{"content": "import logging
from base64 import b64decode, b64encode
from datetime import UTC, datetime
from uuid import uuid4

import requests
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import padding
from django.conf import settings
from django.core.cache import cache

logger = logging.getLogger(__name__)

GATEWAY_TOKEN_CACHE_KEY = "abdm:gateway:token"
CERTIFICATE_CACHE_KEY = "abdm:abha:certificate"
CERTIFICATE_CACHE_TTL = 60 * 60
TOKEN_EXPIRY_MARGIN = 60

GATEWAY_AUTH_FAILURE_CODES = {"900900", "900901", "900902"}

# Keyed by the Java transformation name ABDM publishes beside the key.
ENCRYPTION_PADDINGS = {
    "RSA/ECB/OAEPWithSHA-1AndMGF1Padding": lambda: padding.OAEP(
        mgf=padding.MGF1(algorithm=hashes.SHA1()),  # noqa: S303
        algorithm=hashes.SHA1(),  # noqa: S303
        label=None,
    ),
}


class AbdmError(Exception):
    def __init__(self, message, status=None, code=None, request_id=None):
        super().__init__(message)
        self.message = message
        self.status = status
        self.code = code
        self.request_id = request_id

    def has_code(self, code):
        return self.code == code


def normalize_code(code):
    if code is None:
        return None
    return str(code).strip().rstrip(":").strip() or None


def parse_error(response):
    """Return (code, message) from any of the error shapes ABDM sends."""
    if not response.content:
        return None, f"ABDM returned HTTP {response.status_code} with no body"
    try:
        body = response.json()
    except ValueError:
        return None, response.text[:500]

    if isinstance(body, dict):
        error = body.get("error")
        if isinstance(error, dict):
            return normalize_code(error.get("code")), error.get("message") or ""
        if "code" in body or "message" in body:
            return normalize_code(body.get("code")), body.get("message") or ""
        field_errors = [
            f"{key}: {value}"
            for key, value in body.items()
            if key != "timestamp" and isinstance(value, str)
        ]
        if field_errors:
            return None, "; ".join(field_errors)
    return None, str(body)[:500]


def utc_timestamp():
    return (
        datetime.now(UTC).isoformat(timespec="milliseconds").replace("+00:00", "Z")
    )


def request(method, url, *, headers=None, json=None, params=None, authenticate=True):
    request_id = str(uuid4())
    request_headers = {"REQUEST-ID": request_id, "TIMESTAMP": utc_timestamp()}
    if authenticate:
        request_headers["Authorization"] = f"Bearer {get_gateway_token()}"
    request_headers.update(headers or {})

    logger.info("ABDM %s %s REQUEST-ID=%s", method, url, request_id)
    try:
        response = requests.request(
            method,
            url,
            headers=request_headers,
            json=json,
            params=params,
            timeout=settings.ABDM_REQUEST_TIMEOUT,
        )
    except requests.RequestException as e:
        logger.warning("ABDM %s %s REQUEST-ID=%s failed: %s", method, url, request_id, e)
        raise AbdmError("ABDM could not be reached", request_id=request_id) from e

    if response.status_code >= 400:  # noqa: PLR2004
        code, message = parse_error(response)
        logger.warning(
            "ABDM %s %s REQUEST-ID=%s returned %s %s",
            method,
            url,
            request_id,
            response.status_code,
            code,
        )
        if authenticate and code in GATEWAY_AUTH_FAILURE_CODES:
            # Next call fetches a fresh session instead of retrying this one.
            cache.delete(GATEWAY_TOKEN_CACHE_KEY)
        raise AbdmError(
            message, status=response.status_code, code=code, request_id=request_id
        )
    return response


def get_gateway_token():
    token = cache.get(GATEWAY_TOKEN_CACHE_KEY)
    if token:
        return token
    if not settings.ABDM_CLIENT_ID or not settings.ABDM_CLIENT_SECRET:
        raise AbdmError("ABDM client credentials are not configured")

    body = request(
        "POST",
        f"{settings.ABDM_GATEWAY_URL}/api/hiecm/gateway/v3/sessions",
        headers={"X-CM-ID": settings.ABDM_CM_ID},
        json={
            "clientId": settings.ABDM_CLIENT_ID,
            "clientSecret": settings.ABDM_CLIENT_SECRET,
            "grantType": "client_credentials",
        },
        authenticate=False,
    ).json()
    token = body["accessToken"]
    cache.set(
        GATEWAY_TOKEN_CACHE_KEY,
        token,
        timeout=max(int(body["expiresIn"]) - TOKEN_EXPIRY_MARGIN, 1),
    )
    return token


def get_abha_certificate():
    certificate = cache.get(CERTIFICATE_CACHE_KEY)
    if certificate:
        return certificate
    body = request(
        "GET", f"{settings.ABDM_ABHA_URL}/v3/profile/public/certificate"
    ).json()
    certificate = {
        "public_key": body["publicKey"],
        "algorithm": body["encryptionAlgorithm"],
    }
    cache.set(CERTIFICATE_CACHE_KEY, certificate, timeout=CERTIFICATE_CACHE_TTL)
    return certificate


def encrypt(value):
    certificate = get_abha_certificate()
    build_padding = ENCRYPTION_PADDINGS.get(certificate["algorithm"])
    if build_padding is None:
        raise AbdmError(
            f"Unsupported ABHA encryption algorithm: {certificate['algorithm']}"
        )
    public_key = serialization.load_der_public_key(
        b64decode(certificate["public_key"])
    )
    return b64encode(public_key.encrypt(str(value).encode(), build_padding())).decode()
