{"content": "import datetime
import logging

from django.conf import settings
from django.core.cache import cache

from care.abdm.models import AbhaNumber
from care.abdm.service.client import AbdmError, encrypt, request

logger = logging.getLogger(__name__)

TRANSACTION_TTL = 15 * 60
TOKEN_EXPIRY_MARGIN = 60
ABDM_USER_NOT_FOUND = "ABDM-1114"
ABHA_ENROLMENT_CONSENT = {"code": "abha-enrollment", "version": "1.4"}


class InvalidTransactionError(Exception):
    pass


class AbhaSessionExpiredError(Exception):
    pass


def _url(path):
    return f"{settings.ABDM_ABHA_URL}{path}"


# Transactions: ABDM txnIds bound to the Care user that started them, along
# with any short lived token the next step needs, kept server side.


def _transaction_key(txn_id):
    return f"abdm:m1:transaction:{txn_id}"


def _save_transaction(user, txn_id, flow, **state):
    cache.set(
        _transaction_key(txn_id),
        {"user": user.id, "flow": flow, **state},
        timeout=TRANSACTION_TTL,
    )


def _load_transaction(user, txn_id, *flows):
    state = cache.get(_transaction_key(txn_id)) if txn_id else None
    if not state or state["user"] != user.id or state["flow"] not in flows:
        msg = "The ABHA transaction is invalid or has expired"
        raise InvalidTransactionError(msg)
    return state


def _advance_transaction(user, old_txn_id, new_txn_id, flow, **state):
    new_txn_id = new_txn_id or old_txn_id
    if new_txn_id != old_txn_id:
        cache.delete(_transaction_key(old_txn_id))
    _save_transaction(user, new_txn_id, flow, **state)
    return new_txn_id


# User tokens (X-token and its refresh token), kept in the cache only.


def _ttl(seconds):
    if not seconds:
        return TRANSACTION_TTL
    return max(int(seconds) - TOKEN_EXPIRY_MARGIN, 1)


def _token_key(abha, kind):
    return f"abdm:m1:{kind}:{abha.external_id}"


def _store_user_tokens(abha, tokens):
    cache.set(
        _token_key(abha, "x-token"), tokens["token"], timeout=_ttl(tokens.get("expiresIn"))
    )
    if tokens.get("refreshToken"):
        cache.set(
            _token_key(abha, "r-token"),
            tokens["refreshToken"],
            timeout=_ttl(tokens.get("refreshExpiresIn")),
        )


def _user_token(abha):
    token = cache.get(_token_key(abha, "x-token"))
    if token:
        return token
    refresh_token = cache.get(_token_key(abha, "r-token"))
    if not refresh_token:
        msg = "The ABHA session has expired, the patient has to verify again"
        raise AbhaSessionExpiredError(msg)
    tokens = request(
        "GET",
        _url("/v3/profile/account/request/token"),
        headers={"R-token": f"Bearer {refresh_token}"},
    ).json()
    _store_user_tokens(abha, tokens)
    return tokens["token"]


# Profile


def _parse_date_of_birth(profile):
    try:
        return datetime.date(
            int(profile.get("yearOfBirth")),
            int(profile.get("monthOfBirth")),
            int(profile.get("dayOfBirth")),
        )
    except (TypeError, ValueError):
        return None


def _parse_year_of_birth(profile):
    try:
        return int(profile.get("yearOfBirth"))
    except (TypeError, ValueError):
        return None


def _is_true(value):
    return str(value).lower() == "true"


def _profile_fields(profile):
    name = profile.get("name") or " ".join(
        part
        for part in (
            profile.get("firstName"),
            profile.get("middleName"),
            profile.get("lastName"),
        )
        if part
    )
    return {
        "abha_address": profile.get("preferredAbhaAddress") or "",
        "name": name,
        "gender": profile.get("gender") or "",
        "date_of_birth": _parse_date_of_birth(profile),
        "year_of_birth": _parse_year_of_birth(profile),
        "mobile": profile.get("mobile") or "",
        "address": profile.get("address") or "",
        "pincode": profile.get("pincode") or "",
        "state_code": profile.get("stateCode") or "",
        "state_name": profile.get("stateName") or "",
        "district_code": profile.get("districtCode") or "",
        "district_name": profile.get("districtName") or "",
        "kyc_verified": _is_true(profile.get("kycVerified")),
        "status": profile.get("status") or "",
    }


def _save_profile(user, profile):
    fields = _profile_fields(profile)
    abha, created = AbhaNumber.objects.get_or_create(
        abha_number=profile["ABHANumber"],
        defaults={**fields, "created_by": user, "updated_by": user},
    )
    if not created:
        for field, value in fields.items():
            setattr(abha, field, value)
        abha.updated_by = user
        abha.save()
    return abha


def _fetch_profile(user_token):
    return request(
        "GET", _url("/v3/profile/account"), headers={"X-token": f"Bearer {user_token}"}
    ).json()


def _complete(user, tokens, is_new=False):
    profile = _fetch_profile(tokens["token"])
    abha = _save_profile(user, profile)
    _store_user_tokens(abha, tokens)
    return {
        "abha": abha,
        "is_new": is_new,
        "profile_photo": profile.get("profilePhoto") or None,
    }


def refresh_profile(user, abha):
    profile = _fetch_profile(_user_token(abha))
    abha = _save_profile(user, profile)
    return {"abha": abha, "is_new": False, "profile_photo": profile.get("profilePhoto")}


def _require_success(body, default_message):
    if body.get("authResult") != "success":
        raise AbdmError(body.get("message") or default_message, status=400)


def _account(account):
    return {
        "index": account.get("index"),
        "abha_number": account.get("ABHANumber"),
        "abha_address": account.get("preferredAbhaAddress"),
        "name": account.get("name"),
        "gender": account.get("gender"),
        "kyc_verified": _is_true(account.get("kycVerified")),
        "status": account.get("status"),
        "auth_methods": account.get("authMethods") or [],
    }


# Lookup


def search_by_mobile(user, mobile):
    try:
        body = request(
            "POST",
            _url("/v3/profile/account/abha/search"),
            json={"scope": ["search-abha"], "mobile": encrypt(mobile)},
        ).json()
    except AbdmError as e:
        if e.code == ABDM_USER_NOT_FOUND:
            return []
        raise

    results = []
    for result in body if isinstance(body, list) else [body]:
        accounts = [_account(account) for account in result.get("ABHA") or []]
        _save_transaction(
            user,
            result["txnId"],
            "search",
            indexes=[str(account["index"]) for account in accounts],
        )
        results.append({"txn_id": result["txnId"], "accounts": accounts})
    return results


# Login


def request_login_otp(user, login_hint, otp_system, login_id):
    verify_scope = [
        "abha-login",
        "aadhaar-verify" if otp_system == "aadhaar" else "mobile-verify",
    ]
    body = {"loginHint": login_hint, "otpSystem": otp_system}
    if login_hint == "index":
        txn_id, index = login_id
        state = _load_transaction(user, txn_id, "search")
        if str(index) not in state["indexes"]:
            msg = "The selected account is not part of this search"
            raise InvalidTransactionError(msg)
        body.update(
            scope=["abha-login", "search-abha", verify_scope[1]],
            loginId=encrypt(index),
            txnId=txn_id,
        )
    else:
        body.update(scope=verify_scope, loginId=encrypt(login_id))

    response = request("POST", _url("/v3/profile/login/request/otp"), json=body).json()
    _save_transaction(
        user,
        response["txnId"],
        "login",
        login_hint=login_hint,
        verify_scope=verify_scope,
    )
    return {"txn_id": response["txnId"], "message": response.get("message") or ""}


def verify_login_otp(user, txn_id, otp):
    state = _load_transaction(user, txn_id, "login")
    body = request(
        "POST",
        _url("/v3/profile/login/verify"),
        json={
            "scope": state["verify_scope"],
            "authData": {
                "authMethods": ["otp"],
                "otp": {"txnId": txn_id, "otpValue": encrypt(otp)},
            },
        },
    ).json()
    _require_success(body, "OTP verification failed")

    accounts = body.get("accounts") or []
    if not accounts:
        raise AbdmError("No ABHA account is linked to this identifier", status=404)

    # A mobile login returns a T-token that only selects an account.
    if state["login_hint"] == "mobile" or len(accounts) > 1:
        next_txn_id = _advance_transaction(
            user,
            txn_id,
            body.get("txnId"),
            "select_account",
            t_token=body["token"],
            abha_numbers=[account.get("ABHANumber") for account in accounts],
        )
        return {"txn_id": next_txn_id, "accounts": [_account(a) for a in accounts]}

    cache.delete(_transaction_key(txn_id))
    return _complete(user, body)


def select_account(user, txn_id, abha_number):
    state = _load_transaction(user, txn_id, "select_account")
    if abha_number not in state["abha_numbers"]:
        msg = "The selected ABHA number is not part of this login"
        raise InvalidTransactionError(msg)
    tokens = request(
        "POST",
        _url("/v3/profile/login/verify/user"),
        headers={"T-token": f"Bearer {state['t_token']}"},
        json={"ABHANumber": abha_number, "txnId": txn_id},
    ).json()
    cache.delete(_transaction_key(txn_id))
    return _complete(user, tokens)


# Enrolment


def request_enrolment_otp(user, aadhaar):
    body = request(
        "POST",
        _url("/v3/enrollment/request/otp"),
        json={
            "txnId": "",
            "scope": ["abha-enrol"],
            "loginHint": "aadhaar",
            "loginId": encrypt(aadhaar),
            "otpSystem": "aadhaar",
        },
    ).json()
    _save_transaction(user, body["txnId"], "enrol")
    return {"txn_id": body["txnId"], "message": body.get("message") or ""}


def enrol_with_aadhaar_otp(user, txn_id, otp, mobile):
    _load_transaction(user, txn_id, "enrol")
    body = request(
        "POST",
        _url("/v3/enrollment/enrol/byAadhaar"),
        json={
            "authData": {
                "authMethods": ["otp"],
                "otp": {"txnId": txn_id, "otpValue": encrypt(otp), "mobile": mobile},
            },
            "consent": ABHA_ENROLMENT_CONSENT,
        },
    ).json()
    result = _complete(user, body["tokens"], is_new=_is_true(body.get("isNew")))
    result["txn_id"] = _advance_transaction(
        user, txn_id, body.get("txnId"), "enrolled", abha=result["abha"].id
    )
    return result


def enrol_with_demographics(user, demographics):
    body = request(
        "POST",
        _url("/v3/enrollment/enrol/byAadhaar"),
        headers={"BENEFIT_NAME": settings.ABDM_BENEFIT_NAME},
        json={
            "authData": {
                "authMethods": ["demo_auth"],
                "demo_auth": {
                    **demographics,
                    "aadhaarNumber": encrypt(demographics["aadhaarNumber"]),
                },
            },
            "consent": ABHA_ENROLMENT_CONSENT,
        },
    ).json()
    is_new = _is_true(body.get("new", body.get("isNew")))
    return _complete(user, body.get("jwtResponse") or body["tokens"], is_new=is_new)


def _enrolled_abha(state):
    return AbhaNumber.objects.get(id=state["abha"])


def request_enrolment_mobile_otp(user, txn_id, mobile):
    state = _load_transaction(user, txn_id, "enrolled")
    body = request(
        "POST",
        _url("/v3/enrollment/request/otp"),
        json={
            "txnId": txn_id,
            "scope": ["abha-enrol", "mobile-verify"],
            "loginHint": "mobile",
            "loginId": encrypt(mobile),
            "otpSystem": "abdm",
        },
    ).json()
    next_txn_id = _advance_transaction(
        user, txn_id, body.get("txnId"), "enrolled", abha=state["abha"]
    )
    return {"txn_id": next_txn_id, "message": body.get("message") or ""}


def verify_enrolment_mobile_otp(user, txn_id, otp):
    state = _load_transaction(user, txn_id, "enrolled")
    body = request(
        "POST",
        _url("/v3/enrollment/auth/byAbdm"),
        json={
            "scope": ["abha-enrol", "mobile-verify"],
            "authData": {
                "authMethods": ["otp"],
                "otp": {"txnId": txn_id, "otpValue": encrypt(otp)},
            },
        },
    ).json()
    _require_success(body, "Mobile verification failed")
    result = refresh_profile(user, _enrolled_abha(state))
    result["txn_id"] = _advance_transaction(
        user, txn_id, body.get("txnId"), "enrolled", abha=state["abha"]
    )
    return result


def abha_address_suggestions(user, txn_id):
    _load_transaction(user, txn_id, "enrolled")
    body = request(
        "GET",
        _url("/v3/enrollment/enrol/suggestion"),
        headers={"TRANSACTION_ID": txn_id},
    ).json()
    return {"txn_id": txn_id, "suggestions": body.get("abhaAddressList") or []}


def create_abha_address(user, txn_id, abha_address):
    state = _load_transaction(user, txn_id, "enrolled")
    request(
        "POST",
        _url("/v3/enrollment/enrol/abha-address"),
        json={"txnId": txn_id, "abhaAddress": abha_address, "preferred": 1},
    )
    cache.delete(_transaction_key(txn_id))
    return refresh_profile(user, _enrolled_abha(state))


# Card


def fetch_qr_code(abha):
    return request(
        "GET",
        _url("/v3/profile/account/qrCode"),
        headers={"X-token": f"Bearer {_user_token(abha)}"},
    )


def fetch_abha_card(abha):
    return request(
        "GET",
        _url("/v3/profile/account/abha-card"),
        headers={"X-token": f"Bearer {_user_token(abha)}"},
    )
