{"content": "from django.conf import settings
from django.db import transaction
from django.http import HttpResponse
from drf_spectacular.utils import extend_schema
from rest_framework.decorators import action
from rest_framework.exceptions import PermissionDenied, ValidationError
from rest_framework.permissions import BasePermission
from rest_framework.response import Response
from rest_framework.settings import api_settings

from care.abdm.api.spec import (
    AbhaNumberReadSpec,
    CreateAbhaAddressRequest,
    DemographicEnrolmentRequest,
    EnrolmentMobileOtpRequest,
    EnrolmentOtpRequest,
    EnrolWithAadhaarOtpRequest,
    LinkPatientRequest,
    LoginHint,
    LoginOtpRequest,
    SearchByMobileRequest,
    SelectAccountRequest,
    TransactionRequest,
    VerifyOtpRequest,
)
from care.abdm.models import AbhaNumber
from care.abdm.service import m1
from care.abdm.service.client import GATEWAY_AUTH_FAILURE_CODES, AbdmError
from care.emr.api.viewsets.base import (
    EMRBaseViewSet,
    EMRListMixin,
    EMRRetrieveMixin,
    emr_exception_handler,
)
from care.emr.models import Patient
from care.security.authorization import AuthorizationController
from care.utils.shortcuts import get_object_or_404


class AbdmEnabled(BasePermission):
    message = "ABDM integration is not enabled"

    def has_permission(self, request, view):
        return settings.ABDM_ENABLED


def abdm_exception_handler(exc, context):
    if isinstance(exc, AbdmError):
        is_client_error = (
            exc.status is not None
            and 400 <= exc.status < 500  # noqa: PLR2004
            and exc.code not in GATEWAY_AUTH_FAILURE_CODES
        )
        return Response(
            {
                "errors": [
                    {
                        "type": "abdm_error",
                        "code": exc.code,
                        "msg": exc.message,
                        "request_id": exc.request_id,
                    }
                ]
            },
            status=400 if is_client_error else 502,
        )
    if isinstance(exc, m1.InvalidTransactionError | m1.AbhaSessionExpiredError):
