    data = {
        "abha_number": AbhaNumberReadSpec.serialize(result["abha"]).to_json(),
        "is_new": result["is_new"],
        "profile_photo": result["profile_photo"],
    }
    if "txn_id" in result:
        data["txn_id"] = result["txn_id"]
    return data


