class AbhaNumberViewSet(
    AbdmViewSetMixin, EMRRetrieveMixin, EMRListMixin, EMRBaseViewSet
):
    database_model = AbhaNumber
    pydantic_model = AbhaNumberReadSpec

    def authorize_abha(self, abha):
        user = self.request.user
        if user.is_superuser:
            return
        if abha.patient:
            if not AuthorizationController.call(
                "can_view_patient_obj", user, abha.patient
            ):
                raise PermissionDenied("You do not have access to this patient")
        elif user.id not in (abha.created_by_id, abha.updated_by_id):
            raise PermissionDenied("You do not have access to this ABHA number")

    def authorize_retrieve(self, model_instance):
        self.authorize_abha(model_instance)

    def get_queryset(self):
        queryset = AbhaNumber.objects.select_related("patient").order_by(
            "-modified_date"
        )
        if self.action != "list":
            return queryset
        if patient_id := self.request.query_params.get("patient"):
            patient = get_object_or_404(Patient, external_id=patient_id)
            if not AuthorizationController.call(
                "can_view_patient_obj", self.request.user, patient
            ):
                raise PermissionDenied("You do not have access to this patient")
            return queryset.filter(patient=patient)
        if self.request.user.is_superuser:
            return queryset
        return queryset.filter(patient__isnull=True, updated_by=self.request.user)

    @extend_schema(request=LinkPatientRequest)
    @action(detail=True, methods=["POST"])
    def link_patient(self, request, *args, **kwargs):
        data = LinkPatientRequest.model_validate(request.data)
        with transaction.atomic():
            abha = get_object_or_404(
                AbhaNumber.objects.select_for_update(),
                external_id=kwargs["external_id"],
            )
            self.authorize_abha(abha)
            patient = get_object_or_404(Patient, external_id=data.patient)
            if not AuthorizationController.call(
                "can_write_patient_obj", request.user, patient
            ):
                raise PermissionDenied("You do not have permission to update this patient")
            if abha.patient_id and abha.patient_id != patient.id:
                raise ValidationError("This ABHA number is linked to another patient")
            existing = AbhaNumber.objects.filter(patient=patient).exclude(id=abha.id)
            if existing.exists():
                raise ValidationError("This patient is linked to another ABHA number")
            abha.patient = patient
            abha.updated_by = request.user
            abha.save(update_fields=["patient", "updated_by", "modified_date"])
        return Response(AbhaNumberReadSpec.serialize(abha).to_json())

    @action(detail=True, methods=["POST"])
    def refresh_profile(self, request, *args, **kwargs):
        abha = self.get_object()
        self.authorize_abha(abha)
        return Response(serialize_result(m1.refresh_profile(request.user, abha)))

    @action(detail=True, methods=["GET"])
    def qr_code(self, request, *args, **kwargs):
        abha = self.get_object()
        self.authorize_abha(abha)
        return self._proxy(m1.fetch_qr_code(abha))

    @action(detail=True, methods=["GET"])
    def abha_card(self, request, *args, **kwargs):
        abha = self.get_object()
        self.authorize_abha(abha)
        return self._proxy(m1.fetch_abha_card(abha))

    @staticmethod
    def _proxy(upstream):
        return HttpResponse(
            upstream.content,
            content_type=upstream.headers.get("Content-Type", "application/octet-stream"),
        )
