import { HTTPError } from "@/Utils/request/types";

// The only answer that means nobody holds an ABHA for an identifier.
export const ABDM_USER_NOT_FOUND = "ABDM-1114";

export function getAbhaError(error: unknown, fallback: string): AbhaError {
  if (error instanceof HTTPError) {
    const errors = error.cause?.errors;
    const first = Array.isArray(errors) ? errors[0] : undefined;
    if (first && typeof first === "object") {
      return {
        code: first.code ?? null,
        msg: first.msg || fallback,
        request_id: first.request_id ?? null,
      };
    }
  }
  return { code: null, msg: fallback, request_id: null };
}

export function toIndianMobile(phoneNumber?: string | null) {
  const digits = (phoneNumber ?? "").replace(/\D/g, "");
  if (digits.length === 12 && digits.startsWith("91")) {
    return digits.slice(2);
  }
  return digits.length === 10 ? digits : "";
}

export function abhaGenderToCare(gender: string) {
  return ({ M: "male", F: "female" } as const)[gender];
}

export function getAbhaPhotoSrc(photo: string | null | undefined) {
  if (!photo) {
    return null;
  }
  return photo.startsWith("data:") ? photo : `data:image/jpeg;base64,${photo}`;
}

export function getAbhaDisplayName(abha: AbhaNumber) {
  return abha.abha_address || abha.abha_number;
}
