{"content": "import { BadgeCheckIcon, UserIcon } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";

import { getAbhaPhotoSrc } from "@/components/Abdm/utils";
import { AbhaNumber } from "@/types/abdm/abha";
import { formatDate } from "@/Utils/utils";

interface AbhaProfileSummaryProps {
  abha: AbhaNumber;
  photo?: string | null;
}

export function AbhaProfileSummary({ abha, photo }: AbhaProfileSummaryProps) {
  const { t } = useTranslation();
  const photoSrc = getAbhaPhotoSrc(photo);
  const birth = abha.date_of_birth
    ? formatDate(abha.date_of_birth, "dd MMM yyyy")
    : abha.year_of_birth;
  const location = [abha.district_name, abha.state_name, abha.pincode]
    .filter(Boolean)
    .join(", ");

  return (
    <div className="flex gap-4 items-start">
      <div className="size-16 shrink-0 overflow-hidden rounded-md border border-gray-200 bg-gray-50 flex items-center justify-center">
        {photoSrc ? (
          <img
            src={photoSrc}
            alt={t("abha__profile_photo")}
            className="size-full object-cover"
          />
        ) : (
          <UserIcon className="size-6 text-gray-400" aria-hidden />
        )}
      </div>
      <dl className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-1 text-sm min-w-0">
        <div className="sm:col-span-2 flex items-center gap-2 flex-wrap">
          <dt className="sr-only">{t("name")}</dt>
          <dd className="font-semibold text-gray-900">{abha.name || "-"}</dd>
          {abha.kyc_verified && (
            <Badge variant="green">
              <BadgeCheckIcon aria-hidden />
              {t("abha__kyc_verified")}
            </Badge>
          )}
        </div>
        <div>
          <dt className="text-gray-500">{t("abha__abha_number")}</dt>
          <dd className="font-medium text-gray-900">{abha.abha_number}</dd>
        </div>
        <div>
          <dt className="text-gray-500">{t("abha__abha_address")}</dt>
          <dd className="font-medium text-gray-900 break-all">
            {abha.abha_address || "-"}
          </dd>
        </div>
        <div>
          <dt className="text-gray-500">{t("abha__date_of_birth")}</dt>
          <dd className="text-gray-900">{birth || "-"}</dd>
        </div>
        <div>
          <dt className="text-gray-500">{t("abha__gender")}</dt>
          <dd className="text-gray-900">{abha.gender || "-"}</dd>
        </div>
        {(abha.address || location) && (
          <div className="sm:col-span-2">
            <dt className="text-gray-500">{t("address")}</dt>
            <dd className="text-gray-900">
              {[abha.address, location].filter(Boolean).join(" — ")}
            </dd>
          </div>
        )}
