{"content": "import { useQuery } from "@tanstack/react-query";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp";
import { Label } from "@/components/ui/label";
import RadioInput from "@/components/ui/RadioInput";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";

import {
  AbhaAccount,
  AbhaDemographicEnrolmentRequest,
  AbhaOtpSystem,
} from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import { callApi } from "@/Utils/request/query";
import careConfig from "@careConfig";

export type AbhaIdentifier = "mobile" | "aadhaar" | "abha_number";

export interface AbhaFacts {
  mobile: string;
  mobileFromForm: boolean;
  aadhaar: string;
  abhaNumber: string;
  termsAccepted: boolean;
}

export interface SearchedAbhaAccount extends AbhaAccount {
  txn_id: string;
}

const OTP_LENGTH = 6;
const RESEND_WAIT_SECONDS = 60;
const isMobile = (value: string) => /^\d{10}$/.test(value);
const isAadhaar = (value: string) => /^\d{12}$/.test(value);
const isAbhaNumber = (value: string) => /^\d{14}$/.test(value.replace(/-/g, ""));

const OTP_SYSTEM_BY_AUTH_METHOD: Record<string, AbhaOtpSystem> = {
  AADHAAR_OTP: "aadhaar",
  MOBILE_OTP: "abdm",
};

function FieldHint({ children }: { children: React.ReactNode }) {
  return <p className="text-xs text-gray-500">{children}</p>;
}

function StepActions({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex flex-col-reverse sm:flex-row sm:justify-end gap-2 pt-2">
      {children}
    </div>
  );
}

export function AbhaTermsConsent({
  checked,
  onCheckedChange,
}: {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
}) {
  const { t } = useTranslation();
  return (
    <div className="flex flex-col gap-2 rounded-md border border-gray-200 bg-gray-50 p-3">
      <p className="text-sm font-semibold">{t("abha__terms_title")}</p>
      <div className="max-h-32 overflow-y-auto text-xs text-gray-700 whitespace-pre-line">
        {t("abha__enrolment_terms")}
      </div>
      <div className="flex items-start gap-2">
        <Checkbox
          id="abha-terms"
          checked={checked}
          onCheckedChange={(value) => onCheckedChange(value === true)}
        />
        <Label htmlFor="abha-terms" className="text-sm leading-snug">
          {t("abha__terms_agree")}
        </Label>
      </div>
    </div>
  );
}

interface IdentifyStepProps {
  facts: AbhaFacts;
  identifier: AbhaIdentifier;
  notice?: string;
  busy: boolean;
  onMobile: (mobile: string) => void;
  onAadhaar: (
    aadhaar: string,
    termsAccepted: boolean,
    method: "otp" | "demographic",
  ) => void;
  onAbhaNumber: (abhaNumber: string, otpSystem: AbhaOtpSystem) => void;
  onNotNow: () => void;
}

export function IdentifyStep({
  facts,
  identifier: initialIdentifier,
  notice,
  busy,
  onMobile,
  onAadhaar,
  onAbhaNumber,
  onNotNow,
}: IdentifyStepProps) {
  const { t } = useTranslation();
  const [identifier, setIdentifier] = useState(initialIdentifier);
  const [mobile, setMobile] = useState(facts.mobile);
  const [aadhaar, setAadhaar] = useState(facts.aadhaar);
  const [termsAccepted, setTermsAccepted] = useState(facts.termsAccepted);
  const [abhaNumber, setAbhaNumber] = useState(facts.abhaNumber);
  const [aadhaarMethod, setAadhaarMethod] = useState<"otp" | "demographic">(
    "otp",
  );
  const [abhaOtpSystem, setAbhaOtpSystem] = useState<AbhaOtpSystem>("abdm");

  const canContinue = {
    mobile: isMobile(mobile),
    aadhaar: isAadhaar(aadhaar) && termsAccepted,
    abha_number: isAbhaNumber(abhaNumber),
  }[identifier];

  const handleContinue = () => {
    if (identifier === "mobile") onMobile(mobile);
    if (identifier === "aadhaar") onAadhaar(aadhaar, termsAccepted, aadhaarMethod);
    if (identifier === "abha_number") {
      onAbhaNumber(abhaNumber.replace(/-/g, ""), abhaOtpSystem);
    }
  };

  return (
    <form
      className="flex flex-col gap-4"
      onSubmit={(e) => {
        e.preventDefault();
        if (canContinue && !busy) handleContinue();
      }}
    >
      {notice && (
        <p className="rounded-md bg-blue-50 border border-blue-200 p-3 text-sm text-blue-900">
          {notice}
        </p>
      )}
      <div className="flex flex-col gap-2">
        <Label>{t("abha__identify_with")}</Label>
        <Tabs
          value={identifier}
          onValueChange={(value) => setIdentifier(value as AbhaIdentifier)}
        >
          <TabsList className="w-full">
            <TabsTrigger value="mobile" className="flex-1">
              {t("mobile_number")}
            </TabsTrigger>
            <TabsTrigger value="aadhaar" className="flex-1">
              {t("aadhaar_number")}
            </TabsTrigger>
            <TabsTrigger value="abha_number" className="flex-1">
              {t("abha__abha_number")}
            </TabsTrigger>
          </TabsList>
        </Tabs>
      </div>

      {identifier === "mobile" && (
        <div className="flex flex-col gap-2">
          <Label htmlFor="abha-mobile">{t("mobile_number")}</Label>
          <Input
            id="abha-mobile"
            inputMode="numeric"
            autoComplete="off"
            maxLength={10}
            value={mobile}
            onChange={(e) => setMobile(e.target.value.replace(/\D/g, ""))}
            placeholder={t("abha__mobile_placeholder")}
          />
          {facts.mobileFromForm && mobile === facts.mobile && (
            <FieldHint>{t("abha__from_registration_form")}</FieldHint>
          )}
          <FieldHint>{t("abha__mobile_lookup_hint")}</FieldHint>
        </div>
      )}

      {identifier === "aadhaar" && (
        <div className="flex flex-col gap-3">
          <div className="flex flex-col gap-2">
            <Label htmlFor="abha-aadhaar">{t("aadhaar_number")}</Label>
            <Input
              id="abha-aadhaar"
              inputMode="numeric"
              autoComplete="off"
              maxLength={12}
              value={aadhaar}
              onChange={(e) => setAadhaar(e.target.value.replace(/\D/g, ""))}
              placeholder={t("abha__aadhaar_placeholder")}
            />
          </div>
          {careConfig.abdm.demographicAuth && (
            <div className="flex flex-col gap-2">
              <Label>{t("abha__verify_using")}</Label>
              <RadioInput
                value={aadhaarMethod}
                onValueChange={(value) =>
                  value && setAadhaarMethod(value as "otp" | "demographic")
                }
                options={[
                  { value: "otp", label: t("abha__method_aadhaar_otp") },
                  {
                    value: "demographic",
                    label: t("abha__method_demographic"),
                  },
                ]}
              />
            </div>
          )}
          <AbhaTermsConsent
            checked={termsAccepted}
            onCheckedChange={setTermsAccepted}
          />
        </div>
      )}

      {identifier === "abha_number" && (
        <div className="flex flex-col gap-3">
          <div className="flex flex-col gap-2">
            <Label htmlFor="abha-number">{t("abha__abha_number")}</Label>
            <Input
              id="abha-number"
              autoComplete="off"
              maxLength={17}
              value={abhaNumber}
              onChange={(e) =>
                setAbhaNumber(e.target.value.replace(/[^\d-]/g, ""))
              }
              placeholder="91-XXXX-XXXX-XXXX"
            />
          </div>
          <div className="flex flex-col gap-2">
            <Label>{t("abha__verify_using")}</Label>
            <RadioInput
              value={abhaOtpSystem}
              onValueChange={(value) =>
                value && setAbhaOtpSystem(value as AbhaOtpSystem)
              }
              options={[
                { value: "abdm", label: t("abha__method_mobile_otp") },
                { value: "aadhaar", label: t("abha__method_aadhaar_otp") },
              ]}
            />
          </div>
        </div>
      )}

      <StepActions>
        <Button type="button" variant="outline" onClick={onNotNow}>
          {t("abha__not_now")}
        </Button>
        <Button type="submit" variant="primary" disabled={!canContinue || busy}>
          {t("continue")}
        </Button>
      </StepActions>
    </form>
  );
}

function AccountOption({ account }: { account: AbhaAccount }) {
  const { t } = useTranslation();
  return (
    <span className="flex flex-wrap items-center gap-2">
      <span className="font-medium">{account.name || "-"}</span>
      <span className="text-gray-600">{account.abha_number}</span>
      {account.gender && <span className="text-gray-500">{account.gender}</span>}
      {account.kyc_verified && (
        <Badge variant="green">{t("abha__kyc_verified")}</Badge>
      )}
    </span>
  );
}

interface SearchAccountsStepProps {
  mobile: string;
  accounts: SearchedAbhaAccount[];
  busy: boolean;
  onSendOtp: (account: SearchedAbhaAccount, otpSystem: AbhaOtpSystem) => void;
  onNone: () => void;
  onBack: () => void;
}

export function SearchAccountsStep({
  mobile,
  accounts,
  busy,
  onSendOtp,
  onNone,
  onBack,
}: SearchAccountsStepProps) {
  const { t } = useTranslation();
  const [selected, setSelected] = useState(accounts.length === 1 ? 0 : -1);
  const account = accounts[selected];
  const otpSystems = (account?.auth_methods ?? [])
    .map((method) => OTP_SYSTEM_BY_AUTH_METHOD[method])
    .filter(Boolean);
  const [otpSystem, setOtpSystem] = useState<AbhaOtpSystem | null>(null);
  const chosenOtpSystem =
    otpSystem && otpSystems.includes(otpSystem) ? otpSystem : otpSystems[0];

  return (
    <div className="flex flex-col gap-4">
      <p className="text-sm text-gray-700">
        {t("abha__accounts_on_mobile", { count: accounts.length, mobile })}
      </p>
      <RadioInput
        className="flex-col"
        value={selected >= 0 ? String(selected) : ""}
        onValueChange={(value) => setSelected(value === "" ? -1 : Number(value))}
        options={accounts.map((a, i) => ({
          value: String(i),
          label: `${a.name || "-"} · ${a.abha_number}${a.kyc_verified ? ` · ${t("abha__kyc_verified")}` : ""}`,
        }))}
      />
      {account && otpSystems.length === 0 && (
        <p className="text-sm text-amber-800">{t("abha__no_otp_method")}</p>
      )}
      {account && otpSystems.length > 1 && (
        <div className="flex flex-col gap-2">
          <Label>{t("abha__verify_using")}</Label>
          <RadioInput
            value={chosenOtpSystem}
            onValueChange={(value) => value && setOtpSystem(value as AbhaOtpSystem)}
            options={otpSystems.map((system) => ({
              value: system,
              label:
                system === "aadhaar"
                  ? t("abha__method_aadhaar_otp")
                  : t("abha__method_mobile_otp"),
            }))}
          />
        </div>
      )}
      <StepActions>
        <Button type="button" variant="ghost" onClick={onBack}>
          {t("back")}
        </Button>
        <Button type="button" variant="outline" onClick={onNone}>
          {t("abha__none_of_these")}
        </Button>
        <Button
          type="button"
          variant="primary"
          disabled={!account || !chosenOtpSystem || busy}
          onClick={() => onSendOtp(account, chosenOtpSystem)}
        >
          {t("send_otp")}
        </Button>
      </StepActions>
    </div>
  );
}

interface SelectAccountStepProps {
  accounts: AbhaAccount[];
  busy: boolean;
  onSelect: (abhaNumber: string) => void;
}

export function SelectAccountStep({
  accounts,
  busy,
  onSelect,
}: SelectAccountStepProps) {
  const { t } = useTranslation();
  const [selected, setSelected] = useState(
    accounts.length === 1 ? accounts[0].abha_number : "",
  );
  return (
    <div className="flex flex-col gap-4">
      <p className="text-sm text-gray-700">{t("abha__choose_account")}</p>
      <ul className="flex flex-col gap-2">
        {accounts.map((account) => (
          <li key={account.abha_number}>
            <label className="flex items-center gap-3 rounded-md border border-gray-200 p-3 cursor-pointer has-checked:border-primary-500 has-checked:bg-primary-50">
              <input
                type="radio"
                name="abha-account"
                className="accent-primary-700"
                checked={selected === account.abha_number}
                onChange={() => setSelected(account.abha_number)}
              />
              <AccountOption account={account} />
            </label>
          </li>
        ))}
      </ul>
      <StepActions>
        <Button
          type="button"
          variant="primary"
          disabled={!selected || busy}
          onClick={() => onSelect(selected)}
        >
          {t("continue")}
        </Button>
      </StepActions>
    </div>
  );
}

interface OtpStepProps {
  message: string;
  notice?: string;
  askMobile: boolean;
  facts: AbhaFacts;
  busy: boolean;
  onVerify: (otp: string, mobile: string) => void;
  onResend: () => Promise<boolean>;
  onBack?: () => void;
}

export function OtpStep({
  message,
  notice,
  askMobile,
  facts,
  busy,
  onVerify,
  onResend,
  onBack,
}: OtpStepProps) {
  const { t } = useTranslation();
  const [otp, setOtp] = useState("");
  const [mobile, setMobile] = useState(facts.mobile);
  const [wait, setWait] = useState(RESEND_WAIT_SECONDS);

  useEffect(() => {
    if (wait <= 0) return;
    const timer = setTimeout(() => setWait(wait - 1), 1000);
    return () => clearTimeout(timer);
  }, [wait]);

  const canVerify = otp.length === OTP_LENGTH && (!askMobile || isMobile(mobile));

  return (
    <form
      className="flex flex-col gap-4"
      onSubmit={(e) => {
        e.preventDefault();
        if (canVerify && !busy) onVerify(otp, mobile);
      }}
    >
      {notice && (
        <p className="rounded-md bg-blue-50 border border-blue-200 p-3 text-sm text-blue-900">
          {notice}
        </p>
      )}
      <p className="text-sm text-gray-700" aria-live="polite">
        {message || t("abha__otp_sent")}
      </p>
      <div className="flex flex-col gap-2">
        <Label htmlFor="abha-otp">{t("abha__enter_otp")}</Label>
        <InputOTP
          id="abha-otp"
          maxLength={OTP_LENGTH}
          value={otp}
          onChange={setOtp}
          autoFocus
        >
          <InputOTPGroup>
            {Array.from({ length: OTP_LENGTH }, (_, i) => (
              <InputOTPSlot key={i} index={i} />
            ))}
          </InputOTPGroup>
        </InputOTP>
        <div>
          <Button
            type="button"
            variant="link"
            className="px-0"
            disabled={wait > 0 || busy}
            onClick={async () => {
              if (await onResend()) {
                setOtp("");
                setWait(RESEND_WAIT_SECONDS);
              }
            }}
          >
            {wait > 0
              ? t("abha__resend_in", { seconds: wait })
              : t("resend_otp")}
          </Button>
        </div>
      </div>
      {askMobile && (
        <div className="flex flex-col gap-2">
          <Label htmlFor="abha-enrol-mobile">{t("abha__mobile_to_link")}</Label>
          <Input
            id="abha-enrol-mobile"
            inputMode="numeric"
            maxLength={10}
            value={mobile}
            onChange={(e) => setMobile(e.target.value.replace(/\D/g, ""))}
          />
          {facts.mobile && mobile === facts.mobile && (
            <FieldHint>{t("abha__mobile_already_given")}</FieldHint>
          )}
        </div>
      )}
      <StepActions>
        {onBack && (
          <Button type="button" variant="ghost" onClick={onBack}>
            {t("back")}
          </Button>
        )}
        <Button type="submit" variant="primary" disabled={!canVerify || busy}>
          {t("verify_otp")}
        </Button>
      </StepActions>
    </form>
  );
}

interface LinkMobileStepProps {
  mobile: string;
  busy: boolean;
  onVerifyMobile: () => void;
  onSkip: () => void;
}

export function LinkMobileStep({
  mobile,
  busy,
  onVerifyMobile,
  onSkip,
}: LinkMobileStepProps) {
  const { t } = useTranslation();
  return (
    <div className="flex flex-col gap-4">
      <p className="text-sm text-gray-700">
        {t("abha__mobile_not_linked", { mobile })}
      </p>
      <StepActions>
        <Button type="button" variant="outline" onClick={onSkip}>
          {t("abha__skip")}
        </Button>
        <Button
          type="button"
          variant="primary"
          disabled={busy}
          onClick={onVerifyMobile}
        >
          {t("send_otp")}
        </Button>
      </StepActions>
    </div>
  );
}

interface AddressStepProps {
  txnId: string;
  busy: boolean;
  onCreate: (abhaAddress: string) => void;
  onSkip: () => void;
}

export function AddressStep({ txnId, busy, onCreate, onSkip }: AddressStepProps) {
  const { t } = useTranslation();
  const [address, setAddress] = useState("");
  const { data, isLoading } = useQuery({
    queryKey: ["abha-address-suggestions", txnId],
    queryFn: () =>
      callApi(abhaApi.enrolAddressSuggestions, {
        body: { txn_id: txnId },
        silent: true,
      }),
    retry: false,
  });

  return (
    <form
      className="flex flex-col gap-4"
      onSubmit={(e) => {
        e.preventDefault();
        if (address && !busy) onCreate(address);
      }}
    >
      <p className="text-sm text-gray-700">{t("abha__address_intro")}</p>
      {isLoading && <FieldHint>{t("loading")}</FieldHint>}
      {!!data?.suggestions.length && (
        <div className="flex flex-wrap gap-2">
          {data.suggestions.map((suggestion) => (
            <Button
              key={suggestion}
              type="button"
              size="sm"
              variant={suggestion === address ? "primary" : "outline"}
              onClick={() => setAddress(suggestion)}
            >
              {suggestion}
            </Button>
          ))}
        </div>
      )}
      <div className="flex flex-col gap-2">
        <Label htmlFor="abha-address">{t("abha__abha_address")}</Label>
        <Input
          id="abha-address"
          autoComplete="off"
          value={address}
          onChange={(e) => setAddress(e.target.value.trim())}
        />
        <FieldHint>{t("abha__address_hint")}</FieldHint>
      </div>
      <StepActions>
        <Button type="button" variant="outline" onClick={onSkip}>
          {t("abha__skip")}
        </Button>
        <Button type="submit" variant="primary" disabled={!address || busy}>
          {t("abha__create_address")}
        </Button>
      </StepActions>
    </form>
  );
}

type Demographics = Omit<
  AbhaDemographicEnrolmentRequest,
  "aadhaar" | "terms_accepted"
>;

interface DemographicStepProps {
  facts: AbhaFacts;
  busy: boolean;
  onSubmit: (demographics: Demographics) => void;
  onBack: () => void;
}

export function DemographicStep({
  facts,
  busy,
  onSubmit,
  onBack,
}: DemographicStepProps) {
  const { t } = useTranslation();
  const [values, setValues] = useState<Demographics>({
    name: "",
    gender: "" as Demographics["gender"],
    date_of_birth: "",
    state_code: "",
    district_code: "",
    mobile: facts.mobile,
    pincode: "",
    address: "",
  });
  const set = (field: keyof Demographics) => (value: string) =>
    setValues((current) => ({ ...current, [field]: value }));
  const canSubmit =
    !!values.name &&
    !!values.gender &&
    !!values.date_of_birth &&
    !!values.state_code &&
    !!values.district_code &&
    (!values.mobile || isMobile(values.mobile));

  return (
    <form
      className="flex flex-col gap-4"
      onSubmit={(e) => {
        e.preventDefault();
        if (canSubmit && !busy) {
          onSubmit({
            ...values,
            mobile: values.mobile || undefined,
            pincode: values.pincode || undefined,
            address: values.address || undefined,
          });
        }
      }}
    >
      <p className="text-sm text-gray-700">{t("abha__demographic_intro")}</p>
      <div className="flex flex-col gap-2">
        <Label htmlFor="abha-demo-name" aria-required>
          {t("abha__name_as_in_aadhaar")}
        </Label>
        <Input
          id="abha-demo-name"
          value={values.name}
          onChange={(e) => set("name")(e.target.value)}
        />
      </div>
      <div className="flex flex-col gap-2">
        <Label aria-required>{t("abha__gender")}</Label>
        <RadioInput
          value={values.gender}
          onValueChange={set("gender")}
          options={[
            { value: "M", label: t("GENDER__male") },
            { value: "F", label: t("GENDER__female") },
            { value: "O", label: t("abha__gender_other") },
          ]}
        />
      </div>
      <div className="flex flex-col gap-2">
        <Label htmlFor="abha-demo-dob" aria-required>
          {t("abha__date_of_birth")}
        </Label>
        <Input
          id="abha-demo-dob"
          type="date"
          value={values.date_of_birth}
          onChange={(e) => set("date_of_birth")(e.target.value)}
        />
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="flex flex-col gap-2">
          <Label htmlFor="abha-demo-state" aria-required>
            {t("abha__lgd_state_code")}
          </Label>
          <Input
            id="abha-demo-state"
            inputMode="numeric"
            value={values.state_code}
            onChange={(e) => set("state_code")(e.target.value.replace(/\D/g, ""))}
          />
        </div>
        <div className="flex flex-col gap-2">
          <Label htmlFor="abha-demo-district" aria-required>
            {t("abha__lgd_district_code")}
          </Label>
          <Input
            id="abha-demo-district"
            inputMode="numeric"
            value={values.district_code}
            onChange={(e) =>
              set("district_code")(e.target.value.replace(/\D/g, ""))
            }
          />
        </div>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="flex flex-col gap-2">
          <Label htmlFor="abha-demo-mobile">{t("mobile_number")}</Label>
          <Input
            id="abha-demo-mobile"
            inputMode="numeric"
            maxLength={10}
            value={values.mobile}
            onChange={(e) => set("mobile")(e.target.value.replace(/\D/g, ""))}
          />
          {facts.mobile && values.mobile === facts.mobile && (
            <FieldHint>{t("abha__mobile_already_given")}</FieldHint>
          )}
        </div>
        <div className="flex flex-col gap-2">
          <Label htmlFor="abha-demo-pincode">{t("pincode")}</Label>
          <Input
            id="abha-demo-pincode"
            inputMode="numeric"
            maxLength={6}
            value={values.pincode}
            onChange={(e) => set("pincode")(e.target.value.replace(/\D/g, ""))}
          />
        </div>
      </div>
      <div className="flex flex-col gap-2">
        <Label htmlFor="abha-demo-address">{t("address")}</Label>
        <Textarea
          id="abha-demo-address"
          value={values.address}
          onChange={(e) => set("address")(e.target.value)}
        />
      </div>
      <StepActions>
        <Button type="button" variant="ghost" onClick={onBack}>
          {t("back")}
        </Button>
        <Button type="submit" variant="primary" disabled={!canSubmit || busy}>
          {t("abha__create_abha")}
        </Button>
      </StepActions>
    </form>
  );
}
