{"content": "import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

import {
  AbhaFacts,
  AbhaIdentifier,
  AddressStep,
  DemographicStep,
  IdentifyStep,
  LinkMobileStep,
  OtpStep,
  SearchAccountsStep,
  SearchedAbhaAccount,
  SelectAccountStep,
} from "@/components/Abdm/AbhaVerificationSteps";
import { ABDM_USER_NOT_FOUND, getAbhaError } from "@/components/Abdm/utils";
import {
  AbhaAccount,
  AbhaError,
  AbhaLoginOtpRequest,
  AbhaOtpSent,
  AbhaVerified,
} from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import { callApi } from "@/Utils/request/query";
import { ApiRoute } from "@/Utils/request/types";

type OtpMode = "login" | "enrol" | "enrol_mobile";

type Step =
  | { name: "identify"; identifier: AbhaIdentifier; notice?: string }
  | { name: "search_accounts"; accounts: SearchedAbhaAccount[] }
  | { name: "select_account"; txnId: string; accounts: AbhaAccount[] }
  | {
      name: "otp";
      mode: OtpMode;
      txnId: string;
      message: string;
      notice?: string;
      resend: (txnId: string) => Promise<AbhaOtpSent>;
    }
  | { name: "demographic" }
  | { name: "link_mobile"; txnId: string; result: AbhaVerified }
  | { name: "address"; txnId: string; result: AbhaVerified };

interface AbhaVerificationDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** The patient's 10 digit mobile, when the desk already holds it */
  mobile?: string;
  onVerified: (result: AbhaVerified) => void;
}

export function AbhaVerificationDialog({
  open,
  onOpenChange,
  mobile,
  onVerified,
}: AbhaVerificationDialogProps) {
  const { t } = useTranslation();
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{t("abha__dialog_title")}</DialogTitle>
          <DialogDescription>{t("abha__dialog_description")}</DialogDescription>
        </DialogHeader>
        {open && (
          <AbhaFlow
            initialMobile={mobile}
            onClose={() => onOpenChange(false)}
            onVerified={(result) => {
              onVerified(result);
              onOpenChange(false);
            }}
          />
        )}
      </DialogContent>
    </Dialog>
  );
}

function api<Route extends ApiRoute<unknown, unknown>>(
  route: Route,
  body: Route["TBody"],
) {
  return callApi(route, { body, silent: true });
}

function AbhaFlow({
  initialMobile,
  onClose,
  onVerified,
}: {
  initialMobile?: string;
  onClose: () => void;
  onVerified: (result: AbhaVerified) => void;
}) {
  const { t } = useTranslation();
  const [facts, setFacts] = useState<AbhaFacts>({
    mobile: initialMobile ?? "",
    mobileFromForm: !!initialMobile,
    aadhaar: "",
    abhaNumber: "",
    termsAccepted: false,
  });
  const [step, setStepState] = useState<Step>({
    name: "identify",
    identifier: initialMobile ? "mobile" : "aadhaar",
  });
  const [error, setError] = useState<AbhaError | null>(null);
  const [busy, setBusy] = useState(false);
  const [created, setCreated] = useState(false);

  const setStep = (next: Step) => {
    setError(null);
    setStepState(next);
  };

  const backToIdentify = (identifier: AbhaIdentifier) =>
    setStep({ name: "identify", identifier });

  const run = async (action: () => Promise<void>) => {
    setBusy(true);
    setError(null);
    try {
      await action();
      return true;
    } catch (e) {
      setError(getAbhaError(e, t("abha__request_failed")));
      return false;
    } finally {
      setBusy(false);
    }
  };

  const finish = (result: AbhaVerified) =>
    onVerified({ ...result, is_new: result.is_new || created });

  const startLoginOtp = async (body: AbhaLoginOtpRequest) => {
    const send = () => api(abhaApi.loginSendOtp, body);
    const sent = await send();
    setStep({
      name: "otp",
      mode: "login",
      txnId: sent.txn_id,
      message: sent.message,
      resend: send,
    });
  };

  const startEnrolment = async (aadhaar: string) => {
    const send = () =>
      api(abhaApi.enrolSendAadhaarOtp, { aadhaar, terms_accepted: true });
    const sent = await send();
    setStep({
      name: "otp",
      mode: "enrol",
      txnId: sent.txn_id,
      message: sent.message,
      notice: t("abha__no_abha_for_aadhaar"),
      resend: send,
    });
  };

  const continueEnrolment = (result: AbhaVerified, mobileHandled: boolean) => {
    const txnId = result.txn_id;
    if (!txnId) {
      finish(result);
    } else if (!mobileHandled && !result.abha_number.mobile && facts.mobile) {
      setStep({ name: "link_mobile", txnId, result });
    } else if (!result.abha_number.abha_address) {
      setStep({ name: "address", txnId, result });
    } else {
      finish(result);
    }
  };

  const handleMobile = (mobile: string) =>
    run(async () => {
      setFacts((current) => ({
        ...current,
        mobile,
        mobileFromForm: current.mobileFromForm && current.mobile === mobile,
      }));
      const { results } = await api(abhaApi.searchByMobile, { mobile });
      const accounts = results.flatMap((result) =>
        result.accounts.map((account) => ({ ...account, txn_id: result.txn_id })),
      );
      if (accounts.length) {
        setStep({ name: "search_accounts", accounts });
      } else {
        setStep({
          name: "identify",
          identifier: "aadhaar",
          notice: t("abha__no_abha_for_mobile", { mobile }),
        });
      }
    });

  const handleAadhaar = (
    aadhaar: string,
    termsAccepted: boolean,
    method: "otp" | "demographic",
  ) => {
    setFacts((current) => ({ ...current, aadhaar, termsAccepted }));
    if (method === "demographic") {
      setStep({ name: "demographic" });
      return;
    }
    run(async () => {
      try {
        await startLoginOtp({
          login_hint: "aadhaar",
          otp_system: "aadhaar",
          value: aadhaar,
        });
      } catch (e) {
        if (getAbhaError(e, "").code !== ABDM_USER_NOT_FOUND) throw e;
        await startEnrolment(aadhaar);
      }
    });
  };

  const handleAbhaNumber = (abhaNumber: string, otpSystem: "aadhaar" | "abdm") =>
    run(async () => {
      setFacts((current) => ({ ...current, abhaNumber }));
      await startLoginOtp({
        login_hint: "abha-number",
        otp_system: otpSystem,
        value: abhaNumber,
      });
    });

  const handleVerifyOtp = (
    current: Extract<Step, { name: "otp" }>,
    otp: string,
    mobile: string,
  ) =>
    run(async () => {
      if (current.mode === "login") {
        const response = await api(abhaApi.loginVerifyOtp, {
          txn_id: current.txnId,
          otp,
        });
        if (response.status === "select_account") {
          setStep({
            name: "select_account",
            txnId: response.txn_id,
            accounts: response.accounts,
          });
        } else {
          finish(response);
        }
        return;
      }
      if (current.mode === "enrol") {
        setFacts((existing) => ({ ...existing, mobile }));
        const result = await api(abhaApi.enrolVerifyAadhaarOtp, {
          txn_id: current.txnId,
          otp,
          mobile,
        });
        setCreated(result.is_new);
        if (result.is_new) {
          continueEnrolment(result, false);
        } else {
          finish(result);
        }
        return;
      }
      const result = await api(abhaApi.enrolVerifyMobileOtp, {
        txn_id: current.txnId,
        otp,
      });
      continueEnrolment(result, true);
    });

  const handleResend = (current: Extract<Step, { name: "otp" }>) =>
    run(async () => {
      const sent = await current.resend(current.txnId);
      setStepState({ ...current, txnId: sent.txn_id, message: sent.message });
    });

  const renderStep = () => {
    switch (step.name) {
      case "identify":
        return (
          <IdentifyStep
            key={`${step.identifier}-${step.notice ?? ""}`}
            facts={facts}
            identifier={step.identifier}
            notice={step.notice}
            busy={busy}
            onMobile={handleMobile}
            onAadhaar={handleAadhaar}
            onAbhaNumber={handleAbhaNumber}
            onNotNow={onClose}
          />
        );
      case "search_accounts":
        return (
          <SearchAccountsStep
            mobile={facts.mobile}
            accounts={step.accounts}
            busy={busy}
            onSendOtp={(account, otpSystem) =>
              run(() =>
                startLoginOtp({
                  login_hint: "index",
                  otp_system: otpSystem,
                  value: String(account.index),
                  txn_id: account.txn_id,
                }),
              )
            }
            onNone={() =>
              setStep({
                name: "identify",
                identifier: "aadhaar",
                notice: t("abha__create_with_aadhaar"),
              })
            }
            onBack={() => backToIdentify("mobile")}
          />
        );
      case "select_account":
        return (
          <SelectAccountStep
            accounts={step.accounts}
            busy={busy}
            onSelect={(abhaNumber) =>
              run(async () => {
                finish(
                  await api(abhaApi.loginSelectAccount, {
                    txn_id: step.txnId,
                    abha_number: abhaNumber,
                  }),
                );
              })
            }
          />
        );
      case "otp":
        return (
          <OtpStep
            key={`${step.mode}-${step.txnId}`}
            message={step.message}
            notice={step.notice}
            askMobile={step.mode === "enrol"}
            facts={facts}
            busy={busy}
            onVerify={(otp, mobile) => handleVerifyOtp(step, otp, mobile)}
            onResend={() => handleResend(step)}
            onBack={
              step.mode === "enrol_mobile"
                ? undefined
                : () => backToIdentify(facts.aadhaar ? "aadhaar" : "mobile")
            }
          />
        );
      case "demographic":
        return (
          <DemographicStep
            facts={facts}
            busy={busy}
            onBack={() => backToIdentify("aadhaar")}
            onSubmit={(demographics) =>
              run(async () => {
                const result = await api(abhaApi.enrolDemographic, {
                  ...demographics,
                  aadhaar: facts.aadhaar,
                  terms_accepted: true,
                });
                finish(result);
              })
            }
          />
        );
      case "link_mobile":
        return (
          <LinkMobileStep
            mobile={facts.mobile}
            busy={busy}
            onSkip={() => continueEnrolment(step.result, true)}
            onVerifyMobile={() =>
              run(async () => {
                const send = (txnId: string) =>
                  api(abhaApi.enrolSendMobileOtp, {
                    txn_id: txnId,
                    mobile: facts.mobile,
                  });
                const sent = await send(step.txnId);
                setStep({
                  name: "otp",
                  mode: "enrol_mobile",
                  txnId: sent.txn_id,
                  message: sent.message,
                  resend: send,
                });
              })
            }
          />
        );
      case "address":
        return (
          <AddressStep
            txnId={step.txnId}
            busy={busy}
            onSkip={() => finish(step.result)}
            onCreate={(abhaAddress) =>
              run(async () => {
                finish(
                  await api(abhaApi.enrolCreateAddress, {
                    txn_id: step.txnId,
                    abha_address: abhaAddress,
                  }),
                );
              })
            }
          />
        );
    }
  };

  return (
    <div className="flex flex-col gap-4">
      {error && (
        <Alert variant="destructive" role="alert">
          <AlertTitle>{error.msg}</AlertTitle>
          {(error.code || error.request_id) && (
            <AlertDescription className="text-xs">
              {[error.code, error.request_id && `${t("abha__request_id")}: ${error.request_id}`]
                .filter(Boolean)
                .join(" · ")}
            </AlertDescription>
          )}
        </Alert>
      )}
      {renderStep()}
    </div>
  );
}
