{"content": "import { IdCardIcon, XIcon } from "lucide-react";
import { navigate } from "raviger";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import { AbhaProfileSummary } from "@/components/Abdm/AbhaProfileSummary";
import { AbhaVerificationDialog } from "@/components/Abdm/AbhaVerificationDialog";
import { toIndianMobile } from "@/components/Abdm/utils";
import { AbhaVerified } from "@/types/abdm/abha";

interface AbhaRegistrationPanelProps {
  facilityId?: string;
  phoneNumber?: string;
  value: AbhaVerified | null;
  filledFields: string[];
  keptFields: string[];
  onVerified: (result: AbhaVerified) => void;
  onClear: () => void;
}

export function AbhaRegistrationPanel({
  facilityId,
  phoneNumber,
  value,
  filledFields,
  keptFields,
  onVerified,
  onClear,
}: AbhaRegistrationPanelProps) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const linkedPatient = value?.abha_number.patient;

  return (
    <section
      aria-labelledby="abha-registration-heading"
      className="bg-white flex flex-col gap-4 p-6 shadow rounded-md"
    >
      <div className="flex items-start justify-between gap-4">
        <div>
          <h5 id="abha-registration-heading" className="text-lg font-semibold">
            {t("abha__abha")}
          </h5>
          <p className="text-sm text-gray-600">
            {value
              ? t("abha__registration_verified")
              : t("abha__registration_intro")}
          </p>
        </div>
        {value ? (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={onClear}
            aria-label={t("abha__remove")}
          >
            <XIcon />
            {t("abha__remove")}
          </Button>
        ) : (
          <Button type="button" variant="outline_primary" onClick={() => setOpen(true)}>
            <IdCardIcon />
            {t("abha__verify_or_create")}
          </Button>
        )}
      </div>

      {value && (
        <AbhaProfileSummary abha={value.abha_number} photo={value.profile_photo} />
      )}

      {value && linkedPatient && (
        <Alert>
          <AlertTitle>{t("abha__already_registered")}</AlertTitle>
          <AlertDescription className="flex flex-col gap-2 items-start">
            {t("abha__already_registered_description")}
            {facilityId && (
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() =>
                  navigate(`/facility/${facilityId}/patient/${linkedPatient}`)
                }
              >
                {t("abha__open_patient")}
              </Button>
            )}
          </AlertDescription>
        </Alert>
      )}

      {value && !linkedPatient && (filledFields.length > 0 || keptFields.length > 0) && (
        <div className="rounded-md bg-blue-50 border border-blue-200 p-3 text-sm text-blue-900 flex flex-col gap-1">
          {filledFields.length > 0 && (
            <p>
              {t("abha__fields_filled", { fields: filledFields.join(", ") })}
            </p>
          )}
          {keptFields.length > 0 && (
            <p>{t("abha__fields_kept", { fields: keptFields.join(", ") })}</p>
          )}
          <p>{t("abha__corrections_note")}</p>
        </div>
      )}

      <AbhaVerificationDialog
        open={open}
        onOpenChange={setOpen}
        mobile={toIndianMobile(phoneNumber) || undefined}
        onVerified={onVerified}
      />
    </section>
  );
}
