{"content": "import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { IdCardIcon, QrCodeIcon, RefreshCwIcon } from "lucide-react";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Skeleton } from "@/components/ui/skeleton";

import { AbhaProfileSummary } from "@/components/Abdm/AbhaProfileSummary";
import { AbhaVerificationDialog } from "@/components/Abdm/AbhaVerificationDialog";
import { getAbhaError, toIndianMobile } from "@/components/Abdm/utils";
import { AbhaNumber, AbhaVerified } from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";

interface PatientAbhaSectionProps {
  patientId: string;
  phoneNumber?: string;
  canWrite: boolean;
}

type ImageKind = "qr_code" | "abha_card";

export function PatientAbhaSection({
  patientId,
  phoneNumber,
  canWrite,
}: PatientAbhaSectionProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [verifying, setVerifying] = useState(false);
  const [image, setImage] = useState<ImageKind | null>(null);
  const [photo, setPhoto] = useState<string | null>(null);

  const queryKey = ["abha_number", "patient", patientId];
  const { data, isLoading } = useQuery({
    queryKey,
    queryFn: query(abhaApi.list, { queryParams: { patient: patientId } }),
  });
  const abha = data?.results[0];

  const { mutate: linkPatient, isPending: isLinking } = useMutation({
    mutationFn: (result: AbhaVerified) =>
      mutate(abhaApi.linkPatient, {
        pathParams: { id: result.abha_number.id },
        silent: true,
      })({ patient: patientId }),
    onSuccess: () => {
      toast.success(t("abha__linked"));
      queryClient.invalidateQueries({ queryKey });
    },
    onError: (error) =>
      toast.error(getAbhaError(error, t("abha__link_failed")).msg),
  });

  const { mutate: refreshProfile, isPending: isRefreshing } = useMutation({
    mutationFn: (id: string) =>
      mutate(abhaApi.refreshProfile, { pathParams: { id }, silent: true })(
        undefined,
      ),
    onSuccess: (result) => {
      setPhoto(result.profile_photo);
      queryClient.invalidateQueries({ queryKey });
    },
    onError: (error) =>
      toast.error(getAbhaError(error, t("abha__request_failed")).msg),
  });

  const handleVerified = (result: AbhaVerified) => {
    setPhoto(result.profile_photo);
    if (result.abha_number.patient === patientId) {
      queryClient.invalidateQueries({ queryKey });
      return;
    }
    if (result.abha_number.patient) {
      toast.error(t("abha__linked_to_other_patient"));
      return;
    }
    linkPatient(result);
  };

  return (
    <div className="mt-4 rounded-md bg-white p-5 shadow-sm flex flex-col gap-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h2 className="text-xl">{t("abha__abha")}</h2>
        <div className="flex flex-wrap gap-2">
          {abha && (
            <>
              <Button variant="outline" size="sm" onClick={() => setImage("abha_card")}>
                <IdCardIcon />
                {t("abha__abha_card")}
              </Button>
              <Button variant="outline" size="sm" onClick={() => setImage("qr_code")}>
                <QrCodeIcon />
                {t("qr_code")}
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={isRefreshing}
                onClick={() => refreshProfile(abha.id)}
              >
                <RefreshCwIcon />
                {t("refresh")}
              </Button>
            </>
          )}
          {canWrite && (
            <Button
              variant={abha ? "ghost" : "outline_primary"}
              size="sm"
              disabled={isLinking}
              onClick={() => setVerifying(true)}
            >
              {abha ? t("abha__verify_again") : t("abha__link_abha")}
            </Button>
          )}
        </div>
      </div>

      {isLoading ? (
        <Skeleton className="h-16 w-full" />
      ) : abha ? (
        <AbhaProfileSummary abha={abha} photo={photo} />
      ) : (
        <p className="text-sm text-gray-600">{t("abha__not_linked")}</p>
      )}

      <AbhaVerificationDialog
        open={verifying}
        onOpenChange={setVerifying}
        mobile={toIndianMobile(phoneNumber) || undefined}
        onVerified={handleVerified}
      />

      {abha && (
        <AbhaImageDialog
          abha={abha}
          kind={image}
          onClose={() => setImage(null)}
        />
      )}
    </div>
  );
}

function AbhaImageDialog({
  abha,
  kind,
  onClose,
}: {
  abha: AbhaNumber;
  kind: ImageKind | null;
  onClose: () => void;
}) {
  const { t } = useTranslation();
  const route = kind === "qr_code" ? abhaApi.qrCode : abhaApi.abhaCard;
  const { data, error, isLoading } = useQuery({
    queryKey: ["abha_number", abha.id, kind],
    queryFn: query(route, { pathParams: { id: abha.id }, silent: true }),
    enabled: !!kind,
    retry: false,
    staleTime: 0,
    gcTime: 0,
  });
  const [url, setUrl] = useState<string | null>(null);

  useEffect(() => {
    if (!(data instanceof Blob)) {
      setUrl(null);
      return;
    }
    const objectUrl = URL.createObjectURL(data);
    setUrl(objectUrl);
    return () => URL.revokeObjectURL(objectUrl);
  }, [data]);

  const title = kind === "qr_code" ? t("qr_code") : t("abha__abha_card");

  return (
    <Dialog open={!!kind} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
        </DialogHeader>
        {isLoading && <Skeleton className="h-64 w-full" />}
        {error && (
          <p className="text-sm text-red-700" role="alert">
            {getAbhaError(error, t("abha__request_failed")).msg}
          </p>
        )}
        {url &&
          (data instanceof Blob && data.type === "application/pdf" ? (
            <object
              data={url}
              type="application/pdf"
              className="h-[70vh] w-full"
              aria-label={title}
            />
          ) : (
            <img src={url} alt={title} className="mx-auto max-h-[70vh]" />
          ))}
        {url && (
          <a
            href={url}
            download={`${abha.abha_number}-${kind}`}
            className="text-sm text-primary-700 underline self-start"
          >
            {t("download")}
          </a>
        )}
      </DialogContent>
    </Dialog>
  );
}
