{"content": """"
The Fidelius scheme ABDM uses between HIP and HIU: ECDH on Curve25519, HKDF-SHA256
and AES-256-GCM. Peers encode Curve25519 in short Weierstrass form inside an X.509
key, so the maths runs on X25519 and only the encoding is converted.
"""

import os
from base64 import b64decode, b64encode
from dataclasses import dataclass

from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric.x25519 import (
    X25519PrivateKey,
    X25519PublicKey,
)
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.hkdf import HKDF

P = 2**255 - 19
MONTGOMERY_A = 486662
A_OVER_3 = MONTGOMERY_A * pow(3, -1, P) % P
WEIERSTRASS_A = (3 - MONTGOMERY_A**2) * pow(3, -1, P) % P
WEIERSTRASS_B = (2 * MONTGOMERY_A**3 - 9 * MONTGOMERY_A) * pow(27, -1, P) % P
ORDER = 2**252 + 27742317777372353535851937790883648493
COFACTOR = 8
BASE_U = 9

POINT_LENGTH = 65
NONCE_LENGTH = 32
SALT_LENGTH = 20
IV_LENGTH = 12
KEY_PARAMETERS = "Curve25519/32byte random key"


def _sqrt(n):
    # p = 5 (mod 8)
    root = pow(n, (P + 3) // 8, P)
    if root * root % P != n % P:
        root = root * pow(2, (P - 1) // 4, P) % P
    if root * root % P != n % P:
        msg = "Not a point on Curve25519"
        raise ValueError(msg)
    return root


def u_to_point(u):
    x = (u + A_OVER_3) % P
    y = _sqrt((x**3 + WEIERSTRASS_A * x + WEIERSTRASS_B) % P)
    return b"\x04" + x.to_bytes(32, "big") + y.to_bytes(32, "big")


def point_to_u(point):
    if len(point) != POINT_LENGTH or point[0] != 4:  # noqa: PLR2004
        msg = "Expected an uncompressed Curve25519 point"
        raise ValueError(msg)
    return (int.from_bytes(point[1:33], "big") - A_OVER_3) % P


# DER, enough to write the X.509 key the way BouncyCastle does.


def _der(tag, content):
    length = len(content)
    if length < 0x80:  # noqa: PLR2004
        encoded_length = bytes([length])
    else:
        raw = length.to_bytes((length.bit_length() + 7) // 8, "big")
        encoded_length = bytes([0x80 | len(raw)]) + raw
    return bytes([tag]) + encoded_length + content


def _integer(value):
    raw = value.to_bytes(value.bit_length() // 8 + 1, "big")
    return _der(0x02, raw)


def _oid(dotted):
    parts = [int(part) for part in dotted.split(".")]
    body = bytes([parts[0] * 40 + parts[1]])
    for part in parts[2:]:
        chunk = [part & 0x7F]
        part >>= 7
        while part:
            chunk.insert(0, 0x80 | (part & 0x7F))
            part >>= 7
        body += bytes(chunk)
    return _der(0x06, body)


def _sequence(*items):
    return _der(0x30, b"".join(items))


def _octets(content):
    return _der(0x04, content)


def encode_public_key(point):
    """X.509 SubjectPublicKeyInfo with explicit curve parameters, as Fidelius emits."""
    parameters = _sequence(
        _integer(1),
        _sequence(_oid("1.2.840.10045.1.1"), _integer(P)),
        _sequence(
            _octets(WEIERSTRASS_A.to_bytes(32, "big")),
            _octets(WEIERSTRASS_B.to_bytes(32, "big")),
        ),
        _octets(u_to_point(BASE_U)),
        _integer(ORDER),
        _integer(COFACTOR),
    )
    algorithm = _sequence(_oid("1.2.840.10045.2.1"), parameters)
    return _sequence(algorithm, _der(0x03, b"\x00" + point))


def decode_public_key(key_value):
    # Peers send named or explicit curve parameters; both end with the point.
    return b64decode(key_value)[-POINT_LENGTH:]


@dataclass
class KeyPair:
    private_key: X25519PrivateKey
    nonce: bytes

    @classmethod
    def generate(cls):
        return cls(X25519PrivateKey.generate(), os.urandom(NONCE_LENGTH))

    @property
    def public_point(self):
        u = int.from_bytes(self.private_key.public_key().public_bytes_raw(), "little")
        return u_to_point(u)

    @property
    def key_value(self):
        return b64encode(encode_public_key(self.public_point)).decode()

    @property
    def nonce_value(self):
        return b64encode(self.nonce).decode()

    def _session(self, peer_key_value, peer_nonce_value):
        peer_u = point_to_u(decode_public_key(peer_key_value))
        shared_u = self.private_key.exchange(
            X25519PublicKey.from_public_bytes(peer_u.to_bytes(32, "little"))
        )
        shared_x = (int.from_bytes(shared_u, "little") + A_OVER_3) % P
        mixed = bytes(
            a ^ b
            for a, b in zip(self.nonce, b64decode(peer_nonce_value), strict=True)
        )
        salt, iv = mixed[:SALT_LENGTH], mixed[-IV_LENGTH:]
        key = HKDF(algorithm=hashes.SHA256(), length=32, salt=salt, info=None).derive(
            shared_x.to_bytes(32, "big")
        )
        return AESGCM(key), iv

    def encrypt(self, data, peer_key_value, peer_nonce_value):
        cipher, iv = self._session(peer_key_value, peer_nonce_value)
        return b64encode(cipher.encrypt(iv, data, None)).decode()

    def decrypt(self, content, peer_key_value, peer_nonce_value):
        cipher, iv = self._session(peer_key_value, peer_nonce_value)
        return cipher.decrypt(iv, b64decode(content), None)
