{"content": "from uuid import uuid4

from django.conf import settings

from care.abdm.models import Exchange
from care.abdm.service.client import AbdmError, request

# Credentials and payloads that must never reach the exchange log.
REDACTED_KEYS = {"linkToken", "token", "content", "signature", "keyValue", "otp"}


def redact(value):
    if isinstance(value, dict):
        return {
            key: f"<redacted:{len(str(item))}>"
            if key in REDACTED_KEYS and item
            else redact(item)
            for key, item in value.items()
        }
    if isinstance(value, list):
        return [redact(item) for item in value]
    return value


def header_lengths(headers):
    return {name: len(str(value)) for name, value in headers.items()}


def post(path, body, *, hip_id="", headers=None, context=None):
    """Send a gateway call and record it as an exchange its callback can join."""
    request_id = str(uuid4())
    request_headers = {"X-CM-ID": settings.ABDM_CM_ID}
    if hip_id:
        request_headers["X-HIP-ID"] = hip_id
    request_headers.update(headers or {})

    # Registered before sending: a callback can arrive before the response does.
    exchange = Exchange.objects.create(
        request_id=request_id,
        direction=Exchange.Direction.outbound,
        path=path,
        hip_id=hip_id,
        status=Exchange.Status.sent,
        headers=header_lengths(request_headers),
        body=redact(body),
        context=context or {},
    )
    try:
        response = request(
            "POST",
            f"{settings.ABDM_GATEWAY_URL}{path}",
            headers=request_headers,
            json=body,
            request_id=request_id,
        )
    except AbdmError as e:
        exchange.status = Exchange.Status.refused
        exchange.http_status = e.status
        exchange.error_code = e.code or ""
        exchange.message = e.message
        exchange.save()
        raise
    exchange.status = Exchange.Status.accepted
    exchange.http_status = response.status_code
    exchange.save()
    return exchange
