{"content": """"FHIR R4 resources shaped by the NRCeS profiles, built from Care's own models."""

from uuid import uuid4

from django.conf import settings
from django.utils import timezone

NRCES = "https://nrces.in/ndhm/fhir/r4/StructureDefinition/"
NRCES_IDENTIFIER_TYPE = (
    "https://nrces.in/ndhm/fhir/r4/CodeSystem/ndhm-identifier-type-code"
)
HL7_IDENTIFIER_TYPE = "http://terminology.hl7.org/CodeSystem/v2-0203"
HL7_TERMINOLOGY = "http://terminology.hl7.org/CodeSystem/"
SNOMED = "http://snomed.info/sct"
UCUM = "http://unitsofmeasure.org"

GENDERS = {"male": "male", "female": "female"}
ENCOUNTER_STATUS = {
    "planned": "planned",
    "in_progress": "in-progress",
    "on_hold": "onleave",
    "discharged": "finished",
    "completed": "finished",
    "cancelled": "cancelled",
    "discontinued": "cancelled",
    "entered_in_error": "entered-in-error",
}
ENCOUNTER_CLASS = {
    "amb": ("AMB", "ambulatory"),
    "imp": ("IMP", "inpatient encounter"),
    "emer": ("EMER", "emergency"),
    "vr": ("VR", "virtual"),
    "hh": ("HH", "home health"),
    "obsenc": ("OBSENC", "observation encounter"),
}
CONDITION_CATEGORY = {
    "encounter_diagnosis": "encounter-diagnosis",
    "problem_list_item": "problem-list-item",
    "chronic_condition": "problem-list-item",
}


def local_system(kind):
    return f"https://{settings.CURRENT_DOMAIN}/{kind}"


def fhir_code(value):
    """Care stores FHIR codes with underscores; FHIR spells them with hyphens."""
    return value.replace("_", "-") if value else value


def iso(value):
    return value.isoformat() if value else None


def coding(value):
    if not value or not value.get("code"):
        return None
    return {
        key: value[key] for key in ("system", "code", "display") if value.get(key)
    }


def concept(value, text=None):
    code = coding(value)
    if code:
        return {"coding": [code], "text": value.get("display") or text or code["code"]}
    return {"text": text} if text else None


def status_concept(system, code):
    if not code:
        return None
    return {"coding": [{"system": f"{HL7_TERMINOLOGY}{system}", "code": code}]}


def quantity(value):
    if not value or value.get("value") is None:
        return None
    result = {"value": float(value["value"])}
    unit = value.get("unit")
    if isinstance(unit, dict):
        result.update(
            {
                key: unit[source]
                for key, source in (
                    ("unit", "display"),
                    ("system", "system"),
                    ("code", "code"),
                )
                if unit.get(source)
            }
        )
    elif unit:
        result.update({"unit": unit, "system": UCUM, "code": unit})
    return result


def compact(resource):
    return {key: value for key, value in resource.items() if value not in (None, [], {})}


def reference(resource):
    return {"reference": f"urn:uuid:{resource['id']}"}


class BundleBuilder:
    """Collects resources for one document so every reference resolves inside it."""

    def __init__(self, health_facility):
        self.health_facility = health_facility
        self.resources = {}

    def add(self, resource):
        self.resources.setdefault(resource["id"], compact(resource))
        return self.resources[resource["id"]]

    def organization(self):
        facility = self.health_facility.facility
        return self.add(
            {
                "resourceType": "Organization",
                "id": str(facility.external_id),
                "meta": {"profile": [f"{NRCES}Organization"]},
                "identifier": [
                    {
                        "type": {
                            "coding": [
                                {
                                    "system": HL7_IDENTIFIER_TYPE,
                                    "code": "PRN",
                                    "display": "Provider number",
                                }
                            ]
                        },
                        "system": "https://facility.ndhm.gov.in",
                        "value": self.health_facility.hip_id,
                    }
                ],
                "name": facility.name,
                "address": [{"text": facility.address}] if facility.address else [],
            }
        )

    def patient(self, patient):
        identifiers = [
            {
                "type": {
                    "coding": [
                        {
                            "system": HL7_IDENTIFIER_TYPE,
                            "code": "MR",
                            "display": "Medical record number",
                        }
                    ]
                },
                "system": local_system("patient"),
                "value": str(patient.external_id),
            }
        ]
        abha = getattr(patient, "abha_number", None)
        if abha:
            identifiers.append(
                {
                    "type": {
                        "coding": [
                            {
                                "system": NRCES_IDENTIFIER_TYPE,
                                "code": "HIN",
                                "display": "Health ID issued by NDHM",
                            }
                        ]
                    },
                    "value": abha.abha_number,
                }
            )
            if abha.abha_address:
                identifiers.append(
                    {
                        "type": {
                            "coding": [
                                {
                                    "system": NRCES_IDENTIFIER_TYPE,
                                    "code": "ABHA",
                                    "display": "Ayushman Bharat Health Account (ABHA) ID",
                                }
                            ]
                        },
                        "value": abha.abha_address,
                    }
                )
        return self.add(
            {
                "resourceType": "Patient",
                "id": str(patient.external_id),
                "meta": {"profile": [f"{NRCES}Patient"]},
                "identifier": identifiers,
                "name": [{"text": patient.name}],
                "telecom": [
                    {"system": "phone", "value": patient.phone_number, "use": "home"}
                ]
                if patient.phone_number
                else [],
                "gender": GENDERS.get(patient.gender, "other"),
                "birthDate": iso(patient.date_of_birth),
            }
        )

    def practitioner(self, user):
        return self.add(
            {
                "resourceType": "Practitioner",
                "id": str(user.external_id),
                "meta": {"profile": [f"{NRCES}Practitioner"]},
                "identifier": [
                    {"system": local_system("user"), "value": str(user.external_id)}
                ],
                "name": [{"text": user.get_full_name() or user.username}],
            }
        )

    def encounter(self, encounter, patient, diagnoses=()):
        code, display = ENCOUNTER_CLASS.get(encounter.encounter_class, ("AMB", "ambulatory"))
        period = encounter.period or {}
        return self.add(
            {
                "resourceType": "Encounter",
                "id": str(encounter.external_id),
                "meta": {"profile": [f"{NRCES}Encounter"]},
                "identifier": [
                    {
                        "system": local_system("encounter"),
                        "value": str(encounter.external_id),
                    }
                ],
                "status": ENCOUNTER_STATUS.get(encounter.status, "unknown"),
                "class": {
                    "system": "http://terminology.hl7.org/CodeSystem/v3-ActCode",
                    "code": code,
                    "display": display,
                },
                "subject": reference(patient),
                "period": compact(
                    {
                        "start": period.get("start") or iso(encounter.created_date),
                        "end": period.get("end"),
                    }
                ),
                "diagnosis": [{"condition": reference(item)} for item in diagnoses],
                "serviceProvider": reference(self.organization()),
            }
        )

    def condition(self, condition, patient):
        onset = condition.onset or {}
        return self.add(
            {
                "resourceType": "Condition",
                "id": str(condition.external_id),
                "meta": {"profile": [f"{NRCES}Condition"]},
                "clinicalStatus": status_concept(
                    "condition-clinical", fhir_code(condition.clinical_status)
                ),
                "verificationStatus": status_concept(
                    "condition-ver-status", fhir_code(condition.verification_status)
                ),
                "category": [
                    status_concept(
                        "condition-category",
                        CONDITION_CATEGORY.get(condition.category),
                    )
                ]
                if CONDITION_CATEGORY.get(condition.category)
                else [],
                "code": concept(condition.code),
                "subject": reference(patient),
                "onsetDateTime": onset.get("onset_datetime"),
                "recordedDate": iso(condition.recorded_date),
                "note": [{"text": condition.note}] if condition.note else [],
            }
        )

    def allergy(self, allergy, patient):
        return self.add(
            {
                "resourceType": "AllergyIntolerance",
                "id": str(allergy.external_id),
                "meta": {"profile": [f"{NRCES}AllergyIntolerance"]},
                "clinicalStatus": status_concept(
                    "allergyintolerance-clinical", fhir_code(allergy.clinical_status)
                ),
                "verificationStatus": status_concept(
                    "allergyintolerance-verification",
                    fhir_code(allergy.verification_status),
                ),
                "category": [allergy.category] if allergy.category else [],
                "criticality": fhir_code(allergy.criticality),
                "code": concept(allergy.code),
                "patient": reference(patient),
                "recordedDate": iso(allergy.recorded_date or allergy.created_date),
                "note": [{"text": allergy.note}] if allergy.note else [],
            }
        )

    def medication_request(self, request, patient, encounter):
        requester = self.practitioner(request.requester) if request.requester else None
        product = request.requested_product
        medication = concept(request.medication) or concept(
            None, text=getattr(product, "name", None)
        )
        return self.add(
            {
                "resourceType": "MedicationRequest",
                "id": str(request.external_id),
                "meta": {"profile": [f"{NRCES}MedicationRequest"]},
                "status": fhir_code(request.status),
                "intent": fhir_code(request.intent),
                "medicationCodeableConcept": medication,
                "subject": reference(patient),
                "encounter": reference(encounter),
                "authoredOn": iso(request.authored_on),
                "requester": reference(requester) if requester else None,
                "dosageInstruction": [
                    dosage(item) for item in request.dosage_instruction or []
                ],
                "note": [{"text": request.note}] if request.note else [],
            }
        )

    def service_request(self, service_request, patient, encounter):
        requester = (
            self.practitioner(service_request.requester)
            if service_request.requester
            else None
        )
        return self.add(
            {
                "resourceType": "ServiceRequest",
                "id": str(service_request.external_id),
                "meta": {"profile": [f"{NRCES}ServiceRequest"]},
                "status": fhir_code(service_request.status),
                "intent": fhir_code(service_request.intent),
                "code": concept(service_request.code, text=service_request.title),
                "subject": reference(patient),
                "encounter": reference(encounter),
                "authoredOn": iso(service_request.created_date),
                "requester": reference(requester) if requester else None,
            }
        )

    def observation(self, observation, patient):
        return self.add(
            {
                "resourceType": "Observation",
                "id": str(observation.external_id),
                "meta": {"profile": [f"{NRCES}Observation"]},
                "status": fhir_code(observation.status),
                "code": concept(observation.main_code),
                "subject": reference(patient),
                "effectiveDateTime": iso(observation.effective_datetime),
                **observation_value(observation),
                "note": [{"text": observation.note}] if observation.note else [],
            }
        )

    def diagnostic_report(self, report, patient, results):
        return self.add(
            {
                "resourceType": "DiagnosticReport",
                "id": str(report.external_id),
                "meta": {"profile": [f"{NRCES}DiagnosticReportLab"]},
                "basedOn": [
                    reference(
                        self.service_request(
                            report.service_request, patient, {"id": str(report.encounter.external_id)}
                        )
                    )
                ]
                if report.service_request
                else [],
                "status": fhir_code(report.status),
                "category": [concept(report.category)] if coding(report.category) else [],
                "code": concept(report.code, text="Diagnostic report"),
                "subject": reference(patient),
                "issued": iso(report.modified_date),
                "performer": [reference(self.organization())],
                "result": [reference(item) for item in results],
                "conclusion": report.conclusion,
            }
        )

    def document(self, *, profile, type_coding, title, subject, author, sections, encounter=None):  # noqa: PLR0913
        now = timezone.now()
        composition = {
            "resourceType": "Composition",
            "id": str(uuid4()),
            "meta": {"versionId": "1", "lastUpdated": iso(now), "profile": [f"{NRCES}{profile}"]},
            "language": "en-IN",
            "status": "final",
            "type": {"coding": [type_coding], "text": type_coding["display"]},
            "subject": reference(subject),
            "encounter": reference(encounter) if encounter else None,
            "date": iso(now),
            "author": [reference(author)],
            "title": title,
            "attester": [{"mode": "legal", "party": reference(author)}],
            "custodian": reference(self.organization()),
            "section": sections,
        }
        entries = [compact(composition), *self.resources.values()]
        return {
            "resourceType": "Bundle",
            "id": str(uuid4()),
            "meta": {
                "versionId": "1",
                "lastUpdated": iso(now),
                "profile": [f"{NRCES}DocumentBundle"],
                "security": [
                    {
                        "system": "http://terminology.hl7.org/CodeSystem/v3-Confidentiality",
                        "code": "V",
                        "display": "very restricted",
                    }
                ],
            },
            "identifier": {"system": local_system("bundle"), "value": str(uuid4())},
            "type": "document",
            "timestamp": iso(now),
            "entry": [
                {"fullUrl": f"urn:uuid:{entry['id']}", "resource": entry}
                for entry in entries
            ],
        }


def section(title, code, display, resources):
    return {
        "title": title,
        "code": {"coding": [{"system": SNOMED, "code": code, "display": display}]},
        "entry": [reference(resource) for resource in resources],
    }


def timing_quantity(value):
    if not value:
        return None
    return {"value": float(value["value"]), "unit": value["unit"], "system": UCUM, "code": value["unit"]}


def dosage(instruction):
    timing = instruction.get("timing") or {}
    repeat = timing.get("repeat") or {}
    dose_and_rate = instruction.get("dose_and_rate") or {}
    dose_range = dose_and_rate.get("dose_range") or {}
    return compact(
        {
            "sequence": instruction.get("sequence"),
            "text": instruction.get("text"),
            "additionalInstruction": [
                item
                for item in (
                    concept(code) for code in instruction.get("additional_instruction") or []
                )
                if item
            ],
            "patientInstruction": instruction.get("patient_instruction"),
            "timing": compact(
                {
                    "repeat": compact(
                        {
                            "frequency": repeat.get("frequency"),
                            "period": float(repeat["period"]) if repeat.get("period") else None,
                            "periodUnit": repeat.get("period_unit"),
                            "boundsDuration": timing_quantity(repeat.get("bounds_duration")),
                        }
                    ),
                    "code": concept(timing.get("code")),
                }
            ),
            "asNeededBoolean": instruction.get("as_needed_boolean"),
            "site": concept(instruction.get("site")),
            "route": concept(instruction.get("route")),
            "method": concept(instruction.get("method")),
            "doseAndRate": [
                compact(
                    {
                        "doseQuantity": quantity(dose_and_rate.get("dose_quantity")),
                        "doseRange": compact(
                            {
                                "low": quantity(dose_range.get("low")),
                                "high": quantity(dose_range.get("high")),
                            }
                        ),
                    }
                )
            ]
            if dose_and_rate
            else [],
        }
    )


NUMERIC_VALUE_TYPES = {"decimal", "integer", "quantity"}


def observation_value(observation):
    value = observation.value or {}
    if value.get("coding"):
        return {"valueCodeableConcept": concept(value["coding"])}
    raw = value.get("value")
    if raw in (None, ""):
        return {}
    if observation.value_type in NUMERIC_VALUE_TYPES:
        try:
            return {"valueQuantity": quantity({"value": float(raw), "unit": value.get("unit")})}
        except (TypeError, ValueError):
            pass
    if observation.value_type == "boolean":
        return {"valueBoolean": str(raw).lower() == "true"}
    return {"valueString": str(raw)}
