{"content": """"The ABDM record types Care produces, one builder per hiType."""

from care.abdm.fhir.resources import (
    ENCOUNTER_CLASS,
    SNOMED,
    BundleBuilder,
    section,
)
from care.emr.models import (
    AllergyIntolerance,
    Condition,
    DiagnosticReport,
    MedicationRequest,
    Observation,
    ServiceRequest,
)
from care.users.models import User

OP_CONSULTATION = "OPConsultation"
PRESCRIPTION = "Prescription"
DIAGNOSTIC_REPORT = "DiagnosticReport"
HI_TYPES = (OP_CONSULTATION, PRESCRIPTION, DIAGNOSTIC_REPORT)

ERRORED = ("entered_in_error",)
REPORT_EXCLUDED_STATUSES = ("entered_in_error", "cancelled", "registered")


def care_context_display(encounter):
    _, label = ENCOUNTER_CLASS.get(encounter.encounter_class, ("", "visit"))
    started = (encounter.period or {}).get("start") or encounter.created_date.isoformat()
    return f"{label.capitalize()} records from {started[:10]}"


def _author(builder, encounter):
    team = encounter.care_team if isinstance(encounter.care_team, list) else []
    user_ids = [member.get("user_id") for member in team if member.get("user_id")]
    user = User.objects.filter(id__in=user_ids).first() or encounter.created_by
    return builder.practitioner(user) if user else builder.organization()


def _medication_requests(encounter):
    return (
        MedicationRequest.objects.filter(encounter=encounter)
        .exclude(status__in=(*ERRORED, "draft"))
        .select_related("requester", "requested_product")
    )


def _diagnostic_reports(encounter):
    return (
        DiagnosticReport.objects.filter(encounter=encounter)
        .exclude(status__in=REPORT_EXCLUDED_STATUSES)
        .select_related("service_request", "service_request__requester")
    )


def _op_records(encounter):
    conditions = list(
        Condition.objects.filter(encounter=encounter).exclude(
            verification_status__in=ERRORED
        )
    )
    return {
        "complaints": [c for c in conditions if c.category == "problem_list_item"],
        "diagnoses": [c for c in conditions if c.category == "encounter_diagnosis"],
        "history": [c for c in conditions if c.category == "chronic_condition"],
        "allergies": list(
            AllergyIntolerance.objects.filter(encounter=encounter).exclude(
                verification_status__in=ERRORED
            )
        ),
        "investigations": list(
            ServiceRequest.objects.filter(encounter=encounter)
            .exclude(status__in=ERRORED)
            .select_related("requester")
        ),
        "medications": list(_medication_requests(encounter)),
        "observations": [
            observation
            for observation in Observation.objects.filter(
                encounter=encounter, diagnostic_report__isnull=True
            ).exclude(status__in=ERRORED)
            if (observation.main_code or {}).get("code")
        ],
    }


def available_hi_types(encounter):
    types = []
    if any(_op_records(encounter).values()):
        types.append(OP_CONSULTATION)
    if _medication_requests(encounter).exists():
        types.append(PRESCRIPTION)
    if _diagnostic_reports(encounter).exists():
        types.append(DIAGNOSTIC_REPORT)
    return types


def op_consultation(encounter, health_facility):
    records = _op_records(encounter)
    if not any(records.values()):
        return None
    builder = BundleBuilder(health_facility)
    patient = builder.patient(encounter.patient)
    author = _author(builder, encounter)
    diagnoses = [builder.condition(c, patient) for c in records["diagnoses"]]
    visit = builder.encounter(encounter, patient, diagnoses)

    sections = []
    for title, code, display, resources in (
        (
            "Chief complaints",
            "422843007",
            "Chief complaint section",
            [builder.condition(c, patient) for c in records["complaints"]],
        ),
        (
            "Allergies",
            "722446000",
            "Allergy record",
            [builder.allergy(a, patient) for a in records["allergies"]],
        ),
        (
            "Medical History",
            "371529009",
            "History and physical report",
            [builder.condition(c, patient) for c in records["history"]],
        ),
        (
            "Investigation Advice",
            "721963009",
            "Order document",
            [builder.service_request(s, patient, visit) for s in records["investigations"]],
        ),
        (
            "Medications",
            "721912009",
            "Medication summary document",
            [builder.medication_request(m, patient, visit) for m in records["medications"]],
        ),
        (
            "Physical Examination",
            "425044008",
            "Physical exam section",
            [builder.observation(o, patient) for o in records["observations"]],
        ),
    ):
        if resources:
            sections.append(section(title, code, display, resources))
    if not sections:
        # Diagnoses alone travel on the Encounter, which still needs a section.
        sections.append(
            section("Medical History", "371529009", "History and physical report", diagnoses)
        )

    return builder.document(
        profile="OPConsultRecord",
        type_coding={
            "system": SNOMED,
            "code": "371530004",
            "display": "Clinical consultation report",
        },
        title="Consultation Report",
        subject=patient,
        author=author,
        encounter=visit,
        sections=sections,
    )


def prescription(encounter, health_facility):
    requests = list(_medication_requests(encounter))
    if not requests:
        return None
    builder = BundleBuilder(health_facility)
    patient = builder.patient(encounter.patient)
    author = _author(builder, encounter)
    visit = builder.encounter(encounter, patient)
    return builder.document(
        profile="PrescriptionRecord",
        type_coding={"system": SNOMED, "code": "440545006", "display": "Prescription record"},
        title="Prescription record",
        subject=patient,
        author=author,
        encounter=visit,
        sections=[
            section(
                "Prescription record",
                "440545006",
                "Prescription record",
                [builder.medication_request(r, patient, visit) for r in requests],
            )
        ],
    )


def diagnostic_report(encounter, health_facility):
    reports = list(_diagnostic_reports(encounter))
    if not reports:
        return None
    builder = BundleBuilder(health_facility)
    patient = builder.patient(encounter.patient)
    author = _author(builder, encounter)
    visit = builder.encounter(encounter, patient)
    entries = []
    for report in reports:
        results = [
            builder.observation(o, patient)
            for o in Observation.objects.filter(diagnostic_report=report).exclude(
                status__in=ERRORED
            )
        ]
        entries.append(builder.diagnostic_report(report, patient, visit, results))
    return builder.document(
        profile="DiagnosticReportRecord",
        type_coding={"system": SNOMED, "code": "721981007", "display": "Diagnostic studies report"},
        title="Diagnostic Report",
        subject=patient,
        author=author,
        encounter=visit,
        sections=[section("Diagnostic Report", "721981007", "Diagnostic studies report", entries)],
    )


BUILDERS = {
    OP_CONSULTATION: op_consultation,
    PRESCRIPTION: prescription,
    DIAGNOSTIC_REPORT: diagnostic_report,
}
