{"filePath": "/Users/rithviknishad/ohc.network/care/care/abdm/service/m2.py", "content": """"ABDM M2: Care as a Health Information Provider.

Every outbound call is an exchange: it is logged before sending, the gateway
accepts or refuses it synchronously, and the answer arrives later on a callback
joined by request id. Nothing here waits for a callback.
"""

import base64
import hashlib
import hmac
import ipaddress
import json
import logging
import re
import secrets
import socket
from datetime import UTC, datetime, timedelta
from urllib.parse import urlparse
from uuid import uuid4

import requests
from django.conf import settings
from django.core.cache import cache
from django.db.models import Q
from django.utils import timezone

from care.abdm.fhir.records import BUILDERS, available_hi_types
from care.abdm.models import (
    AbhaNumber,
    CareContext,
    CareContextStatus,
    Consent,
    DataTransfer,
    Exchange,
    HealthFacility,
)
from care.abdm.service import gateway
from care.abdm.service.client import AbdmError, utc_timestamp
from care.abdm.service.fidelius import KEY_PARAMETERS, KeyPair
from care.emr.models import Patient
from care.utils.sms.utils import send_text_message

logger = logging.getLogger(__name__)

LINK_TOKEN_FALLBACK_TTL = 60 * 60
LINK_TOKEN_EXPIRY_MARGIN = 60
LINK_OTP_MAX_ATTEMPTS = 5
UNKNOWN_ERROR = "ABDM-9999"
DUPLICATE_LINK_TOKEN_REQUEST = "ABDM-1092"
DATA_KEY_VALIDITY = timedelta(days=1)

ABDM_GENDER = {"M": "male", "F": "female", "O": "non_binary", "T": "transgender"}
# Characters ABDM accepts in display and reference fields.
UNSAFE_TEXT = re.compile(r"[^a-zA-Z0-9_\-@,. \"':|()/]")


def safe_text(value, limit=255):
    return UNSAFE_TEXT.sub(" ", str(value or "")).strip()[:limit]


def abha_digits(abha):
    return int("".join(ch for ch in abha.abha_number if ch.isdigit()))


def error_detail(error, **extra):
    return {
        "code": error.code,
        "message": error.message,
        "request_id": error.request_id,
        "at": timezone.now().isoformat(),
        **extra,
    }


def fail_care_contexts(care_contexts, detail):
    for care_context in care_contexts:
        if care_context.error and detail.get("code") == DUPLICATE_LINK_TOKEN_REQUEST:
            # A duplicate request says nothing new; the first error is the cause.
            continue
        care_context.error = care_context.error or detail
        care_context.status = CareContextStatus.failed
        care_context.save(update_fields=["error", "status", "modified_date"])


def parse_time(value):
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo else parsed.replace(tzinfo=UTC)


def encounter_start(encounter):
    return parse_time((encounter.period or {}).get("start")) or encounter.created_date


# --- Care contexts ------------------------------------------------------------


def ensure_care_context(encounter):
    """Make the encounter a care context if its facility is a mapped HIP."""
    health_facility = HealthFacility.objects.filter(
        facility_id=encounter.facility_id, active=True
    ).first()
    if health_facility is None:
        return None
    from care.abdm.fhir.records import care_context_display

    care_context, _ = CareContext.objects.get_or_create(
        encounter=encounter,
        defaults={
            "patient": encounter.patient,
            "health_facility": health_facility,
            "abha_number": AbhaNumber.objects.filter(
                patient=encounter.patient
            ).first(),
            "reference_number": str(encounter.external_id),
            "display": safe_text(care_context_display(encounter)),
        },
    )
    return care_context


def care_context_entries(patient, care_contexts):
    """The patient block ABDM expects: one entry per hiType."""
    by_type = {}
    for care_context in care_contexts:
        for hi_type in available_hi_types(care_context.encounter):
            by_type.setdefault(hi_type, []).append(care_context)
    return [
        {
            "referenceNumber": str(patient.external_id),
            "display": safe_text(patient.name),
            "careContexts": [
                {"referenceNumber": cc.reference_number, "display": cc.display}
                for cc in items
            ],
            "hiType": hi_type,
            "count": len(items),
        }
        for hi_type, items in by_type.items()
    ]


# --- HIP-initiated linking ----------------------------------------------------


def link_token_key(hip_id, abha):
    return f"abdm:m2:link-token:{hip_id}:{abha.external_id}"


def link_token_ttl(token):
    try:
        payload = token.split(".")[1]
        claims = json.loads(base64.urlsafe_b64decode(payload + "=" * (-len(payload) % 4)))
        remaining = int(claims["exp"]) - int(timezone.now().timestamp())
    except (IndexError, KeyError, TypeError, ValueError):
        return LINK_TOKEN_FALLBACK_TTL
    return max(remaining - LINK_TOKEN_EXPIRY_MARGIN, 1)


def link_care_contexts(care_context_ids):
    """Link care contexts to their patient's ABHA, fetching a link token first."""
    groups = {}
    care_contexts = CareContext.objects.filter(id__in=care_context_ids).exclude(
        status=CareContextStatus.linked
    ).select_related("health_facility", "patient", "encounter", "abha_number")
    for care_context in care_contexts:
        abha = care_context.abha_number or AbhaNumber.objects.filter(
            patient=care_context.patient
        ).first()
        if abha is None:
            continue
        if care_context.abha_number_id != abha.id:
            care_context.abha_number = abha
            care_context.save(update_fields=["abha_number", "modified_date"])
        if not available_hi_types(care_context.encounter):
            continue
        groups.setdefault((care_context.health_facility, abha), []).append(care_context)

    for (health_facility, abha), items in groups.items():
        token = cache.get(link_token_key(health_facility.hip_id, abha))
        if token:
            send_link(health_facility, abha, token, items)
        else:
            request_link_token(health_facility, abha, items)


def request_link_token(health_facility, abha, care_contexts):
    body = {
        "abhaNumber": abha_digits(abha),
        "abhaAddress": abha.abha_address,
        "name": abha.name,
        "gender": abha.gender,
        "yearOfBirth": abha.year_of_birth,
    }
    ids = [cc.id for cc in care_contexts]
    try:
        gateway.post(
            "/api/hiecm/v3/token/generate-token",
            body,
            hip_id=health_facility.hip_id,
            context={"care_contexts": ids, "abha_number": abha.id},
        )
    except AbdmError as e:
        fail_care_contexts(care_contexts, error_detail(e))
        return
    CareContext.objects.filter(id__in=ids).update(
        status=CareContextStatus.awaiting_link_token, modified_date=timezone.now()
    )


def send_link(health_facility, abha, token, care_contexts):
    patient = care_contexts[0].patient
    body = {
        "abhaNumber": abha_digits(abha),
        "abhaAddress": abha.abha_address,
        "patient": care_context_entries(patient, care_contexts),
    }
    ids = [cc.id for cc in care_contexts]
    try:
        gateway.post(
            "/api/hiecm/hip/v3/link/carecontext",
            body,
            hip_id=health_facility.hip_id,
            headers={"X-LINK-TOKEN": token},
            context={"care_contexts": ids, "abha_number": abha.id},
        )
    except AbdmError as e:
        if e.status == 401:  # noqa: PLR2004
            # The token was rejected; the next attempt asks for a fresh one.
            cache.delete(link_token_key(health_facility.hip_id, abha))
        fail_care_contexts(care_contexts, error_detail(e))
        return
    CareContext.objects.filter(id__in=ids).update(
        status=CareContextStatus.linking, modified_date=timezone.now()
    )


def answer_error(body):
    error = body.get("error")
    if isinstance(error, dict) and (error.get("code") or error.get("message")):
        return error
    return None


def on_generate_token(outbound, body):
    care_contexts = list(
        CareContext.objects.filter(id__in=outbound.context.get("care_contexts", []))
    )
    abha = AbhaNumber.objects.filter(id=outbound.context.get("abha_number")).first()
    error = answer_error(body)
    token = body.get("linkToken")
    if error or not token or abha is None:
        error = error or {"code": None, "message": "No link token in the answer"}
        fail_care_contexts(
            care_contexts,
            {**error, "request_id": outbound.request_id, "at": timezone.now().isoformat()},
        )
        return
    health_facility = care_contexts[0].health_facility if care_contexts else None
    if health_facility is None:
        return
    cache.set(
        link_token_key(health_facility.hip_id, abha), token, link_token_ttl(token)
    )
    send_link(health_facility, abha, token, care_contexts)


def on_carecontext(outbound, body):
    care_contexts = list(
        CareContext.objects.filter(id__in=outbound.context.get("care_contexts", []))
    )
    error = answer_error(body)
    if error:
        fail_care_contexts(
            care_contexts,
            {**error, "request_id": outbound.request_id, "at": timezone.now().isoformat()},
        )
        return
    abha = AbhaNumber.objects.filter(id=outbound.context.get("abha_number")).first()
    for care_context in care_contexts:
        care_context.status = CareContextStatus.linked
        care_context.linked_at = timezone.now()
        care_context.linked_abha_address = body.get("abhaAddress") or (
            abha.abha_address if abha else ""
        )
        care_context.error = None
        care_context.save()


ANSWER_HANDLERS = {
    "/api/hiecm/v3/token/generate-token": on_generate_token,
    "/api/hiecm/hip/v3/link/carecontext": on_carecontext,
}


def process_answer(outbound, body):
    handler = ANSWER_HANDLERS.get(outbound.path)
    if handler:
        handler(outbound, body)


# --- User-initiated linking ---------------------------------------------------


def identifiers(patient_info):
    values = {}
    for item in [
        *(patient_info.get("verifiedIdentifiers") or []),
        *(patient_info.get("unverifiedIdentifiers") or []),
    ]:
        if item.get("type") and item.get("value"):
            values.setdefault(item["type"], item["value"])
    return values


def match_patient(health_facility, patient_info):
    """Find the patient a discover request describes, and what matched them."""
    candidates = Patient.objects.filter(
        carecontext__health_facility=health_facility
    ).distinct()
    ids = identifiers(patient_info)
    abha_address = patient_info.get("id") or ids.get("ABHA_ADDRESS")
    abha_number = ids.get("ABHA_NUMBER")

    abha_filter = Q()
    if abha_number:
        abha_filter |= Q(abha_number__abha_number=abha_number)
    if abha_address:
        abha_filter |= Q(abha_number__abha_address=abha_address)
    if abha_filter:
        patient = candidates.filter(abha_filter).first()
        if patient:
            return patient, ["ABHA_NUMBER" if abha_number else "ABHA_ADDRESS"]

    if ids.get("MR"):
        patient = candidates.filter(external_id__iexact=ids["MR"]).first() if _is_uuid(ids["MR"]) else None
        if patient:
            return patient, ["MR"]

    mobile = "".join(ch for ch in ids.get("MOBILE", "") if ch.isdigit())[-10:]
    if len(mobile) == 10:  # noqa: PLR2004
        matches = candidates.filter(phone_number__endswith=mobile)
        if patient_info.get("gender") in ABDM_GENDER:
            matches = matches.filter(gender=ABDM_GENDER[patient_info["gender"]])
        if patient_info.get("name"):
            matches = matches.filter(name__iexact=patient_info["name"].strip())
        if patient_info.get("yearOfBirth"):
            year = int(patient_info["yearOfBirth"])
            matches = matches.filter(
                Q(year_of_birth=year) | Q(date_of_birth__year=year)
            )
        if matches.count() == 1:
            return matches.first(), ["MOBILE"]
    return None, []


def _is_uuid(value):
    try:
        uuid4().__class__(str(value))
    except ValueError:
        return False
    return True


def discover(health_facility, body, request_id):
    reply = {
        "transactionId": body.get("transactionId"),
        "response": {"requestId": request_id},
    }
    patient, matched_by = match_patient(health_facility, body.get("patient") or {})
    entries = []
    if patient:
        care_contexts = CareContext.objects.filter(
            patient=patient, health_facility=health_facility
        ).exclude(status=CareContextStatus.linked).select_related("encounter")
        entries = care_context_entries(patient, care_contexts)
    if entries:
        reply.update(patient=entries, matchedBy=matched_by)
    else:
        message = (
            "No unlinked records found for this patient"
            if patient
            else "Patient not found"
        )
        reply["error"] = {"code": UNKNOWN_ERROR, "message": message}
    gateway.post(
        "/api/hiecm/user-initiated-linking/v3/patient/care-context/on-discover",
        reply,
        hip_id=health_facility.hip_id,
    )


def link_reference_key(reference):
    return f"abdm:m2:link-ref:{reference}"


def otp_digest(reference, otp):
    return hmac.new(
        settings.SECRET_KEY.encode(), f"{reference}:{otp}".encode(), hashlib.sha256
    ).hexdigest()


def link_init(health_facility, body, request_id):
    reply = {
        "transactionId": body.get("transactionId"),
        "response": {"requestId": request_id},
    }
    references = {
        context.get("referenceNumber")
        for entry in body.get("patient") or []
        for context in entry.get("careContexts") or []
    }
    care_contexts = list(
        CareContext.objects.filter(
            reference_number__in=references, health_facility=health_facility
        )
        .exclude(status=CareContextStatus.linked)
        .select_related("patient")
    )
    patients = {cc.patient_id for cc in care_contexts}
    patient = care_contexts[0].patient if care_contexts else None
    if not references or len(care_contexts) != len(references) or len(patients) != 1:
        reply["error"] = {
            "code": UNKNOWN_ERROR,
            "message": "Care contexts not found or already linked",
        }
    elif not patient.phone_number:
        reply["error"] = {
            "code": UNKNOWN_ERROR,
            "message": "No mobile number on record to send the OTP to",
        }
    else:
        reference = str(uuid4())
        otp = f"{secrets.randbelow(10**6):06d}"
        ttl = settings.ABDM_LINK_OTP_TTL
        cache.set(
            link_reference_key(reference),
            {
                "otp": otp_digest(reference, otp),
                "hip_id": health_facility.hip_id,
                "care_contexts": [cc.id for cc in care_contexts],
                "abha_address": body.get("abhaAddress") or "",
                "attempts": 0,
            },
            ttl,
        )
        send_text_message(
            content=(
                f"{otp} is your OTP to link records at "
                f"{health_facility.facility.name} with your ABHA. "
                f"It is valid for {ttl // 60} minutes."
            ),
            recipients=[patient.phone_number],
        )
        reply["link"] = {
            "referenceNumber": reference,
            "authenticationType": "DIRECT",
            "meta": {
                "communicationMedium": "MOBILE",
                "communicationHint": "OTP",
                "communicationExpiry": (timezone.now() + timedelta(seconds=ttl))
                .astimezone(UTC)
                .isoformat(timespec="milliseconds")
                .replace("+00:00", "Z"),
            },
        }
    gateway.post(
        "/api/hiecm/user-initiated-linking/v3/link/care-context/on-init",
        reply,
        hip_id=health_facility.hip_id,
    )


def verify_link_otp(health_facility, confirmation):
    """Return the linking state if the OTP is right, else an error message."""
    reference = str(confirmation.get("linkRefNumber") or "")
    key = link_reference_key(reference)
    state = cache.get(key)
    if not state or state["hip_id"] != health_facility.hip_id:
        return None, "Link reference is invalid or has expired"
    if state["attempts"] >= LINK_OTP_MAX_ATTEMPTS:
        cache.delete(key)
        return None, "Too many incorrect OTP attempts"
    expected = otp_digest(reference, str(confirmation.get("token") or ""))
    if not hmac.compare_digest(expected, state["otp"]):
        state["attempts"] += 1
        cache.set(key, state, cache.ttl(key) or settings.ABDM_LINK_OTP_TTL)
        return None, "Incorrect OTP"
    cache.delete(key)
    return state, None


def link_confirm(health_facility, body, request_id):
    reply = {"response": {"requestId": request_id}}
    state, message = verify_link_otp(health_facility, body.get("confirmation") or {})
    if state is None:
        reply["error"] = {"code": UNKNOWN_ERROR, "message": message}
    else:
        care_contexts = list(
            CareContext.objects.filter(id__in=state["care_contexts"]).select_related(
                "patient", "encounter"
            )
        )
        for care_context in care_contexts:
            care_context.status = CareContextStatus.linked
            care_context.linked_at = timezone.now()
            care_context.linked_abha_address = state["abha_address"]
            care_context.error = None
            care_context.save()
        reply["patient"] = care_context_entries(care_contexts[0].patient, care_contexts)
    gateway.post(
        "/api/hiecm/user-initiated-linking/v3/link/care-context/on-confirm",
        reply,
        hip_id=health_facility.hip_id,
    )


# --- Consent and data transfer -----------------------------------------------


def consent_notify(health_facility, body, request_id):
    notification = body.get("notification") or {}
    consent_id = notification.get("consentId")
    detail = notification.get("consentDetail") or {}
    status = notification.get("status") or ""
    if consent_id:
        consent = Consent.objects.filter(consent_id=consent_id).first()
        if consent is None:
            consent = Consent(consent_id=consent_id, health_facility=health_facility)
        if consent.health_facility_id == health_facility.id:
            consent.status = status
            if detail:
                consent.detail = detail
            if notification.get("signature"):
                consent.signature = notification["signature"]
            consent.save()
    gateway.post(
        "/api/hiecm/consent/v3/request/hip/on-notify",
        {
            "acknowledgement": {"status": "OK", "consentId": consent_id},
            "response": {"requestId": request_id},
        },
        hip_id=health_facility.hip_id,
    )


def is_public_https(url):
    parsed = urlparse(url or "")
    if parsed.scheme != "https" or not parsed.hostname:
        return False
    try:
        addresses = socket.getaddrinfo(parsed.hostname, parsed.port or 443)
    except socket.gaierror:
        return False
    return all(ipaddress.ip_address(address[4][0]).is_global for address in addresses)


def hi_request_error(consent, hi_request):
    if consent is None or consent.status != "GRANTED":
        return "Consent is not granted"
    permission = consent.detail.get("permission") or {}
    erase_at = parse_time(permission.get("dataEraseAt"))
    if erase_at and erase_at < timezone.now():
        return "Consent has expired"
    requested = hi_request.get("dateRange") or {}
    allowed = permission.get("dateRange") or {}
    start, end = parse_time(requested.get("from")), parse_time(requested.get("to"))
    allowed_start, allowed_end = parse_time(allowed.get("from")), parse_time(allowed.get("to"))
    if not start or not end or start > end:
        return "Date range is invalid"
    if (allowed_start and start < allowed_start) or (allowed_end and end > allowed_end):
        return "Date range is outside the consented range"
    key_material = hi_request.get("keyMaterial") or {}
    public_key = key_material.get("dhPublicKey") or {}
    if not public_key.get("keyValue") or not key_material.get("nonce"):
        return "Key material is missing"
    expiry = parse_time(public_key.get("expiry"))
    if expiry and expiry < timezone.now():
        return "Key material has expired"
    if not is_public_https(hi_request.get("dataPushUrl")):
        return "Data push url is not a public https url"
    return None


def health_information_request(health_facility, body, request_id):
    transaction_id = body.get("transactionId")
    hi_request = body.get("hiRequest") or {}
    consent = Consent.objects.filter(
        consent_id=(hi_request.get("consent") or {}).get("id"),
        health_facility=health_facility,
    ).first()
    error = hi_request_error(consent, hi_request)
    transfer, created = DataTransfer.objects.get_or_create(
        transaction_id=transaction_id,
        defaults={
            "consent": consent,
            "health_facility": health_facility,
            "status": "ERRORED" if error else "ACKNOWLEDGED",
            "request": hi_request,
            "result": {"error": error} if error else {},
        },
    )
    if not created:
        error = error or "Transaction already processed"
    reply = {
        "hiRequest": {
            "transactionId": transaction_id,
            "sessionStatus": "ERRORED" if error else "ACKNOWLEDGED",
        },
        "response": {"requestId": request_id},
    }
    if error:
        reply["error"] = {"code": UNKNOWN_ERROR, "message": error}
    gateway.post(
        "/api/hiecm/data-flow/v3/health-information/hip/on-request",
        reply,
        hip_id=health_facility.hip_id,
    )
    if not error:
        transfer_health_information(transfer)


def bundles_for(consent, hi_request, health_facility):
    """Yield (care context reference, bundle) for everything the consent covers."""
    detail = consent.detail
    references = [
        item.get("careContextReference") for item in detail.get("careContexts") or []
    ]
    hi_types = [t for t in detail.get("hiTypes") or [] if t in BUILDERS]
    date_range = hi_request.get("dateRange") or {}
    start, end = parse_time(date_range.get("from")), parse_time(date_range.get("to"))
    care_contexts = CareContext.objects.filter(
        reference_number__in=references, health_facility=health_facility
    ).select_related("encounter", "encounter__patient")
    found = set()
    for care_context in care_contexts:
        found.add(care_context.reference_number)
        if not start <= encounter_start(care_context.encounter) <= end:
            yield care_context.reference_number, None
            continue
        for hi_type in hi_types:
            bundle = BUILDERS[hi_type](care_context.encounter, health_facility)
            if bundle:
                yield care_context.reference_number, bundle
    for reference in references:
        if reference not in found:
            yield reference, None


def push_page(url, payload, health_facility):
    """POST one page to the HIU's data push url, logged like any other call."""
    exchange = Exchange.objects.create(
        request_id=str(uuid4()),
        direction=Exchange.Direction.outbound,
        path=urlparse(url).path,
        hip_id=health_facility.hip_id,
        status=Exchange.Status.sent,
        body=gateway.redact(payload),
        context={"data_push": True, "transaction_id": payload["transactionId"]},
    )
    try:
        response = requests.post(
            url, json=payload, timeout=settings.ABDM_REQUEST_TIMEOUT, allow_redirects=False
        )
    except requests.RequestException as e:
        exchange.status = Exchange.Status.failed
        exchange.message = str(e)[:500]
        exchange.save()
        return False
    exchange.http_status = response.status_code
    accepted = response.status_code < 300  # noqa: PLR2004
    exchange.status = Exchange.Status.accepted if accepted else Exchange.Status.refused
    exchange.message = "" if accepted else response.text[:500]
    exchange.save()
    return accepted


def transfer_health_information(transfer):
    health_facility = transfer.health_facility
    hi_request = transfer.request
    key_material = hi_request["keyMaterial"]
    peer_key = key_material["dhPublicKey"]["keyValue"]
    peer_nonce = key_material["nonce"]

    produced = list(bundles_for(transfer.consent, hi_request, health_facility))
    pages = [(reference, bundle) for reference, bundle in produced if bundle]
    statuses = {}
    for reference, bundle in produced:
        if bundle is None:
            statuses.setdefault(reference, ("ERRORED", "No records in the requested range"))

    for page_number, (reference, bundle) in enumerate(pages, start=1):
        data = json.dumps(bundle, separators=(",", ":")).encode()
        # A fresh key pair per page, so no key and IV pair is ever reused.
        key_pair = KeyPair.generate()
        payload = {
            "pageNumber": page_number,
            "pageCount": len(pages),
            "transactionId": transfer.transaction_id,
            "entries": [
                {
                    "content": key_pair.encrypt(data, peer_key, peer_nonce),
                    "media": "application/fhir+json",
                    "checksum": hashlib.md5(data, usedforsecurity=False).hexdigest(),
                    "careContextReference": reference,
                }
            ],
            "keyMaterial": {
                "cryptoAlg": "ECDH",
                "curve": "Curve25519",
                "dhPublicKey": {
                    "expiry": (timezone.now() + DATA_KEY_VALIDITY)
                    .astimezone(UTC)
                    .isoformat(timespec="milliseconds")
                    .replace("+00:00", "Z"),
                    "parameters": KEY_PARAMETERS,
                    "keyValue": key_pair.key_value,
                },
                "nonce": key_pair.nonce_value,
            },
        }
        if push_page(hi_request["dataPushUrl"], payload, health_facility):
            if statuses.get(reference, ("DELIVERED",))[0] != "ERRORED":
                statuses[reference] = ("DELIVERED", "Delivered")
        else:
            statuses[reference] = ("ERRORED", "The HIU did not accept the data")

    delivered = any(status == "DELIVERED" for status, _ in statuses.values())
    session_status = "TRANSFERRED" if delivered else "FAILED"
    transfer.status = session_status
    transfer.result = {
        "pages": len(pages),
        "statuses": {ref: status for ref, (status, _) in statuses.items()},
    }
    transfer.save(update_fields=["status", "result", "modified_date"])
    notify_transfer(transfer, session_status, statuses)


def notify_transfer(transfer, session_status, statuses):
    hip_id = transfer.health_facility.hip_id
    try:
        gateway.post(
            "/api/hiecm/data-flow/v3/health-information/notify",
            {
                "notification": {
                    "consentId": transfer.consent.consent_id if transfer.consent else "",
                    "transactionId": transfer.transaction_id,
                    "doneAt": utc_timestamp(),
                    "notifier": {"type": "HIP", "id": hip_id},
                    "statusNotification": {
                        "sessionStatus": session_status,
                        "hipId": hip_id,
                        "statusResponses": [
                            {
                                "careContextReference": reference,
                                "hiStatus": status,
                                "description": description,
                            }
                            for reference, (status, description) in statuses.items()
                        ],
                    },
                }
            },
            hip_id=hip_id,
        )
    except AbdmError:
        logger.warning("ABDM data flow notify refused for %s", transfer.transaction_id)


# --- Inbound requests ---------------------------------------------------------

REQUEST_HANDLERS = {
    "/api/v3/hip/patient/care-context/discover": discover,
    "/api/v3/hip/link/care-context/init": link_init,
    "/api/v3/hip/link/care-context/confirm": link_confirm,
    "/api/v3/consent/request/hip/notify": consent_notify,
    "/api/v3/hip/health-information/request": health_information_request,
}
"}

