{"content": """"The bridge: every call ABDM makes to Care lands here.

Each call is checked, logged whole (redacted) and answered at once with a 202.
The work happens afterwards in a task, so ABDM is never kept waiting.
"""

import json

from django.conf import settings
from django.db import transaction
from django.http import HttpResponse, JsonResponse
from django.views.decorators.csrf import csrf_exempt
from django.views.decorators.http import require_POST

from care.abdm.models import Exchange, HealthFacility
from care.abdm.service.gateway import header_lengths, redact
from care.abdm.service.m2 import REQUEST_HANDLERS
from care.abdm.tasks import process_callback

# Answers to calls Care made, keyed by the callback path ABDM uses.
ANSWER_PATHS = {
    "/api/v3/hip/token/on-generate-token",
    "/api/v3/link/on_carecontext",
    "/api/v3/links/context/on-notify",
    "/api/v3/patients/sms/on-notify",
}
LOGGED_HEADERS = ("Authorization", "REQUEST-ID", "TIMESTAMP", "X-HIP-ID", "X-CM-ID")


def reject(exchange, status, message):
    exchange.status = Exchange.Status.rejected
    exchange.http_status = status
    exchange.message = message
    exchange.save()
    return JsonResponse({"error": {"message": message}}, status=status)


@csrf_exempt
@require_POST
def callback(request, path):
    if not settings.ABDM_ENABLED:
        return HttpResponse(status=404)
    path = f"/{path.strip('/')}"
    hip_id = request.headers.get("X-HIP-ID", "")
    try:
        body = json.loads(request.body or b"{}")
    except ValueError:
        body = None

    exchange = Exchange(
        request_id=request.headers.get("REQUEST-ID", ""),
        direction=Exchange.Direction.inbound,
        path=path,
        hip_id=hip_id,
        status=Exchange.Status.received,
        headers=header_lengths(
            {name: request.headers[name] for name in LOGGED_HEADERS if name in request.headers}
        ),
        body=redact(body) if isinstance(body, dict) else {"length": len(request.body)},
    )

    authorization = request.headers.get("Authorization", "")
    if not authorization.startswith("Bearer ") or not authorization[7:].strip():
        return reject(exchange, 401, "A bearer token is required")
    if not isinstance(body, dict):
        return reject(exchange, 400, "The body must be a JSON object")

    outbound = None
    if path in ANSWER_PATHS:
        answered = (body.get("response") or {}).get("requestId")
        outbound = Exchange.objects.filter(
            direction=Exchange.Direction.outbound, request_id=answered or ""
        ).first()
        if outbound is None:
            return reject(exchange, 400, "response.requestId matches no request")
        if hip_id and outbound.hip_id and hip_id != outbound.hip_id:
            return reject(exchange, 400, "X-HIP-ID does not match the request")
        exchange.context = {"answers": answered}
    elif path in REQUEST_HANDLERS:
        if not HealthFacility.objects.filter(hip_id=hip_id, active=True).exists():
            return reject(exchange, 400, "X-HIP-ID is not a facility of this HIP")
    else:
        return reject(exchange, 404, "Unknown callback")

    exchange.save()
    if outbound is not None:
        error = body.get("error") if isinstance(body.get("error"), dict) else {}
        outbound.status = Exchange.Status.answered
        outbound.answer = exchange.body
        outbound.error_code = outbound.error_code or str(error.get("code") or "")
        outbound.message = outbound.message or str(error.get("message") or "")
        outbound.save()
    transaction.on_commit(lambda: process_callback.delay(exchange.id, body))
    return HttpResponse(status=202)
