{"content": "import logging

from celery import shared_task

from care.abdm.models import Exchange, HealthFacility
from care.abdm.service import m2

logger = logging.getLogger(__name__)


@shared_task
def link_care_contexts(care_context_ids):
    m2.link_care_contexts(care_context_ids)


@shared_task
def process_callback(exchange_id, body):
    exchange = Exchange.objects.get(id=exchange_id)
    try:
        if exchange.path in m2.REQUEST_HANDLERS:
            health_facility = HealthFacility.objects.get(hip_id=exchange.hip_id)
            m2.REQUEST_HANDLERS[exchange.path](
                health_facility, body, exchange.request_id
            )
        else:
            outbound = Exchange.objects.get(
                direction=Exchange.Direction.outbound,
                request_id=exchange.context["answers"],
            )
            m2.process_answer(outbound, body)
    except Exception as e:
        logger.exception("ABDM callback %s failed", exchange.path)
        exchange.status = Exchange.Status.failed
        exchange.message = str(e)[:1000]
        exchange.save(update_fields=["status", "message", "modified_date"])
        return
    exchange.status = Exchange.Status.processed
    exchange.save(update_fields=["status", "modified_date"])
