{"content": "from django.conf import settings
from django.db import transaction
from django.db.models.signals import post_save
from django.dispatch import receiver

from care.abdm.models import AbhaNumber, CareContext, CareContextStatus
from care.abdm.service.m2 import ensure_care_context
from care.abdm.tasks import link_care_contexts
from care.emr.models import Encounter

# An encounter becomes a care context once its records are settled.
CLOSED_ENCOUNTER_STATUSES = {"completed", "discharged"}


def enqueue_linking(care_context_ids):
    if care_context_ids:
        transaction.on_commit(lambda: link_care_contexts.delay(care_context_ids))


@receiver(post_save, sender=Encounter)
def encounter_closed(sender, instance, **kwargs):
    if not settings.ABDM_ENABLED or instance.status not in CLOSED_ENCOUNTER_STATUSES:
        return
    care_context = ensure_care_context(instance)
    if care_context and care_context.status != CareContextStatus.linked:
        enqueue_linking([care_context.id])


@receiver(post_save, sender=AbhaNumber)
def abha_linked(sender, instance, **kwargs):
    """Records closed before the patient had an ABHA are linked once they do."""
    if not settings.ABDM_ENABLED or instance.patient_id is None:
        return
    care_context_ids = list(
        CareContext.objects.filter(patient_id=instance.patient_id)
        .exclude(status=CareContextStatus.linked)
        .values_list("id", flat=True)
    )
    enqueue_linking(care_context_ids)
