from care.abdm.service.client import AbdmError, request


class Command(BaseCommand):
    help = "Point the ABDM bridge at ABDM_CALLBACK_BASE_URL and list its services."

    def add_arguments(self, parser):
        parser.add_argument(
            "--check", action="store_true", help="Only list the registered services"
        )

    def handle(self, *args, **options):
        gateway = f"{settings.ABDM_GATEWAY_URL}/api/hiecm/gateway/v3"
        headers = {"X-CM-ID": settings.ABDM_CM_ID}
        try:
            if not options["check"]:
                base = settings.ABDM_CALLBACK_BASE_URL.rstrip("/")
                if not base.startswith("https://"):
                    msg = "ABDM_CALLBACK_BASE_URL must be an https url"
                    raise CommandError(msg)
                url = f"{base}/api/abdm"
                request("PATCH", f"{gateway}/bridge/url", headers=headers, json={"url": url})
                self.stdout.write(self.style.SUCCESS(f"Bridge url set to {url}"))
            services = request("GET", f"{gateway}/bridge-services", headers=headers).json()
        except AbdmError as e:
            raise CommandError(f"{e.code or e.status}: {e.message}") from e
        for service in services if isinstance(services, list) else [services]:
            self.stdout.write(str(service))
