from django.core.management.base import BaseCommand, CommandError

from care.abdm.service.client import AbdmError, request

BRIDGE_PATH = "/api/abdm"


class Command(BaseCommand):
    help = (
        "Point the ABDM bridge at this deployment's callback url "
        f"(ABDM_CALLBACK_BASE_URL + {BRIDGE_PATH}) and list its services."
    )

    def add_arguments(self, parser):
        parser.add_argument(
            "--base-url",
            help="Public https origin to use instead of ABDM_CALLBACK_BASE_URL",
        )
        parser.add_argument(
            "--check",
            action="store_true",
            help="Only list the services registered on the bridge",
        )

    def handle(self, *args, **options):
        gateway = f"{settings.ABDM_GATEWAY_URL}/api/hiecm/gateway/v3"
        headers = {"X-CM-ID": settings.ABDM_CM_ID}
        try:
