{"content": "from django.conf import settings
from django.core.cache import cache
from django.db import transaction
from django.db.models.signals import post_save
from django.dispatch import receiver

from care.abdm.models import AbhaNumber, CareContext, CareContextStatus
from care.abdm.service.m2 import ensure_care_context
from care.abdm.tasks import link_care_contexts, notify_care_context_update
from care.emr.models import (
    AllergyIntolerance,
    Condition,
    DiagnosticReport,
    Encounter,
    MedicationRequest,
    Observation,
    ServiceRequest,
)

# An encounter becomes a care context once its records are settled.
CLOSED_ENCOUNTER_STATUSES = {"completed", "discharged"}
# Edits within this window are told to ABDM once.
RECORDS_SETTLE_SECONDS = 30
RECORD_MODELS = (
    AllergyIntolerance,
    Condition,
    DiagnosticReport,
    MedicationRequest,
    Observation,
    ServiceRequest,
)


def enqueue_linking(care_context_ids):
    if care_context_ids:
        transaction.on_commit(lambda: link_care_contexts.delay(care_context_ids))


@receiver(post_save, sender=Encounter)
def encounter_closed(sender, instance, **kwargs):
    if not settings.ABDM_ENABLED or instance.status not in CLOSED_ENCOUNTER_STATUSES:
        return
    care_context = ensure_care_context(instance)
    if care_context and care_context.status != CareContextStatus.linked:
        enqueue_linking([care_context.id])


@receiver(post_save, sender=AbhaNumber)
def abha_linked(sender, instance, **kwargs):
    """Records closed before the patient had an ABHA are linked once they do."""
    if not settings.ABDM_ENABLED or instance.patient_id is None:
        return
    care_context_ids = list(
        CareContext.objects.filter(patient_id=instance.patient_id)
        .exclude(status=CareContextStatus.linked)
        .values_list("id", flat=True)
    )
    enqueue_linking(care_context_ids)


def records_changed(sender, instance, **kwargs):
    """Records written after an encounter closed reach ABDM as a link or an update."""
    encounter_id = getattr(instance, "encounter_id", None)
    if not settings.ABDM_ENABLED or encounter_id is None:
        return
    care_context = (
        CareContext.objects.filter(encounter_id=encounter_id).only("id", "status").first()
    )
    if care_context is None or not cache.add(
        f"abdm:m2:records-changed:{care_context.id}", 1, RECORDS_SETTLE_SECONDS
    ):
        return
    if care_context.status == CareContextStatus.linked:
        task, args = notify_care_context_update, [care_context.id]
    else:
        task, args = link_care_contexts, [[care_context.id]]
    transaction.on_commit(
        lambda: task.apply_async(args=args, countdown=RECORDS_SETTLE_SECONDS)
    )


for model in RECORD_MODELS:
    post_save.connect(records_changed, sender=model, dispatch_uid=f"abdm-{model.__name__}")
