def send_deep_link_sms(care_context_id):
    """Ask ABDM to text a patient without an ABHA that records await them here."""
    care_context = (
        CareContext.objects.filter(id=care_context_id, sms_notified_at__isnull=True)
        .select_related("health_facility__facility", "patient", "encounter")
        .first()
    )
    if care_context is None or AbhaNumber.objects.filter(
        patient=care_context.patient
    ).exists():
        return
    phone = "".join(ch for ch in care_context.patient.phone_number if ch.isdigit())
    if len(phone) < 10 or not available_hi_types(care_context.encounter):  # noqa: PLR2004
        return
    health_facility = care_context.health_facility
    try:
        gateway.post(
            "/api/hiecm/hip/v3/link/patient/links/sms/notify2",
