                    "phoneNo": phone[-10:],
                    "hip": {
                        "id": health_facility.hip_id,
                        "name": health_facility.facility.name,
                    },
                }
            },
            hip_id=health_facility.hip_id,
            context={"care_context": care_context.id},
        )
    except AbdmError as e:
        logger.warning("ABDM deep link SMS refused: %s %s", e.code, e.message)
        return
    care_context.sms_notified_at = timezone.now()
    care_context.save(update_fields=["sms_notified_at", "modified_date"])","oldString":"ANSWER_HANDLERS = {
