{"content": "export const ABDM_HI_TYPES = [
  "OPConsultation",
  "Prescription",
  "DiagnosticReport",
] as const;

export type AbdmHiType = (typeof ABDM_HI_TYPES)[number];

export type CareContextStatus =
  | "pending"
  | "awaiting_link_token"
  | "linking"
  | "linked"
  | "failed";

export interface AbdmError {
  code?: string | null;
  message?: string;
  request_id?: string;
  at?: string;
}

export interface CareContext {
  id: string;
  reference_number: string;
  display: string;
  status: CareContextStatus;
  hi_types: string[];
  linked_abha_address: string;
  linked_at: string | null;
  sms_notified_at: string | null;
  error: AbdmError | null;
  created_date: string;
  modified_date: string;
}

export interface AbdmConsent {
  consent_id: string;
  status: string;
  purpose: string;
  hi_types: string[];
  date_range: { from?: string; to?: string };
  data_erase_at: string | null;
  requested_at: string | null;
  modified_date: string;
}

export interface AbdmDataTransfer {
  transaction_id: string;
  consent_id: string | null;
  status: string;
  care_context_status: string | null;
  error: string | null;
  created_date: string;
  modified_date: string;
}

export interface AbdmExchange {
  id: number;
  direction: "inbound" | "outbound";
  path: string;
  status: string;
  error_code: string;
  message: string;
  created_date: string;
  modified_date: string;
}

export interface EncounterAbdmSummary {
  hip_id: string | null;
  abha_address: string | null;
  encounter_closed: boolean;
  available_hi_types: string[];
  care_context: CareContext | null;
  consents: AbdmConsent[];
  transfers: AbdmDataTransfer[];
  activity: AbdmExchange[];
}
