{"content": "import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  AlertCircleIcon,
  CloudOffIcon,
  FileClockIcon,
  RefreshCwIcon,
  ShieldCheckIcon,
} from "lucide-react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { EmptyState } from "@/components/ui/empty-state";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import { TableSkeleton } from "@/components/Common/SkeletonLoading";

import { getAbhaError } from "@/components/Abdm/utils";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import {
  AbdmExchange,
  CareContextStatus,
  EncounterAbdmSummary,
} from "@/types/abdm/careContext";
import careContextApi from "@/types/abdm/careContextApi";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { formatDateTime } from "@/Utils/utils";

type BadgeVariant = React.ComponentProps<typeof Badge>["variant"];

const POLL_INTERVAL_MS = 15000;
const IN_FLIGHT: CareContextStatus[] = ["awaiting_link_token", "linking"];

const CARE_CONTEXT_STATUS_VARIANT: Record<CareContextStatus, BadgeVariant> = {
  pending: "secondary",
  awaiting_link_token: "blue",
  linking: "blue",
  linked: "green",
  failed: "destructive",
};

const EXCHANGE_STATUS_VARIANT: Record<string, BadgeVariant> = {
  sent: "secondary",
  accepted: "blue",
  answered: "green",
  received: "blue",
  processed: "green",
  refused: "destructive",
  rejected: "destructive",
  failed: "destructive",
};

// The gateway calls Care makes for a care context, by what they do.
const ACTIVITY_LABELS: Record<string, string> = {
  "/api/hiecm/v3/token/generate-token": "abdm__activity_link_token",
  "/api/hiecm/hip/v3/link/carecontext": "abdm__activity_link",
  "/api/hiecm/hip/v3/link/context/notify": "abdm__activity_update",
  "/api/hiecm/hip/v3/link/patient/links/sms/notify2": "abdm__activity_sms",
  "/api/hiecm/data-flow/v3/health-information/notify":
    "abdm__activity_transfer_notify",
};

function dateTime(value?: string | null) {
  return value ? formatDateTime(value, "DD MMM YYYY, hh:mm A") : "-";
}

function shortId(value: string) {
  return value.length > 12 ? `${value.slice(0, 8)}…` : value;
}

function Detail({ label, value }: { label: string; value: React.ReactNode }) {
  return (
    <div className="flex flex-col gap-1">
      <span className="text-xs text-gray-500">{label}</span>
      <span className="text-sm font-medium break-all">{value}</span>
    </div>
  );
}

function LinkStatusCard({
  summary,
  onSync,
  isSyncing,
}: {
  summary: EncounterAbdmSummary;
  onSync: () => void;
  isSyncing: boolean;
}) {
  const { t } = useTranslation();
  const careContext = summary.care_context;
  const shared = new Set(careContext?.hi_types ?? []);
  const hasRecords = summary.available_hi_types.length > 0;
  const hasUnshared = summary.available_hi_types.some(
    (type) => !shared.has(type),
  );
  const inFlight = !!careContext && IN_FLIGHT.includes(careContext.status);
  const canSync =
    summary.encounter_closed &&
    hasRecords &&
    !inFlight &&
    (careContext?.status !== "linked" || hasUnshared);

  const status = careContext?.status;
  const description = !summary.encounter_closed
    ? t("abdm__status_desc_open_encounter")
    : !hasRecords
      ? t("abdm__status_desc_no_records")
      : status
        ? t(`abdm__status_desc_${status}`)
        : t("abdm__status_desc_not_created");

  return (
    <Card>
      <CardHeader className="flex flex-row flex-wrap items-start justify-between gap-2 space-y-0">
