export const EncounterAbdmTab = () => {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const { selectedEncounterId: encounterId } = useEncounter();
  const queryKey = ["abdm_care_context", encounterId];

  const { data: summary, isLoading } = useQuery({
    queryKey,
    queryFn: query(careContextApi.getForEncounter, {
      queryParams: { encounter: encounterId },
    }),
    enabled: !!encounterId,
    // ABDM answers asynchronously; keep checking while a link is in flight.
    refetchInterval: (state) => {
      const status = state.state.data?.care_context?.status;
      return status && IN_FLIGHT.includes(status) ? POLL_INTERVAL_MS : false;
    },
  });

  const { mutate: sync, isPending: isSyncing } = useMutation({
    mutationFn: mutate(careContextApi.sync, { silent: true }),
    onSuccess: (result) => {
      queryClient.setQueryData(queryKey, result);
      toast.success(t("abdm__sync_started"));
    },
    onError: (error) =>
      toast.error(getAbhaError(error, t("abdm__sync_failed")).msg),
  });

  if (isLoading || !summary) {
    return <TableSkeleton count={4} />;
  }

  if (!summary.hip_id) {
    return (
      <EmptyState
        icon={<CloudOffIcon />}
        title={t("abdm__facility_not_registered")}
        description={t("abdm__facility_not_registered_desc")}
      />
    );
  }

  return (
    <div className="flex flex-col gap-4">
      <LinkStatusCard
        summary={summary}
        isSyncing={isSyncing}
        onSync={() => sync({ encounter: encounterId })}
      />
      {summary.care_context && (
        <>
          <ConsentsCard summary={summary} />
          <TransfersCard summary={summary} />
          <ActivityCard activity={summary.activity} />
        </>
      )}
    </div>
  );
};
