import sys
from pathlib import Path

base = Path(sys.argv[1])


def strip(node):
    if isinstance(node, dict):
        out = {}
        for key, value in node.items():
            if key in ("description", "pattern", "maximum", "minimum", "format"):
                continue
            out[key] = strip(value)
        return out
    if isinstance(node, list):
        return [strip(item) for item in node]
    return node


def shape(node, depth=0):
    """Compact field tree: name(type)[req] ..."""
    pad = "  " * depth
    lines = []
    props = node.get("properties") or {}
    required = set(node.get("required") or [])
    for name, prop in props.items():
        kind = prop.get("type", "")
        extra = ""
        if "enum" in prop:
            extra = f" enum={prop['enum']}"
        if "example" in prop and kind not in ("object", "array"):
            extra += f" eg={json.dumps(prop['example'])[:60]}"
        lines.append(f"{pad}{name}:{kind}{'*' if name in required else ''}{extra}")
        if kind == "object":
            lines += shape(prop, depth + 1)
        elif kind == "array" and isinstance(prop.get("items"), dict):
            items = prop["items"]
            if items.get("type") == "object" or items.get("properties"):
                lines += shape(items, depth + 1)
            elif "enum" in items:
                lines.append(f"{pad}  [items enum={items['enum']}]")
    return lines


for name in sys.argv[2:]:
    data = json.loads((base / name / "content.json").read_text())
    spec = data.get("spec", data)
    print("=" * 10, data.get("operation_id"), spec.get("path", ""))
    print("headers:", [p.get("name") for p in spec.get("parameters", [])])
    body = spec.get("requestBody", {}).get("content", {}).get("application/json", {})
    schema = strip(body.get("schema") or {})
    print("\n".join(shape(schema)))
