{"filePath": "/Users/rithviknishad/ohc.network/care/care/abdm/service/m3.py", "content": """"ABDM M3: Care as a Health Information User.

A consent request goes to the patient; each HIP they grant gets an artefact,
which is fetched and then used to request the records. The HIP pushes them,
encrypted for a key made for that request, straight to the data push url.
"""

import hashlib
import json
import logging
from datetime import UTC, timedelta

from cryptography.exceptions import InvalidTag
from django.conf import settings
from django.db import transaction
from django.utils import timezone

from care.abdm.models import (
    ConsentArtefact,
    ConsentRequest,
    ConsentRequestStatus,
    FetchedRecord,
    HealthInformationFetch,
    HealthInformationFetchStatus,
)
from care.abdm.service import gateway
from care.abdm.service.client import AbdmError, utc_timestamp
from care.abdm.service.fidelius import KEY_PARAMETERS, KeyPair
from care.abdm.service.m2 import answer_error, parse_time

logger = logging.getLogger(__name__)

PURPOSES = {
    "CAREMGT": "Care Management",
    "BTG": "Break the Glass",
    "PUBHLTH": "Public Health",
    "HPAYMT": "Healthcare Payment",
    "DSRCH": "Disease Specific Healthcare Research",
    "PATRQT": "Self Requested",
}
HI_TYPES = (
    "OPConsultation",
    "Prescription",
    "DischargeSummary",
    "DiagnosticReport",
    "ImmunizationRecord",
    "HealthDocumentRecord",
    "WellnessRecord",
    "Invoice",
)
PURPOSE_REF_URI = "http://terminology.hl7.org/ValueSet/v3-PurposeOfUse"
KEY_VALIDITY = timedelta(days=1)
# A notification or page can overtake the answer that tells us its id.
EARLY_RETRY_DELAY = 60
EARLY_RETRY_LIMIT = 30
DATA_PUSH_PATH = "/api/abdm/hiu/data-push"


def iso(value):
    return (
        value.astimezone(UTC).isoformat(timespec="milliseconds").replace("+00:00", "Z")
    )


def failure(error, **extra):
    return {
        "code": error.get("code"),
        "message": error.get("message"),
        "at": timezone.now().isoformat(),
        **extra,
    }


def refusal(error):
    return failure({"code": error.code or error.status, "message": error.message})


# --- Consent request -----------------------------------------------------------


def request_consent(consent_request, requester):
    """Send a consent request to the patient's consent manager."""
    hiu_id = consent_request.health_facility.hip_id
    body = {
        "consent": {
            "purpose": {
                "text": PURPOSES[consent_request.purpose],
                "code": consent_request.purpose,
                "refUri": PURPOSE_REF_URI,
            },
            "patient": {"id": consent_request.abha_address},
            "hiu": {"id": hiu_id},
            "requester": {
                "name": requester.full_name or requester.username,
                "identifier": {
                    "type": "REGNO",
                    "value": str(requester.external_id),
                    "system": "https://www.mciindia.org",
                },
            },
            "hiTypes": consent_request.hi_types,
            "permission": {
                "accessMode": "VIEW",
                "dateRange": {
                    "from": iso(consent_request.date_from),
                    "to": iso(consent_request.date_to),
                },
                "dataEraseAt": iso(consent_request.erase_at),
                "frequency": {"unit": "HOUR", "value": 1, "repeats": 0},
            },
        }
    }
    try:
        gateway.post(
            "/api/hiecm/consent/v3/request/init",
            body,
            facility_id=hiu_id,
            context={"consent_request": consent_request.id},
        )
    except AbdmError as e:
        consent_request.status = ConsentRequestStatus.failed
        consent_request.error = refusal(e)
        consent_request.save(update_fields=["status", "error", "modified_date"])


def on_consent_init(outbound, body):
    consent_request = ConsentRequest.objects.filter(
        id=outbound.context.get("consent_request")
    ).first()
    if consent_request is None:
        return
    error = answer_error(body)
    consent_request_id = (body.get("consentRequest") or {}).get("id")
    if error or not consent_request_id:
        consent_request.status = ConsentRequestStatus.failed
        consent_request.error = failure(
            error or {"message": "No consent request id in the answer"},
            request_id=outbound.request_id,
        )
        consent_request.save(update_fields=["status", "error", "modified_date"])
        return
    consent_request.consent_request_id = consent_request_id
    # A notification can arrive first and has already moved the status on.
    if consent_request.status == ConsentRequestStatus.pending:
        consent_request.status = ConsentRequestStatus.requested
    consent_request.save(
        update_fields=["consent_request_id", "status", "modified_date"]
    )


# --- Consent notification ------------------------------------------------------


def hiu_consent_notify(health_facility, body, request_id):
    notification = body.get("notification") or {}
    artefacts = [
        item.get("id")
        for item in notification.get("consentArtefacts") or []
        if item.get("id")
    ]
    try:
        gateway.post(
            "/api/hiecm/consent/v3/request/hiu/on-notify",
            {
                "acknowledgement": [
                    {"status": "OK", "consentId": artefact_id}
                    for artefact_id in artefacts
                ],
                "response": {"requestId": request_id},
            },
            facility_id=health_facility.hip_id,
        )
    except AbdmError as e:
        logger.warning("ABDM HIU consent on-notify refused: %s %s", e.code, e.message)
    apply_consent_notification(health_facility.id, notification)


def apply_consent_notification(health_facility_id, notification, attempt=0):
    from care.abdm.tasks import apply_consent_notification as retry  # noqa: PLC0415

    status = str(notification.get("status") or "").upper()
    artefact_ids = [
        item.get("id")
        for item in notification.get("consentArtefacts") or []
        if item.get("id")
    ]
    consent_request = ConsentRequest.objects.filter(
        consent_request_id=notification.get("consentRequestId"),
        health_facility_id=health_facility_id,
    ).first()
    if consent_request is None and artefact_ids:
        artefact = (
            ConsentArtefact.objects.filter(artefact_id__in=artefact_ids)
            .select_related("consent_request")
            .first()
        )
        consent_request = artefact.consent_request if artefact else None
    if consent_request is None:
        waiting = ConsentRequest.objects.filter(
            health_facility_id=health_facility_id,
            status=ConsentRequestStatus.pending,
        ).exists()
        if waiting and attempt < EARLY_RETRY_LIMIT:
            retry.apply_async(
                args=[health_facility_id, notification, attempt + 1],
                countdown=EARLY_RETRY_DELAY,
            )
        return

    if status in ("REVOKED", "EXPIRED"):
        revoked = consent_request.artefacts.all()
        if artefact_ids:
            revoked = revoked.filter(artefact_id__in=artefact_ids)
        erase_records(revoked, status)
        if not consent_request.artefacts.exclude(status=status).exists():
            consent_request.status = status.lower()
    elif status in ConsentRequestStatus.values or status.lower() in (
        ConsentRequestStatus.values
    ):
        consent_request.status = status.lower()
    consent_request.reason = str(notification.get("reason") or "")[:1000]
    consent_request.save(update_fields=["status", "reason", "modified_date"])

    if status == "GRANTED":
        for artefact_id in artefact_ids:
            artefact, created = ConsentArtefact.objects.get_or_create(
                artefact_id=artefact_id,
                defaults={"consent_request": consent_request},
            )
            if created:
                transaction.on_commit(
                    lambda pk=artefact.id: fetch_artefact_later(pk)
                )


def fetch_artefact_later(artefact_id):
    from care.abdm.tasks import fetch_consent_artefact  # noqa: PLC0415

    fetch_consent_artefact.delay(artefact_id)


def erase_records(artefacts, status):
    FetchedRecord.objects.filter(fetch__artefact__in=artefacts).delete()
    HealthInformationFetch.objects.filter(artefact__in=artefacts).update(
        key_material=None, modified_date=timezone.now()
    )
    artefacts.update(status=status, modified_date=timezone.now())


# --- Artefact and health information request ----------------------------------


def fetch_artefact(artefact_id):
    artefact = (
        ConsentArtefact.objects.filter(id=artefact_id)
        .select_related("consent_request__health_facility")
        .first()
    )
    if artefact is None:
        return
    try:
        gateway.post(
            "/api/hiecm/consent/v3/fetch",
            {"consentId": artefact.artefact_id},
            hiu_id=artefact.consent_request.health_facility.hip_id,
            context={"artefact": artefact.id},
        )
    except AbdmError as e:
        artefact.error = refusal(e)
        artefact.save(update_fields=["error", "modified_date"])


def on_fetch(outbound, body):
    artefact = (
        ConsentArtefact.objects.filter(id=outbound.context.get("artefact"))
        .select_related("consent_request__health_facility")
        .first()
    )
    if artefact is None:
        return
    error = answer_error(body)
    consent = body.get("consent") or {}
    detail = consent.get("consentDetail") or {}
    if error or not detail:
        artefact.error = failure(
            error or {"message": "No consent detail in the answer"},
            request_id=outbound.request_id,
        )
        artefact.save(update_fields=["error", "modified_date"])
        return
    if detail.get("consentId") != artefact.artefact_id:
        return
    hip = detail.get("hip") or {}
    # A revocation may have been applied while the fetch was in flight.
    if artefact.status in ("REVOKED", "EXPIRED"):
        return
    artefact.status = consent.get("status") or artefact.status
    artefact.detail = detail
    artefact.signature = consent.get("signature") or ""
    artefact.hip_id = hip.get("id") or ""
    artefact.hip_name = hip.get("name") or ""
    artefact.error = None
    artefact.save()
    if artefact.status == "GRANTED" and not artefact.fetches.exists():
        request_health_information(artefact)


def request_health_information(artefact):
    permission = artefact.detail.get("permission") or {}
    consent_request = artefact.consent_request
    hiu_id = consent_request.health_facility.hip_id
    key_pair = KeyPair.generate()
    fetch = HealthInformationFetch.objects.create(
        artefact=artefact,
        status=HealthInformationFetchStatus.requested,
        key_material=key_pair.export(),
    )
    base = settings.ABDM_CALLBACK_BASE_URL.rstrip("/")
    try:
        gateway.post(
            "/api/hiecm/data-flow/v3/health-information/request",
            {
                "hiRequest": {
                    "consent": {"id": artefact.artefact_id},
                    "dateRange": permission.get("dateRange")
                    or {
                        "from": iso(consent_request.date_from),
                        "to": iso(consent_request.date_to),
                    },
                    "dataPushUrl": f"{base}{DATA_PUSH_PATH}",
                    "keyMaterial": {
                        "cryptoAlg": "ECDH",
                        "curve": "Curve25519",
                        "dhPublicKey": {
                            "expiry": iso(timezone.now() + KEY_VALIDITY),
                            "parameters": KEY_PARAMETERS,
                            "keyValue": key_pair.key_value,
                        },
                        "nonce": key_pair.nonce_value,
                    },
                }
            },
            hiu_id=hiu_id,
            context={"fetch": fetch.id},
        )
    except AbdmError as e:
        fetch.status = HealthInformationFetchStatus.failed
        fetch.error = refusal(e)
        fetch.key_material = None
        fetch.save(update_fields=["status", "error", "key_material", "modified_date"])


def on_hi_request(outbound, body):
    fetch = HealthInformationFetch.objects.filter(
        id=outbound.context.get("fetch")
    ).first()
    if fetch is None:
        return
    error = answer_error(body)
    hi_request = body.get("hiRequest") or {}
    transaction_id = hi_request.get("transactionId")
    if error or not transaction_id or hi_request.get("sessionStatus") == "ERRORED":
        fetch.status = HealthInformationFetchStatus.failed
        fetch.error = failure(
            error or {"message": f"Session {hi_request.get('sessionStatus')}"},
            request_id=outbound.request_id,
        )
        fetch.key_material = None
        fetch.save(update_fields=["status", "error", "key_material", "modified_date"])
        return
    fetch.transaction_id = transaction_id
    if fetch.status == HealthInformationFetchStatus.requested:
        fetch.status = HealthInformationFetchStatus.receiving
    fetch.save(update_fields=["transaction_id", "status", "modified_date"])


ANSWER_HANDLERS = {
    "/api/hiecm/consent/v3/request/init": on_consent_init,
    "/api/hiecm/consent/v3/fetch": on_fetch,
    "/api/hiecm/data-flow/v3/health-information/request": on_hi_request,
}

REQUEST_HANDLERS = {
    "/api/v3/hiu/consent/request/notify": hiu_consent_notify,
}


# --- Data push -----------------------------------------------------------------


def is_awaited(transaction_id):
    """A push is only accepted for a session we asked for."""
    if HealthInformationFetch.objects.filter(
        transaction_id=transaction_id,
        status__in=(
            HealthInformationFetchStatus.receiving,
            HealthInformationFetchStatus.requested,
        ),
    ).exists():
        return True
    # The page may overtake the answer that tells us its transaction id.
    return HealthInformationFetch.objects.filter(
        transaction_id__isnull=True,
        status=HealthInformationFetchStatus.requested,
    ).exists()


def decrypt_entry(key_pair, entry, key_material):
    content = entry.get("content")
    if not content:
        return None, "The entry has no content"
    try:
        data = key_pair.decrypt(
            content,
            key_material["dhPublicKey"]["keyValue"],
            key_material["nonce"],
        )
    except (InvalidTag, KeyError, TypeError, ValueError):
        return None, "The entry could not be decrypted"
    checksum = hashlib.md5(data, usedforsecurity=False).hexdigest()
    if entry.get("checksum") and entry["checksum"].lower() != checksum:
        return None, "The checksum does not match"
    try:
        bundle = json.loads(data)
    except ValueError:
        return None, "The entry is not JSON"
    if not isinstance(bundle, dict):
        return None, "The entry is not a FHIR bundle"
    return bundle, None


def process_data_push(payload, attempt=0):
    from care.abdm.tasks import process_data_push as retry  # noqa: PLC0415

    transaction_id = payload.get("transactionId")
    with transaction.atomic():
        fetch = (
            HealthInformationFetch.objects.select_for_update()
            .filter(transaction_id=transaction_id)
            .select_related("artefact__consent_request__health_facility")
            .first()
        )
        if fetch is None:
            if attempt < EARLY_RETRY_LIMIT and is_awaited(transaction_id):
                retry.apply_async(
                    args=[payload, attempt + 1], countdown=EARLY_RETRY_DELAY
                )
            return
        if not fetch.key_material or fetch.status not in (
            HealthInformationFetchStatus.requested,
            HealthInformationFetchStatus.receiving,
        ):
            return
        page_number = payload.get("pageNumber") or 1
        if page_number in fetch.pages_received:
            return

        key_pair = KeyPair.restore(fetch.key_material)
        key_material = payload.get("keyMaterial") or {}
        erase_at = fetch.artefact.consent_request.erase_at
        permission = fetch.artefact.detail.get("permission") or {}
        erase_at = parse_time(permission.get("dataEraseAt")) or erase_at
        statuses = (fetch.error or {}).get("statuses") or {}
        for entry in payload.get("entries") or []:
            reference = str(entry.get("careContextReference") or "")
            bundle, problem = decrypt_entry(key_pair, entry, key_material)
            if problem:
                statuses[reference] = {"status": "ERRORED", "description": problem}
                continue
            FetchedRecord.objects.create(
                fetch=fetch,
                care_context_reference=reference,
                bundle=bundle,
                erase_at=erase_at,
            )
            if statuses.get(reference, {}).get("status") != "ERRORED":
                statuses[reference] = {"status": "OK", "description": "Received"}

        fetch.pages_received = [*fetch.pages_received, page_number]
        fetch.page_count = payload.get("pageCount") or fetch.page_count or 1
        fetch.status = HealthInformationFetchStatus.receiving
        fetch.error = {"statuses": statuses}
        complete = len(fetch.pages_received) >= fetch.page_count
        if complete:
            received = any(s["status"] == "OK" for s in statuses.values())
            fetch.status = (
                HealthInformationFetchStatus.received
                if received
                else HealthInformationFetchStatus.failed
            )
            fetch.key_material = None
        fetch.save()
    if complete:
        notify_received(fetch, statuses)


def notify_received(fetch, statuses):
    hiu_id = fetch.artefact.consent_request.health_facility.hip_id
    received = fetch.status == HealthInformationFetchStatus.received
    try:
        gateway.post(
            "/api/hiecm/data-flow/v3/health-information/notify",
            {
                "notification": {
                    "consentId": fetch.artefact.artefact_id,
                    "transactionId": fetch.transaction_id,
                    "doneAt": utc_timestamp(),
                    "notifier": {"type": "HIU", "id": hiu_id},
                    "statusNotification": {
                        "sessionStatus": "RECEIVED" if received else "FAILED",
                        "hipId": fetch.artefact.hip_id,
                        "statusResponses": [
                            {
                                "careContextReference": reference,
                                "hiStatus": item["status"],
                                "description": item["description"],
                            }
                            for reference, item in statuses.items()
                        ],
                    },
                }
            },
            facility_id=hiu_id,
        )
    except AbdmError as e:
        logger.warning("ABDM HIU data flow notify refused: %s %s", e.code, e.message)


# --- Retention -----------------------------------------------------------------


def purge_expired_records():
    """Erase records past the time the patient allowed them to be kept."""
    now = timezone.now()
    FetchedRecord.objects.filter(erase_at__lte=now).delete()
    expired = ConsentRequest.objects.filter(
        erase_at__lte=now, status=ConsentRequestStatus.granted
    )
    erase_records(ConsentArtefact.objects.filter(consent_request__in=expired), "EXPIRED")
    expired.update(status=ConsentRequestStatus.expired, modified_date=now)
