@require_POST
def data_push(request):
    """Where a HIP pushes the records we asked for, outside the gateway.

    It carries no gateway token, so a page is only taken for a session we
    opened; the content can only be read with the key made for that session.
    """
    if not settings.ABDM_ENABLED:
        return HttpResponse(status=404)
    try:
        body = json.loads(request.body or b"{}")
    except ValueError:
        body = None
    exchange = Exchange(
        request_id=str(uuid4()),
        direction=Exchange.Direction.inbound,
        path=request.path,
        status=Exchange.Status.received,
        body=redact(body) if isinstance(body, dict) else {"length": len(request.body)},
    )
    if not isinstance(body, dict) or not isinstance(body.get("entries"), list):
        return reject(exchange, 400, "The body must be a data push page")
    transaction_id = str(body.get("transactionId") or "")
    if not transaction_id or not is_awaited(transaction_id):
        return reject(exchange, 400, "No health information request awaits this")
    exchange.context = {"data_push": True, "transaction_id": transaction_id}
    exchange.save()
    transaction.on_commit(lambda: process_data_push.delay(body))
