)
from care.abdm.service.m3 import HI_TYPES, PURPOSES
from care.abdm.tasks import request_consent
from care.emr.models import Encounter
from care.security.authorization import AuthorizationController
from care.utils.shortcuts import get_object_or_404


class ConsentRequestCreate(BaseModel):
    encounter: str
    purpose: str
    hi_types: list[str] = Field(min_length=1)
    date_from: datetime
    date_to: datetime
    erase_at: datetime

    @field_validator("purpose")
    @classmethod
    def known_purpose(cls, value):
        if value not in PURPOSES:
            msg = "Unknown purpose"
            raise ValueError(msg)
        return value

    @field_validator("hi_types")
    @classmethod
    def known_hi_types(cls, value):
        if set(value) - set(HI_TYPES):
            msg = "Unknown health information type"
            raise ValueError(msg)
        return list(dict.fromkeys(value))

    @model_validator(mode="after")
    def valid_dates(self):
        if self.date_from > self.date_to:
            msg = "The start date must be before the end date"
            raise ValueError(msg)
        if self.erase_at <= timezone.now():
            msg = "The erase date must be in the future"
            raise ValueError(msg)
        return self


def iso(value):
    return value.isoformat() if value else None


def serialize_consent_request(consent_request):
    return {
        "id": str(consent_request.external_id),
        "consent_request_id": consent_request.consent_request_id,
        "status": consent_request.status,
        "purpose": consent_request.purpose,
        "hi_types": consent_request.hi_types,
        "date_from": iso(consent_request.date_from),
        "date_to": iso(consent_request.date_to),
        "erase_at": iso(consent_request.erase_at),
        "reason": consent_request.reason,
        "error": consent_request.error,
        "requested_by": consent_request.created_by.get_full_name()
        if consent_request.created_by
        else None,
        "created_date": iso(consent_request.created_date),
        "modified_date": iso(consent_request.modified_date),
        "artefacts": [
            {
                "id": str(artefact.external_id),
                "artefact_id": artefact.artefact_id,
                "status": artefact.status,
                "hip_id": artefact.hip_id,
                "hip_name": artefact.hip_name,
                "hi_types": artefact.detail.get("hiTypes") or [],
                "care_contexts": artefact.detail.get("careContexts") or [],
                "error": artefact.error,
                "fetches": [
                    {
                        "status": fetch.status,
                        "page_count": fetch.page_count,
                        "pages_received": len(fetch.pages_received),
                        "statuses": fetch.statuses,
                        "record_count": fetch.records.count(),
                        "error": fetch.error,
                        "created_date": iso(fetch.created_date),
                        "modified_date": iso(fetch.modified_date),
                    }
                    for fetch in artefact.fetches.order_by("-created_date")
                ],
            }
            for artefact in consent_request.artefacts.order_by("created_date")
        ],
    }


class ConsentRequestViewSet(AbdmViewSetMixin, ViewSet):
    """Requests, made from an encounter, for records held elsewhere (M3)."""

    lookup_field = "external_id"

    def get_encounter(self, external_id, permission):
        encounter = get_object_or_404(
            Encounter.objects.select_related("patient", "facility"),
            external_id=external_id,
        )
        if not AuthorizationController.call(permission, self.request.user, encounter):
            raise PermissionDenied("You do not have access to this encounter")
        return encounter

    def get_consent_request(self, external_id):
        consent_request = get_object_or_404(
            ConsentRequest.objects.select_related("encounter", "created_by"),
            external_id=external_id,
        )
        self.get_encounter(
            consent_request.encounter.external_id, "can_view_encounter_clinical_data"
        )
        return consent_request

    def list(self, request):
        encounter_id = request.query_params.get("encounter")
        if not encounter_id:
            raise ValidationError({"encounter": "This query parameter is required"})
        encounter = self.get_encounter(encounter_id, "can_view_encounter_clinical_data")
        consent_requests = (
            ConsentRequest.objects.filter(encounter=encounter)
            .select_related("created_by")
            .order_by("-created_date")
        )
        return Response(
            {"results": [serialize_consent_request(c) for c in consent_requests]}
        )

    def retrieve(self, request, external_id=None):
        return Response(
            serialize_consent_request(self.get_consent_request(external_id))
        )

    @extend_schema(request=ConsentRequestCreate)
    def create(self, request):
        data = ConsentRequestCreate.model_validate(request.data)
        encounter = self.get_encounter(
            data.encounter, "can_update_encounter_clinical_data"
        )
        abha = AbhaNumber.objects.filter(patient_id=encounter.patient_id).first()
        if abha is None or not abha.abha_address:
            raise ValidationError("The patient has no ABHA address")
        health_facility = HealthFacility.objects.filter(
            facility_id=encounter.facility_id, active=True
        ).first()
        if health_facility is None:
            raise ValidationError("This facility is not registered with ABDM")
        consent_request = ConsentRequest.objects.create(
            encounter=encounter,
            patient=encounter.patient,
            health_facility=health_facility,
            abha_address=abha.abha_address,
            purpose=data.purpose,
            hi_types=data.hi_types,
            date_from=data.date_from,
            date_to=data.date_to,
            erase_at=data.erase_at,
            created_by=request.user,
        )
        transaction.on_commit(
            lambda: request_consent.delay(consent_request.id, request.user.id)
        )
        return Response(serialize_consent_request(consent_request), status=201)

    @action(detail=True, methods=["GET"])
    def records(self, request, external_id=None):
        consent_request = self.get_consent_request(external_id)
        records = (
            FetchedRecord.objects.filter(
                fetch__artefact__consent_request=consent_request,
                erase_at__gt=timezone.now(),
            )
            .select_related("fetch__artefact")
            .order_by("created_date")
        )
        return Response(
            {
                "results": [
                    {
                        "id": str(record.external_id),
                        "hip_id": record.fetch.artefact.hip_id,
                        "hip_name": record.fetch.artefact.hip_name,
                        "care_context_reference": record.care_context_reference,
                        "erase_at": iso(record.erase_at),
                        "bundle": record.bundle,
                    }
                    for record in records
                ]
            }
        )
