{"content": "import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import dayjs from "dayjs";
import { useForm } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import * as z from "zod";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import { getAbhaError } from "@/components/Abdm/utils";
import {
  CONSENT_PURPOSES,
  REQUESTABLE_HI_TYPES,
} from "@/types/abdm/consentRequest";
import consentRequestApi from "@/types/abdm/consentRequestApi";
import mutate from "@/Utils/request/mutate";

const DATE_FORMAT = "YYYY-MM-DD";

interface Props {
  encounterId: string;
  abhaAddress: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function ConsentRequestDialog({
  encounterId,
  abhaAddress,
  open,
  onOpenChange,
}: Props) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();

  const schema = z
    .object({
      purpose: z.enum(CONSENT_PURPOSES),
      hi_types: z.array(z.string()).min(1, t("abdm__select_record_types")),
      date_from: z.string().min(1, t("field_required")),
      date_to: z.string().min(1, t("field_required")),
      erase_at: z.string().min(1, t("field_required")),
    })
    .refine((data) => data.date_from <= data.date_to, {
      message: t("abdm__date_range_invalid"),
      path: ["date_to"],
    })
    .refine((data) => dayjs(data.erase_at).isAfter(dayjs(), "day"), {
      message: t("abdm__erase_at_future"),
      path: ["erase_at"],
    });

  const form = useForm<z.infer<typeof schema>>({
    resolver: zodResolver(schema),
    defaultValues: {
      purpose: "CAREMGT",
      hi_types: [...REQUESTABLE_HI_TYPES],
      date_from: dayjs().subtract(1, "year").format(DATE_FORMAT),
      date_to: dayjs().format(DATE_FORMAT),
      erase_at: dayjs().add(7, "day").format(DATE_FORMAT),
    },
  });

  const { mutate: create, isPending } = useMutation({
    mutationFn: mutate(consentRequestApi.create, { silent: true }),
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: ["abdm_consent_requests", encounterId],
      });
      toast.success(t("abdm__consent_requested"));
      onOpenChange(false);
      form.reset();
    },
    onError: (error) =>
      toast.error(getAbhaError(error, t("abdm__consent_request_failed")).msg),
  });

  const onSubmit = (values: z.infer<typeof schema>) =>
    create({
      encounter: encounterId,
      purpose: values.purpose,
      hi_types: values.hi_types,
      date_from: dayjs(values.date_from).startOf("day").toISOString(),
      date_to: dayjs(values.date_to).endOf("day").toISOString(),
      erase_at: dayjs(values.erase_at).endOf("day").toISOString(),
    });

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-xl">
        <DialogHeader>
          <DialogTitle>{t("abdm__request_records")}</DialogTitle>
          <DialogDescription>
            {t("abdm__request_records_desc", { abha: abhaAddress })}
          </DialogDescription>
        </DialogHeader>
        <Form {...form}>
          <form
            onSubmit={form.handleSubmit(onSubmit)}
            className="flex flex-col gap-4"
          >
            <FormField
              control={form.control}
              name="purpose"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t("abdm__purpose")}</FormLabel>
                  <Select value={field.value} onValueChange={field.onChange}>
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      {CONSENT_PURPOSES.map((purpose) => (
                        <SelectItem key={purpose} value={purpose}>
                          {t(`abdm__purpose__${purpose}`)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="hi_types"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t("abdm__record_types")}</FormLabel>
                  <div className="grid grid-cols-2 gap-2">
                    {REQUESTABLE_HI_TYPES.map((type) => (
                      <label
                        key={type}
                        className="flex items-center gap-2 text-sm"
                      >
                        <Checkbox
                          checked={field.value.includes(type)}
                          onCheckedChange={(checked) =>
                            field.onChange(
                              checked
                                ? [...field.value, type]
                                : field.value.filter((v) => v !== type),
                            )
                          }
                        />
                        {t(`abdm__hi_type__${type}`)}
                      </label>
                    ))}
                  </div>
                  <FormMessage />
                </FormItem>
              )}
            />
            <div className="grid grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="date_from"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t("abdm__records_from_date")}</FormLabel>
                    <FormControl>
                      <Input type="date" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="date_to"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t("abdm__records_to_date")}</FormLabel>
                    <FormControl>
                      <Input type="date" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>
            <FormField
              control={form.control}
              name="erase_at"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t("abdm__erase_at")}</FormLabel>
                  <FormControl>
                    <Input type="date" {...field} />
                  </FormControl>
                  <FormDescription>{t("abdm__erase_at_desc")}</FormDescription>
                  <FormMessage />
                </FormItem>
              )}
            />
            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => onOpenChange(false)}
              >
                {t("cancel")}
              </Button>
              <Button type="submit" disabled={isPending}>
                {t("abdm__send_request")}
              </Button>
            </DialogFooter>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}
