{"content": "import { useQuery } from "@tanstack/react-query";
import { FileTextIcon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { EmptyState } from "@/components/ui/empty-state";
import { Label } from "@/components/ui/label";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Switch } from "@/components/ui/switch";

import { TableSkeleton } from "@/components/Common/SkeletonLoading";

import { FetchedRecord, FhirResource } from "@/types/abdm/consentRequest";
import consentRequestApi from "@/types/abdm/consentRequestApi";
import query from "@/Utils/request/query";
import { formatDateTime } from "@/Utils/utils";

interface Coding {
  display?: string;
  code?: string;
}
interface CodeableConcept {
  text?: string;
  coding?: Coding[];
}
interface Section {
  title?: string;
  entry?: { reference?: string }[];
}

function conceptText(value: unknown) {
  const concept = value as CodeableConcept | undefined;
  return (
    concept?.text ||
    concept?.coding?.find((c) => c.display)?.display ||
    concept?.coding?.[0]?.code
  );
}

function quantityText(value: unknown) {
  const quantity = value as { value?: number; unit?: string } | undefined;
  return quantity?.value !== undefined
    ? `${quantity.value} ${quantity.unit ?? ""}`.trim()
    : undefined;
}

// A one-line reading of any FHIR resource, from the fields most types share.
function describe(resource: FhirResource) {
  const name = (resource.name as { text?: string }[] | undefined)?.[0];
  return [
    conceptText(resource.code) ??
      conceptText(resource.medicationCodeableConcept) ??
      conceptText(resource.vaccineCode) ??
      (resource.title as string | undefined) ??
      (resource.description as string | undefined) ??
      name?.text,
    quantityText(resource.valueQuantity) ??
      (resource.valueString as string | undefined) ??
      conceptText(resource.valueCodeableConcept),
    (resource.dosageInstruction as { text?: string }[] | undefined)?.[0]?.text,
    resource.conclusion as string | undefined,
  ]
    .filter(Boolean)
    .join(" · ");
}

function referenceKeys(fullUrl: string | undefined, resource: FhirResource) {
  return [fullUrl, `${resource.resourceType}/${resource.id}`].filter(
    Boolean,
  ) as string[];
}

function RecordSummary({ record }: { record: FetchedRecord }) {
  const { t } = useTranslation();
  const entries = record.bundle.entry ?? [];
  const byReference = new Map<string, FhirResource>();
  for (const entry of entries) {
    if (!entry.resource) continue;
    for (const key of referenceKeys(entry.fullUrl, entry.resource)) {
      byReference.set(key, entry.resource);
    }
  }
  const composition = entries.find(
    (entry) => entry.resource?.resourceType === "Composition",
  )?.resource;
  const sections = (composition?.section as Section[] | undefined) ?? [];

  const groups = sections.length
    ? sections.map((section) => ({
        title: section.title ?? "",
        resources: (section.entry ?? [])
          .map((item) => byReference.get(item.reference ?? ""))
          .filter(Boolean) as FhirResource[],
      }))
    : [
        {
          title: "",
          resources: entries
            .map((entry) => entry.resource)
            .filter(Boolean) as FhirResource[],
        },
      ];

  return (
    <div className="flex flex-col gap-3">
      {composition && (
        <div className="flex flex-col">
          <span className="font-medium">
            {(composition.title as string) ?? conceptText(composition.type)}
          </span>
          {typeof composition.date === "string" && (
            <span className="text-xs text-gray-500">
              {formatDateTime(composition.date, "DD MMM YYYY, hh:mm A")}
            </span>
          )}
        </div>
      )}
      {groups.map((group, index) => (
        <div key={index} className="flex flex-col gap-1">
          {group.title && (
            <span className="text-xs font-medium uppercase text-gray-500">
              {group.title}
            </span>
          )}
          {group.resources.length ? (
            <ul className="flex flex-col gap-1">
              {group.resources.map((resource, i) => (
                <li key={i} className="flex items-start gap-2 text-sm">
                  <Badge variant="secondary" className="shrink-0">
                    {resource.resourceType}
                  </Badge>
                  <span className="break-words">
                    {describe(resource) || t("abdm__no_summary")}
                  </span>
                </li>
              ))}
            </ul>
          ) : (
            <span className="text-sm text-gray-500">-</span>
          )}
        </div>
      ))}
    </div>
  );
}

interface Props {
  consentRequestId: string | null;
  onClose: () => void;
}

export function FetchedRecordsDialog({ consentRequestId, onClose }: Props) {
  const { t } = useTranslation();
  const [raw, setRaw] = useState(false);
  const { data, isLoading } = useQuery({
    queryKey: ["abdm_fetched_records", consentRequestId],
    queryFn: query(consentRequestApi.records, {
      pathParams: { id: consentRequestId ?? "" },
    }),
    enabled: !!consentRequestId,
  });
  const records = data?.results ?? [];

  return (
    <Dialog open={!!consentRequestId} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-3xl">
        <DialogHeader>
          <DialogTitle>{t("abdm__received_records")}</DialogTitle>
          <DialogDescription>{t("abdm__received_records_desc")}</DialogDescription>
        </DialogHeader>
        <div className="flex items-center gap-2">
          <Switch id="abdm-raw-json" checked={raw} onCheckedChange={setRaw} />
          <Label htmlFor="abdm-raw-json">{t("abdm__show_raw_json")}</Label>
        </div>
        <ScrollArea className="max-h-[65vh] pr-3">
          {isLoading ? (
            <TableSkeleton count={3} />
          ) : records.length ? (
            <div className="flex flex-col gap-4">
              {records.map((record) => (
                <div
                  key={record.id}
                  className="flex flex-col gap-2 rounded-md border p-3"
                >
                  <div className="flex flex-wrap items-center justify-between gap-2 text-xs text-gray-500">
                    <span>
                      {record.hip_name || record.hip_id} ·{" "}
                      {record.care_context_reference}
                    </span>
                    <span>
                      {t("abdm__erased_on", {
                        date: formatDateTime(record.erase_at, "DD MMM YYYY"),
                      })}
                    </span>
                  </div>
                  {raw ? (
                    <pre className="overflow-x-auto rounded bg-gray-50 p-2 text-xs">
                      {JSON.stringify(record.bundle, null, 2)}
                    </pre>
                  ) : (
                    <RecordSummary record={record} />
                  )}
                </div>
              ))}
            </div>
          ) : (
            <EmptyState
              icon={<FileTextIcon />}
              title={t("abdm__no_received_records")}
            />
          )}
        </ScrollArea>
      </DialogContent>
    </Dialog>
