{"content": "import { useQuery } from "@tanstack/react-query";
import { AlertCircleIcon, DownloadIcon, EyeIcon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { EmptyState } from "@/components/ui/empty-state";

import { TableSkeleton } from "@/components/Common/SkeletonLoading";

import { ConsentRequestDialog } from "@/components/Abdm/ConsentRequestDialog";
import { FetchedRecordsDialog } from "@/components/Abdm/FetchedRecordsDialog";
import {
  ConsentRequest,
  ConsentRequestStatus,
  HealthInformationFetchStatus,
} from "@/types/abdm/consentRequest";
import consentRequestApi from "@/types/abdm/consentRequestApi";
import query from "@/Utils/request/query";
import { formatDateTime } from "@/Utils/utils";

type BadgeVariant = React.ComponentProps<typeof Badge>["variant"];

const POLL_INTERVAL_MS = 15000;

const REQUEST_STATUS_VARIANT: Record<ConsentRequestStatus, BadgeVariant> = {
  pending: "secondary",
  requested: "blue",
  granted: "green",
  denied: "destructive",
  expired: "secondary",
  revoked: "yellow",
  failed: "destructive",
};

const FETCH_STATUS_VARIANT: Record<HealthInformationFetchStatus, BadgeVariant> =
  {
    pending: "secondary",
    requested: "blue",
    receiving: "blue",
    received: "green",
    failed: "destructive",
  };

function isInFlight(request: ConsentRequest) {
  return (
    ["pending", "requested"].includes(request.status) ||
    request.artefacts.some(
      (artefact) =>
        artefact.status === "GRANTED" &&
        (!artefact.fetches.length ||
          ["requested", "receiving"].includes(artefact.fetches[0].status)),
    )
  );
}

function date(value: string) {
  return formatDateTime(value, "DD MMM YYYY");
}

function ConsentRequestItem({
  request,
  onView,
}: {
  request: ConsentRequest;
  onView: () => void;
}) {
  const { t } = useTranslation();
  const recordCount = request.artefacts.reduce(
    (total, artefact) => total + (artefact.fetches[0]?.record_count ?? 0),
    0,
  );
  const errors = [
    request.error,
    ...request.artefacts.flatMap((a) => [a.error, a.fetches[0]?.error]),
  ].filter((error) => error?.message);

  return (
    <div className="flex flex-col gap-3 rounded-md border p-3">
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div className="flex flex-col gap-1">
          <div className="flex items-center gap-2">
            <span className="font-medium">
              {t(`abdm__purpose__${request.purpose}`)}
            </span>
            <Badge variant={REQUEST_STATUS_VARIANT[request.status]}>
              {t(`abdm__consent_request_status__${request.status}`)}
            </Badge>
          </div>
          <span className="text-xs text-gray-500">
            {t("abdm__consent_request_meta", {
              from: date(request.date_from),
              to: date(request.date_to),
              erase: date(request.erase_at),
            })}
          </span>
          <span className="text-xs text-gray-500">
            {request.hi_types
              .map((type) => t(`abdm__hi_type__${type}`))
              .join(", ")}
          </span>
          {request.requested_by && (
            <span className="text-xs text-gray-500">
              {t("abdm__requested_by", {
                name: request.requested_by,
                date: formatDateTime(
                  request.created_date,
                  "DD MMM YYYY, hh:mm A",
                ),
              })}
            </span>
          )}
        </div>
        {recordCount > 0 && (
          <Button variant="outline" size="sm" onClick={onView}>
            <EyeIcon />
            {t("abdm__view_records", { count: recordCount })}
          </Button>
        )}
      </div>

      {request.reason && (
        <span className="text-sm text-gray-700">{request.reason}</span>
      )}

      {errors.map((error, index) => (
        <div
          key={index}
          className="flex gap-2 rounded-md border border-red-200 bg-red-50 p-2 text-sm text-red-900"
        >
          <AlertCircleIcon className="size-4 mt-0.5 shrink-0" />
          <span>
            {error?.code ? `${error.code}: ` : ""}
            {error?.message}
          </span>
        </div>
      ))}

      {request.artefacts.length > 0 && (
        <div className="flex flex-col gap-2">
          {request.artefacts.map((artefact) => {
            const fetch = artefact.fetches[0];
            return (
              <div
                key={artefact.id}
                className="flex flex-wrap items-center justify-between gap-2 rounded bg-gray-50 px-3 py-2 text-sm"
              >
                <div className="flex flex-col">
                  <span className="font-medium">
                    {artefact.hip_name ||
                      artefact.hip_id ||
                      t("abdm__awaiting_details")}
                  </span>
                  <span className="text-xs text-gray-500">
                    {artefact.hi_types
                      .map((type) => t(`abdm__hi_type__${type}`))
                      .join(", ")}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <Badge
                    variant={artefact.status === "GRANTED" ? "green" : "secondary"}
                  >
                    {artefact.status}
                  </Badge>
                  {fetch && (
                    <Badge variant={FETCH_STATUS_VARIANT[fetch.status]}>
                      <DownloadIcon className="size-3" />
                      {t(`abdm__fetch_status__${fetch.status}`, {
                        received: fetch.pages_received,
                        total: fetch.page_count ?? "?",
                      })}
                    </Badge>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

export function ExternalRecordsCard({
  encounterId,
  abhaAddress,
  canRequest,
}: {
  encounterId: string;
  abhaAddress: string | null;
  canRequest: boolean;
}) {
  const { t } = useTranslation();
  const [requesting, setRequesting] = useState(false);
  const [viewing, setViewing] = useState<string | null>(null);

  const { data, isLoading } = useQuery({
    queryKey: ["abdm_consent_requests", encounterId],
    queryFn: query(consentRequestApi.list, {
      queryParams: { encounter: encounterId },
    }),
    enabled: !!encounterId,
    // Consent and data arrive from ABDM asynchronously.
    refetchInterval: (state) =>
      state.state.data?.results.some(isInFlight) ? POLL_INTERVAL_MS : false,
  });
  const requests = data?.results ?? [];

  return (
    <Card>
      <CardHeader className="flex flex-row flex-wrap items-start justify-between gap-2 space-y-0">
        <div className="flex flex-col gap-1.5">
          <CardTitle className="text-lg">
            {t("abdm__external_records")}
          </CardTitle>
          <CardDescription>
            {abhaAddress
              ? t("abdm__external_records_desc")
              : t("abdm__external_records_no_abha")}
          </CardDescription>
        </div>
        {abhaAddress && canRequest && (
          <Button
            variant="outline_primary"
            size="sm"
            onClick={() => setRequesting(true)}
          >
            <DownloadIcon />
            {t("abdm__request_records")}
          </Button>
        )}
      </CardHeader>
      <CardContent>
        {isLoading ? (
          <TableSkeleton count={2} />
        ) : requests.length ? (
          <div className="flex flex-col gap-3">
            {requests.map((request) => (
              <ConsentRequestItem
                key={request.id}
                request={request}
                onView={() => setViewing(request.id)}
              />
            ))}
          </div>
        ) : (
          <EmptyState
            icon={<DownloadIcon />}
            title={t("abdm__no_consent_requests")}
            description={t("abdm__no_consent_requests_desc")}
          />
        )}
      </CardContent>
      {abhaAddress && (
        <ConsentRequestDialog
          encounterId={encounterId}
          abhaAddress={abhaAddress}
          open={requesting}
          onOpenChange={setRequesting}
        />
      )}
      <FetchedRecordsDialog
        consentRequestId={viewing}
        onClose={() => setViewing(null)}
      />
    </Card>
  );
}
