{"content": """"ABDM M4: the professional (HPR) and facility (HFR) registries.

Care links a facility to its HFR id and to this bridge, lets a user prove the
HPR id they hold, walks a professional through creating one, and registers a
facility in the HFR. Registry calls carry the gateway session token; calls made
for a professional also carry their HPR token, which lives in the cache only.
"""

import re
from base64 import b64encode

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import padding
from django.conf import settings
from django.core.cache import cache
from django.db import transaction
from django.utils import timezone

from care.abdm.models import (
    HealthFacility,
    HfrRegistration,
    HfrRegistrationStatus,
    HprProfile,
)
from care.abdm.service.client import AbdmError, request

TRANSACTION_TTL = 15 * 60
CERTIFICATE_TTL = 6 * 60 * 60
MASTER_TTL = 24 * 60 * 60
TOKEN_FALLBACK_TTL = 30 * 60
TOKEN_EXPIRY_MARGIN = 60
SEARCH_PAGE_SIZE = 20
HIP_NAME_LIMIT = 15
# Characters ABDM refuses in the name patients see for a facility.
HIP_NAME_FORBIDDEN = re.compile(r"[%$*#@(~&!)]")
# The registry answers a link that already exists with this, not with success.
ALREADY_LINKED = "already associated"
HPR_DOMAIN = "@hpr.abdm"
# Photos are large and only shown once, so they are never stored.
UNSTORED_PROFILE_FIELDS = {"kycPhoto", "profilePhoto", "photo"}
MASTER_PARAM = re.compile(r"^[\w\- ]{0,40}$")


class RegistryError(Exception):
    """A request Care refuses before anything is sent to the registry."""


class HprSessionExpiredError(RegistryError):
    pass


def url(path):
    return f"{settings.ABDM_HPR_URL}{path}"


def call(method, path, *, json=None, params=None, headers=None):
    return request(method, url(path), json=json, params=params, headers=headers)


def clean(value):
    return value.strip() if isinstance(value, str) else value


# --- Encryption ----------------------------------------------------------------


def hpr_certificate():
    certificate = cache.get("abdm:m4:certificate")
    if not certificate:
        certificate = call("GET", "/api/v1/auth/cert").text.strip()
        cache.set("abdm:m4:certificate", certificate, CERTIFICATE_TTL)
    return certificate


def hpr_encrypt(value):
    # The registry decrypts with RSA/ECB/PKCS1Padding, not the M1 padding.
    key = serialization.load_pem_public_key(hpr_certificate().encode())
    return b64encode(key.encrypt(str(value).encode(), padding.PKCS1v15())).decode()


# --- Master data ---------------------------------------------------------------

# Every master list Care may read, by the name the API exposes it under.
MASTERS = {
    "lgd_states": ("GET", "/v1.5/facility/lgd/states", (), ()),
    "lgd_sub_districts": (
        "GET",
        "/v1.5/facility/lgd/subdistricts",
        ("districtCode",),
        (),
    ),
    "master_types": ("GET", "/v1.5/facility/get-master-types", (), ()),
    "master_data": ("GET", "/v1.5/facility/get-master-data", ("type",), ()),
    "facility_types": (
        "POST",
        "/v1.5/facility/fetch-facility-type",
        ("ownershipCode", "systemOfMedicineCode"),
        (),
    ),
    "facility_sub_types": (
        "POST",
        "/v1.5/facility/fetch-facility-Sub-type",
        ("facilityTypeCode",),
        (),
    ),
    "owner_sub_types": (
        "POST",
        "/v1.5/facility/get-owner-subtype",
        ("ownershipCode", "ownerSubtypeCode"),
        (),
    ),
    "specialities": (
        "POST",
        "/v1.5/facility/get-specialities",
        ("systemOfMedicineCode",),
        (),
    ),
    "hpr_states": ("GET", "/apis/v1/masters/states", (), ()),
    "hpr_districts": ("GET", "/apis/v1/masters/district/{stateId}", (), ("stateId",)),
}


def normalize_options(body):
    """Reduce the registry's several list shapes to code and name pairs."""
    if isinstance(body, dict):
        body = body.get("data") or body.get("masterTypes") or []
    options = []
    for item in body if isinstance(body, list) else []:
        if not isinstance(item, dict):
            continue
        code = item.get("code") or item.get("type") or item.get("isoCode")
        if code is None and "id" in item:
            code = item["id"]
        name = (
            item.get("name")
            or item.get("value")
            or item.get("desc")
            or item.get("districtName")
        )
        option = {"code": str(clean(code)), "name": clean(name) or ""}
        if "id" in item and item.get("isoCode"):
            option["id"] = str(item["id"])
        if isinstance(item.get("districts"), list):
            option["districts"] = normalize_options(item["districts"])
        options.append(option)
    return options


def master(name, params):
    if name not in MASTERS:
        msg = "Unknown master list"
        raise RegistryError(msg)
    method, path, body_fields, path_fields = MASTERS[name]
    values = {}
    for field in (*body_fields, *path_fields):
        value = str(params.get(field) or "")
        if not MASTER_PARAM.match(value):
            msg = f"{field} is not valid"
            raise RegistryError(msg)
        values[field] = value
    for field in path_fields:
        if not values[field]:
            msg = f"{field} is required"
            raise RegistryError(msg)
    key = f"abdm:m4:master:{name}:" + ":".join(values.values())
    options = cache.get(key)
    if options is None:
        path = path.format(**{f: values[f] for f in path_fields})
        fields = {f: values[f] for f in body_fields}
        response = (
            call(method, path, params=fields)
            if method == "GET"
            else call(method, path, json=fields)
        )
        options = normalize_options(response.json())
        cache.set(key, options, MASTER_TTL)
    return options


# --- Facility: HFR search and bridge linkage ----------------------------------


def normalize_facility(record):
    return {
        "facility_id": record.get("facilityId") or "",
        "name": clean(record.get("facilityName")) or "",
        "status": record.get("facilityStatus") or "",
        "ownership": record.get("ownership") or "",
        "facility_type": record.get("facilityType") or "",
        "system_of_medicine": record.get("systemOfMedicine") or "",
        "address": record.get("address") or "",
        "state": record.get("stateName") or "",
        "district": record.get("districtName") or "",
        "sub_district": record.get("subDistrictName") or "",
        "pincode": record.get("pincode") or "",
        "latitude": record.get("latitude") or "",
        "longitude": record.get("longitude") or "",
    }


def search_facilities(*, name="", state_code="", district_code="", facility_id=""):
    body = call(
        "POST",
        "/FacilityManagement/v1.5/facility/search",
        json={
            "ownershipCode": "",
            "stateLGDCode": state_code,
            "districtLGDCode": district_code,
            "subDistrictLGDCode": "",
            "pincode": "",
            "facilityName": name,
            "facilityId": facility_id,
            "page": 1,
            "resultsPerPage": SEARCH_PAGE_SIZE,
        },
    ).json()
    return {
        "results": [normalize_facility(f) for f in body.get("facilities") or []],
        "total": body.get("totalFacilities") or 0,
    }


def find_facility(hfr_id):
    for record in search_facilities(facility_id=hfr_id)["results"]:
        if record["facility_id"] == hfr_id:
            return record
    return None


def bridge_service(hfr_id):
    """What the gateway holds for a facility's service id, whichever bridge."""
    try:
        return request(
            "GET",
            f"{settings.ABDM_GATEWAY_URL}/api/hiecm/gateway/v3/bridge-service/serviceId/{hfr_id}",
            headers={"X-CM-ID": settings.ABDM_CM_ID},
        ).json()
    except AbdmError as e:
        if e.status == 404:  # noqa: PLR2004
            return None
        raise


def validate_hip_name(hip_name):
    if not hip_name or len(hip_name) > HIP_NAME_LIMIT:
        msg = f"The name patients see must be 1 to {HIP_NAME_LIMIT} characters"
        raise RegistryError(msg)
    if HIP_NAME_FORBIDDEN.search(hip_name):
        msg = "The name patients see cannot contain %$*#@(~&!)"
        raise RegistryError(msg)


def link_facility(facility, hfr_id, hip_name, *, hip=True, hiu=True):
    """Link a Care facility to its HFR id and this bridge, as HIP and/or HIU."""
    hfr_id = hfr_id.strip().upper()
    hip_name = hip_name.strip()
    validate_hip_name(hip_name)
    if (
        HealthFacility.objects.filter(hip_id=hfr_id)
        .exclude(facility=facility)
        .exists()
    ):
        msg = "Another Care facility is already linked to this HFR id"
        raise RegistryError(msg)
    record = find_facility(hfr_id)
    if record is None:
        msg = "No facility with this id exists in the HFR"
        raise RegistryError(msg)

    results = call(
        "POST",
        "/v1/bridges/MutipleHRPAddUpdateServices",
        json={
            "facilityId": hfr_id,
            "facilityName": record["name"],
            "HRP": [
                {
                    "bridgeId": settings.ABDM_BRIDGE_ID,
                    "hipName": hip_name,
                    "type": role,
                    "active": wanted,
                }
                for role, wanted in (("HIP", hip), ("HIU", hiu))
            ],
        },
    ).json()
    # The call answers 200 with a refusal per entry, so each one is read.
    refusals = [
        item["error"]
        for item in results if isinstance(results, list) else []
        if isinstance(item, dict)
        and isinstance(item.get("error"), dict)
        and ALREADY_LINKED not in str(item["error"].get("message") or "")
    ]
    service = bridge_service(hfr_id)
    ours = bool(service) and service.get("bridgeId") == settings.ABDM_BRIDGE_ID
    if refusals and not ours:
        raise AbdmError(
            str(refusals[0].get("message") or "The registry refused the link"),
            status=400,
            code=str(refusals[0].get("code") or "") or None,
        )
    if not ours:
        msg = "The facility is linked to another bridge"
        raise RegistryError(msg)

    is_hip = bool(service.get("isHip"))
    is_hiu = bool(service.get("isHiu"))
    health_facility, _ = HealthFacility.objects.update_or_create(
        facility=facility,
        defaults={
            "hip_id": hfr_id,
            "hip_name": service.get("name") or hip_name,
            "is_hip": is_hip,
            "is_hiu": is_hiu,
            "active": bool(service.get("active")) and (is_hip or is_hiu),
            "hfr_detail": record,
            "bridge_detail": {"service": service, "results": results},
            "linked_at": timezone.now(),
        },
    )
    return health_facility


# --- Professionals: HPR tokens and profiles ------------------------------------


def token_key(user):
    return f"abdm:m4:hpr-token:{user.id}"


def hpr_token(user):
    token = cache.get(token_key(user))
    if not token:
        msg = "Sign in to the HPR again"
        raise HprSessionExpiredError(msg)
    return token


def professional_headers(token):
    return {"X-Token": f"Bearer {token}"}


def account_information(token):
    return call(
        "GET",
        "/v1/account/information",
        headers=professional_headers(token),
    ).json()


def sign_in(user, body):
    """Keep the HPR token a sign in returned and record who it belongs to."""
    token = body.get("token")
    if not token:
        msg = "The registry did not return a session"
        raise RegistryError(msg)
    try:
        ttl = int(body.get("expiresIn") or TOKEN_FALLBACK_TTL)
    except (TypeError, ValueError):
        ttl = TOKEN_FALLBACK_TTL
    cache.set(token_key(user), token, max(ttl - TOKEN_EXPIRY_MARGIN, 60))
    info = account_information(token)
    hpr_id_number = info.get("hprIdNumber") or body.get("hprIdNumber")
    hpr_id = info.get("hprId") or body.get("hprId")
    if not hpr_id_number or not hpr_id:
        msg = "The registry did not say which professional signed in"
        raise RegistryError(msg)
    with transaction.atomic():
        if (
            HprProfile.objects.filter(hpr_id_number=hpr_id_number)
            .exclude(user=user)
            .exists()
        ):
            cache.delete(token_key(user))
            msg = "This HPR id is linked to another Care user"
            raise RegistryError(msg)
        profile, _ = HprProfile.objects.update_or_create(
            user=user,
            defaults={
                "hpr_id": hpr_id,
                "hpr_id_number": hpr_id_number,
                "name": info.get("name") or body.get("name") or "",
                "category": info.get("categoryName") or "",
                "sub_category": info.get("categorySubName") or "",
                "detail": {
                    k: v for k, v in info.items() if k not in UNSTORED_PROFILE_FIELDS
                },
                "verified_at": timezone.now(),
            },
        )
    return profile


def sign_out(user):
    cache.delete(token_key(user))


def login_with_password(user, hpr_id, password):
    body = call(
        "POST",
        "/api/v1/auth/authPassword",
        json={
            "idType": "",
            "domainName": "",
            "hprId": hpr_id,
            "password": hpr_encrypt(password),
        },
    ).json()
    return sign_in(user, body)


# Transactions: registry txnIds bound to the Care user that started them.


def transaction_key(txn_id):
    return f"abdm:m4:transaction:{txn_id}"


def save_transaction(user, txn_id, flow, **state):
    cache.set(
        transaction_key(txn_id),
        {"user": user.id, "flow": flow, **state},
        TRANSACTION_TTL,
    )


def load_transaction(user, txn_id, *flows):
    state = cache.get(transaction_key(txn_id)) if txn_id else None
    if not state or state["user"] != user.id or state["flow"] not in flows:
        msg = "The HPR transaction is invalid or has expired"
        raise RegistryError(msg)
    return state


def login_send_aadhaar_otp(user, hpr_id):
    body = call(
        "POST",
        "/api/v1/auth/init",
        json={
            "idType": "",
            "domainName": "",
            "authMethod": "AADHAAR_OTP",
            "hprId": hpr_id,
        },
    ).json()
    txn_id = body.get("transactionId") or body.get("txnId")
    save_transaction(user, txn_id, "login")
    return {"txn_id": txn_id, "mobile": body.get("mobileNumber") or ""}


def login_verify_aadhaar_otp(user, txn_id, otp):
    load_transaction(user, txn_id, "login")
    body = call(
        "POST",
        "/api/v1/auth/confirmWithAadhaarOtp",
        json={"otp": otp, "txnId": txn_id},
    ).json()
    cache.delete(transaction_key(txn_id))
    return sign_in(user, body)


# --- Professionals: creating an HPR id -----------------------------------------


def creation_start(user):
    body = call(
        "POST",
        "/aadhaar/generateLink",
        json={"scopes": ["nhpr-register"], "source": "NHPR"},
    ).json()
    save_transaction(user, body["txnId"], "create")
    return {"txn_id": body["txnId"], "url": body.get("url") or ""}


def creation_status(user, txn_id):
    load_transaction(user, txn_id, "create")
    response = call("POST", "/aadhaar/isAuthenticated", json={"txnId": txn_id})
    # The registry answers with a bare boolean, not an object.
    return response.text.strip().lower() == "true"


def creation_verify(user, txn_id):
    """Read who Aadhaar authenticated; sign in if they already hold an HPR id."""
    load_transaction(user, txn_id, "create")
    person = call(
        "POST", "/v2/registration/aadhaar/verifyOTP", json={"txnId": txn_id}
    ).json()
    existing = call(
        "POST",
        "/v1/registration/aadhaar/checkHpIdAccountExist",
        json={"txnId": txn_id},
    ).json()
    if existing.get("token") and existing.get("hprIdNumber"):
        cache.delete(transaction_key(txn_id))
        return {"status": "existing", "profile": sign_in(user, existing)}
    save_transaction(user, txn_id, "create", verified=True, person=person)
    return {
        "status": "new",
        "name": person.get("name") or "",
        "gender": person.get("gender") or "",
        "birthdate": person.get("birthdate") or "",
        "mobile": person.get("mobileNumber") or "",
        "photo": person.get("photo") or "",
        "email": person.get("email") or "",
    }


def creation_check_mobile(user, txn_id, mobile):
    state = load_transaction(user, txn_id, "create")
    if not state.get("verified"):
        msg = "Authenticate with Aadhaar first"
        raise RegistryError(msg)
    body = call(
        "POST",
        "/v2/registration/aadhaar/demographicAuthViaMobile",
        json={"txnId": txn_id, "mobileNumber": hpr_encrypt(mobile)},
    ).json()
    verified = bool(body.get("verified"))
    if not verified:
        call(
            "POST",
            "/v1/registration/aadhaar/generateMobileOTP",
            json={"mobile": hpr_encrypt(mobile), "txnId": txn_id},
        )
    save_transaction(user, txn_id, "create", **{**state, "mobile_verified": verified})
    return {"verified": verified}


def creation_verify_mobile_otp(user, txn_id, otp):
    state = load_transaction(user, txn_id, "create")
    call(
        "POST",
        "/v1/registration/aadhaar/verifyMobileOTP",
        json={"otp": hpr_encrypt(otp), "txnId": txn_id},
    )
    save_transaction(user, txn_id, "create", **{**state, "mobile_verified": True})
    return {"verified": True}


def creation_suggestions(user, txn_id):
    load_transaction(user, txn_id, "create")
    body = call(
        "POST", "/v1/registration/aadhaar/hpid/suggestion", json={"txnId": txn_id}
    ).json()
    return body if isinstance(body, list) else []


def split_name(name):
    parts = (name or "").split()
    if len(parts) <= 1:
        return (parts[0] if parts else ""), "", ""
    return parts[0], " ".join(parts[1:-1]), parts[-1]


def creation_finish(user, txn_id, data):  # noqa: PLR0913
    state = load_transaction(user, txn_id, "create")
    if not state.get("mobile_verified"):
        msg = "Verify the mobile number first"
        raise RegistryError(msg)
    person = state.get("person") or {}
    first, middle, last = split_name(person.get("name"))
    hpr_id = data["hpr_id"].strip().lower().removesuffix(HPR_DOMAIN)
    body = call(
        "POST",
        "/v2/registration/aadhaar/createHprIdWithPreVerified",
        json={
            "idType": "hpr_id",
            "domainName": HPR_DOMAIN,
            "hprId": hpr_id,
            "email": data["email"],
            "password": hpr_encrypt(data["password"]),
            "firstName": first,
            "middleName": middle,
            "lastName": last,
            "profilePhoto": person.get("photo") or "",
            "txnId": txn_id,
            "sourceType": "AADHAAR",
            "hpCategoryCode": int(data["category"]),
            "hpSubCategoryCode": int(data["sub_category"]),
            "stateCode": data["state_code"],
            "districtCode": data["district_code"],
            "clientId": "V4",
            "council": False,
            "role": 0,
        },
    ).json()
    cache.delete(transaction_key(txn_id))
    return sign_in(user, body)


# --- Facility: HFR registration ------------------------------------------------


def registration_headers(user, *, verifier=False):
    token = hpr_token(user)
    headers = {"x-hprid-auth": token}
    if verifier:
        headers["x-hprid-auth-verifier"] = token
    return headers


def find_duplicates(name, address, district_code, sub_district_code):
    body = call(
        "POST",
        "/search/address/filter/deduplicate",
        json={
            "name": name,
            "address": address,
            "district": district_code,
            "subDistrict": sub_district_code,
            "village": "",
            "geolocation": "",
            "facilityId": "",
        },
    ).json()
    return [normalize_facility(f) for f in body] if isinstance(body, list) else []


def record_step(registration, step, sent, answer, status):
    registration.data = {**registration.data, step: sent}
    registration.responses = {**registration.responses, step: answer}
    registration.status = status
    registration.error = None
    registration.save()


def record_failure(registration, step, error):
    registration.error = {
        "step": step,
        "code": error.code,
        "message": error.message,
        "request_id": error.request_id,
        "at": timezone.now().isoformat(),
    }
    registration.save(update_fields=["error", "modified_date"])


def run_step(registration, step, path, body, status, headers=None):
    try:
        answer = call("POST", path, json=body, headers=headers).json()
    except AbdmError as e:
        record_failure(registration, step, e)
        raise
    record_step(registration, step, body, answer, status)
    return answer


def submit_basic_information(user, registration, information):
    headers = registration_headers(user)
    answer = run_step(
        registration,
        "basic",
        "/v1.5/facility/basic-information",
        {"trackingId": registration.tracking_id, "facilityInformation": information},
        HfrRegistrationStatus.basic,
        headers,
    )
    tracking_id = str(answer.get("trackingId") or registration.tracking_id or "")
    if not tracking_id:
        msg = "The registry did not return a tracking id"
        raise RegistryError(msg)
    registration.tracking_id = tracking_id
    registration.save(update_fields=["tracking_id", "modified_date"])
    return registration


def require_tracking_id(registration):
    if not registration.tracking_id:
        msg = "Submit the basic information first"
        raise RegistryError(msg)


def submit_additional_information(user, registration, information):
    require_tracking_id(registration)
    run_step(
        registration,
        "additional",
        "/v1.5/facility/additional-information",
        {"trackingId": registration.tracking_id, **information},
        HfrRegistrationStatus.additional,
        registration_headers(user),
    )
    return registration


def submit_detailed_information(user, registration, information):
    require_tracking_id(registration)
    run_step(
        registration,
        "detailed",
        "/v1.5/facility/detailed-information",
        {"trackingId": registration.tracking_id, **information},
        HfrRegistrationStatus.detailed,
        registration_headers(user),
    )
    return registration


def submit_registration(user, registration):
    require_tracking_id(registration)
    answer = run_step(
        registration,
        "submit",
        "/v1.5/facility/submit-facility",
        {
            "trackingId": registration.tracking_id,
            "sourceOfInformation": "",
            "sourceUniqueID": str(registration.facility.external_id),
        },
        HfrRegistrationStatus.submitted,
        registration_headers(user, verifier=True),
    )
    registration.hfr_id = answer.get("facilityId") or ""
    registration.save(update_fields=["hfr_id", "modified_date"])
    return registration


