{"content": "from django.core.cache import cache
from drf_spectacular.utils import extend_schema
from pydantic import BaseModel, Field
from rest_framework.decorators import action
from rest_framework.exceptions import PermissionDenied, ValidationError
from rest_framework.response import Response
from rest_framework.viewsets import ViewSet

from care.abdm.api.viewsets import AbdmViewSetMixin
from care.abdm.models import HealthFacility, HfrRegistration, HprProfile
from care.abdm.service import m4
from care.facility.models import Facility
from care.security.authorization import AuthorizationController
from care.utils.shortcuts import get_object_or_404


def iso(value):
    return value.isoformat() if value else None


class FacilitySearchRequest(BaseModel):
    name: str = Field(default="", max_length=100)
    state_code: str = Field(default="", max_length=10)
    district_code: str = Field(default="", max_length=10)
    facility_id: str = Field(default="", max_length=20)


class LinkFacilityRequest(BaseModel):
    facility: str
    hfr_id: str = Field(pattern=r"^\s*[Ii][Nn]\d+\s*$")
    hip_name: str
    hip: bool = True
    hiu: bool = True


class FacilityRequest(BaseModel):
    facility: str


class DuplicateSearchRequest(BaseModel):
    name: str = Field(max_length=200)
    address: str = Field(default="", max_length=500)
    district_code: str = Field(max_length=10)
    sub_district_code: str = Field(default="", max_length=10)


class RegistrationStepRequest(BaseModel):
    registration: str
    step: str = Field(pattern=r"^(basic|additional|detailed|submit)$")
    information: dict = Field(default_factory=dict)


class PasswordLoginRequest(BaseModel):
    hpr_id: str = Field(max_length=255)
    password: str = Field(max_length=200)


class HprIdRequest(BaseModel):
    hpr_id: str = Field(max_length=255)


class TxnRequest(BaseModel):
    txn_id: str = Field(max_length=100)


class TxnOtpRequest(TxnRequest):
    otp: str = Field(pattern=r"^\d{4,8}$")


class TxnMobileRequest(TxnRequest):
    mobile: str = Field(pattern=r"^\d{10}$")


class CreateHprIdRequest(TxnRequest):
    hpr_id: str = Field(max_length=100)
    email: str = Field(max_length=255)
    password: str = Field(max_length=200)
    category: int
    sub_category: int
    state_code: str = Field(max_length=10)
    district_code: str = Field(max_length=10)


def serialize_health_facility(health_facility):
    if health_facility is None:
        return None
    return {
        "hfr_id": health_facility.hip_id,
        "hip_name": health_facility.hip_name,
        "is_hip": health_facility.is_hip,
        "is_hiu": health_facility.is_hiu,
        "active": health_facility.active,
        "hfr": health_facility.hfr_detail,
        "linked_at": iso(health_facility.linked_at),
    }


def serialize_registration(registration):
    return {
        "id": str(registration.external_id),
        "status": registration.status,
        "tracking_id": registration.tracking_id,
        "hfr_id": registration.hfr_id,
        "data": registration.data,
        "responses": registration.responses,
        "error": registration.error,
        "created_date": iso(registration.created_date),
        "modified_date": iso(registration.modified_date),
    }


def serialize_profile(profile, user):
    return {
        "profile": None
        if profile is None
        else {
            "hpr_id": profile.hpr_id,
            "hpr_id_number": profile.hpr_id_number,
            "name": profile.name,
            "category": profile.category,
            "sub_category": profile.sub_category,
            "verified_at": iso(profile.verified_at),
        },
        "session_active": bool(cache.get(m4.token_key(user))),
    }


class RegistryMasterViewSet(AbdmViewSetMixin, ViewSet):
    """The registries' published code lists, which their forms take as codes."""

    def list(self, request):
        name = request.query_params.get("name", "")
        try:
            return Response({"results": m4.master(name, request.query_params)})
        except m4.RegistryError as e:
            raise ValidationError(str(e)) from e


class HealthFacilityViewSet(AbdmViewSetMixin, ViewSet):
    """A facility's HFR id, its bridge linkage and its HFR registration (M4)."""

    def get_facility(self, external_id):
        facility = get_object_or_404(Facility, external_id=external_id)
        if not AuthorizationController.call(
            "can_update_facility_obj", self.request.user, facility
        ):
            raise PermissionDenied("You cannot manage this facility")
        return facility

    def list(self, request):
        facility_id = request.query_params.get("facility")
        if not facility_id:
            raise ValidationError({"facility": "This query parameter is required"})
        facility = self.get_facility(facility_id)
        return Response(
            {
                "health_facility": serialize_health_facility(
                    HealthFacility.objects.filter(facility=facility).first()
                ),
                "bridge_id": m4.settings.ABDM_BRIDGE_ID,
                "registrations": [
                    serialize_registration(r)
                    for r in facility.hfr_registrations.order_by("-created_date")
                ],
            }
        )

    @extend_schema(request=FacilitySearchRequest)
    @action(detail=False, methods=["POST"])
    def search(self, request):
        data = FacilitySearchRequest.model_validate(request.data)
        if not any([data.name, data.facility_id, data.state_code]):
            raise ValidationError("Enter a name, an HFR id or a state")
        return Response(
            m4.search_facilities(
                name=data.name.strip(),
                state_code=data.state_code,
                district_code=data.district_code,
                facility_id=data.facility_id.strip().upper(),
            )
        )

    @extend_schema(request=LinkFacilityRequest)
    @action(detail=False, methods=["POST"])
    def link(self, request):
        data = LinkFacilityRequest.model_validate(request.data)
        facility = self.get_facility(data.facility)
        try:
            health_facility = m4.link_facility(
                facility, data.hfr_id, data.hip_name, hip=data.hip, hiu=data.hiu
            )
        except m4.RegistryError as e:
            raise ValidationError(str(e)) from e
        return Response(serialize_health_facility(health_facility))

    @extend_schema(request=DuplicateSearchRequest)
    @action(detail=False, methods=["POST"])
    def duplicates(self, request):
        data = DuplicateSearchRequest.model_validate(request.data)
        return Response(
            {
                "results": m4.find_duplicates(
                    data.name, data.address, data.district_code, data.sub_district_code
                )
            }
        )

    @extend_schema(request=FacilityRequest)
    @action(detail=False, methods=["POST"])
    def register(self, request):
        """Start an HFR registration for a facility not yet in the registry."""
        data = FacilityRequest.model_validate(request.data)
        facility = self.get_facility(data.facility)
        registration = (
            facility.hfr_registrations.exclude(status="submitted")
            .order_by("-created_date")
            .first()
        ) or HfrRegistration.objects.create(
            facility=facility, created_by=request.user
        )
        return Response(serialize_registration(registration))

    @extend_schema(request=RegistrationStepRequest)
    @action(detail=False, methods=["POST"], url_path="registration_step")
    def registration_step(self, request):
        data = RegistrationStepRequest.model_validate(request.data)
        registration = get_object_or_404(
            HfrRegistration.objects.select_related("facility"),
            external_id=data.registration,
        )
        self.get_facility(registration.facility.external_id)
        if registration.status == "submitted":
            raise ValidationError("This registration has already been submitted")
        steps = {
            "basic": m4.submit_basic_information,
            "additional": m4.submit_additional_information,
            "detailed": m4.submit_detailed_information,
        }
        try:
            if data.step == "submit":
                m4.submit_registration(request.user, registration)
            else:
                steps[data.step](request.user, registration, data.information)
        except m4.RegistryError as e:
            raise ValidationError(str(e)) from e
        return Response(serialize_registration(registration))


class HprViewSet(AbdmViewSetMixin, ViewSet):
    """The signed-in user's own HPR id: sign in, link, or create one (M4)."""

    def respond(self, call, *args):
        try:
            call(self.request.user, *args)
        except m4.RegistryError as e:
            raise ValidationError(str(e)) from e
        return self.me(self.request)

    @action(detail=False, methods=["GET"])
    def me(self, request):
        profile = HprProfile.objects.filter(user=request.user).first()
        return Response(serialize_profile(profile, request.user))

    @extend_schema(request=PasswordLoginRequest)
    @action(detail=False, methods=["POST"], url_path="login/password")
    def login_password(self, request):
        data = PasswordLoginRequest.model_validate(request.data)
        return self.respond(m4.login_with_password, data.hpr_id, data.password)

    @extend_schema(request=HprIdRequest)
    @action(detail=False, methods=["POST"], url_path="login/send_otp")
    def login_send_otp(self, request):
        data = HprIdRequest.model_validate(request.data)
        return Response(m4.login_send_aadhaar_otp(request.user, data.hpr_id))

    @extend_schema(request=TxnOtpRequest)
    @action(detail=False, methods=["POST"], url_path="login/verify_otp")
    def login_verify_otp(self, request):
        data = TxnOtpRequest.model_validate(request.data)
        return self.respond(m4.login_verify_aadhaar_otp, data.txn_id, data.otp)

    @action(detail=False, methods=["POST"])
    def logout(self, request):
        m4.sign_out(request.user)
        return self.me(request)

    @action(detail=False, methods=["POST"])
    def unlink(self, request):
        m4.sign_out(request.user)
        HprProfile.objects.filter(user=request.user).delete()
        return self.me(request)

    @action(detail=False, methods=["POST"], url_path="create/start")
    def create_start(self, request):
        return Response(m4.creation_start(request.user))

    @extend_schema(request=TxnRequest)
    @action(detail=False, methods=["POST"], url_path="create/status")
    def create_status(self, request):
        data = TxnRequest.model_validate(request.data)
        try:
            return Response(
                {"authenticated": m4.creation_status(request.user, data.txn_id)}
            )
        except m4.RegistryError as e:
            raise ValidationError(str(e)) from e

    @extend_schema(request=TxnRequest)
    @action(detail=False, methods=["POST"], url_path="create/verify")
    def create_verify(self, request):
        data = TxnRequest.model_validate(request.data)
        try:
            result = m4.creation_verify(request.user, data.txn_id)
        except m4.RegistryError as e:
            raise ValidationError(str(e)) from e
        if result["status"] == "existing":
            return Response(
                {"status": "existing", **serialize_profile(result["profile"], request.user)}
            )
        return Response(result)

    @extend_schema(request=TxnMobileRequest)
    @action(detail=False, methods=["POST"], url_path="create/mobile")
    def create_mobile(self, request):
        data = TxnMobileRequest.model_validate(request.data)
        try:
            return Response(
                m4.creation_check_mobile(request.user, data.txn_id, data.mobile)
            )
        except m4.RegistryError as e:
            raise ValidationError(str(e)) from e

    @extend_schema(request=TxnOtpRequest)
    @action(detail=False, methods=["POST"], url_path="create/mobile_otp")
    def create_mobile_otp(self, request):
        data = TxnOtpRequest.model_validate(request.data)
        try:
            return Response(
                m4.creation_verify_mobile_otp(request.user, data.txn_id, data.otp)
            )
        except m4.RegistryError as e:
            raise ValidationError(str(e)) from e

    @extend_schema(request=TxnRequest)
    @action(detail=False, methods=["POST"], url_path="create/suggestions")
    def create_suggestions(self, request):
        data = TxnRequest.model_validate(request.data)
        try:
            return Response(
                {"results": m4.creation_suggestions(request.user, data.txn_id)}
            )
        except m4.RegistryError as e:
            raise ValidationError(str(e)) from e

    @extend_schema(request=CreateHprIdRequest)
    @action(detail=False, methods=["POST"], url_path="create/finish")
    def create_finish(self, request):
        data = CreateHprIdRequest.model_validate(request.data)
        return self.respond(m4.creation_finish, data.txn_id, data.model_dump())
