{"content": "import { useQuery } from "@tanstack/react-query";
import { useTranslation } from "react-i18next";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import { RegistryOption } from "@/types/abdm/registry";
import registryApi from "@/types/abdm/registryApi";
import query from "@/Utils/request/query";

type Params = Record<string, string | number | undefined>;

// A code list the registries publish; read live so it never goes stale here.
export function useRegistryOptions(name: string, params: Params = {}) {
  const missing = Object.values(params).some((v) => v === undefined || v === "");
  const { data, isLoading } = useQuery({
    queryKey: ["abdm_registry_master", name, params],
    queryFn: query(registryApi.masters, {
      queryParams: { name, ...params },
    }),
    enabled: !missing,
    staleTime: Infinity,
  });
  return { options: (data?.results ?? []) as RegistryOption[], isLoading };
}

interface Props {
  name: string;
  params?: Params;
  value?: string;
  onChange: (value: string) => void;
  placeholder?: string;
  options?: RegistryOption[];
  disabled?: boolean;
}

export function RegistrySelect({
  name,
  params,
  value,
  onChange,
  placeholder,
  options: given,
  disabled,
}: Props) {
  const { t } = useTranslation();
  const { options: fetched, isLoading } = useRegistryOptions(
    given ? "" : name,
    given ? { skip: undefined } : params,
  );
  const options = given ?? fetched;
  return (
    <Select
      value={value || undefined}
      onValueChange={onChange}
      disabled={disabled || isLoading || !options.length}
    >
      <SelectTrigger>
        <SelectValue placeholder={placeholder ?? t("select")} />
      </SelectTrigger>
      <SelectContent>
        {options.map((option) => (
          <SelectItem key={option.code} value={option.code}>
            {option.name}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}
