{"content": "import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

import { getAbhaError } from "@/components/Abdm/utils";
import { HprStatus } from "@/types/abdm/registry";
import registryApi from "@/types/abdm/registryApi";
import mutate from "@/Utils/request/mutate";

export const HPR_ME_QUERY_KEY = ["abdm_hpr_me"];

export function HprSignInForm({ defaultHprId = "" }: { defaultHprId?: string }) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [hprId, setHprId] = useState(defaultHprId);
  const [password, setPassword] = useState("");
  const [otp, setOtp] = useState("");
  const [txn, setTxn] = useState<{ txn_id: string; mobile: string } | null>(
    null,
  );

  const onSignedIn = (status: HprStatus) => {
    queryClient.setQueryData(HPR_ME_QUERY_KEY, status);
    setPassword("");
    setOtp("");
    setTxn(null);
    toast.success(t("abdm__hpr_signed_in"));
  };
  const onError = (error: Error) =>
    toast.error(getAbhaError(error, t("abdm__hpr_sign_in_failed")).msg);

  const passwordLogin = useMutation({
    mutationFn: mutate(registryApi.hprLoginPassword, { silent: true }),
    onSuccess: onSignedIn,
    onError,
  });
  const sendOtp = useMutation({
    mutationFn: mutate(registryApi.hprLoginSendOtp, { silent: true }),
    onSuccess: (result) => {
      setTxn(result);
      toast.success(t("abdm__otp_sent"));
    },
    onError,
  });
  const verifyOtp = useMutation({
    mutationFn: mutate(registryApi.hprLoginVerifyOtp, { silent: true }),
    onSuccess: onSignedIn,
    onError,
  });

  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-col gap-1.5">
        <Label htmlFor="hpr-id">{t("abdm__hpr_id")}</Label>
        <Input
          id="hpr-id"
          value={hprId}
          placeholder="[REDACTED_EMAIL]"
          autoComplete="username"
          onChange={(e) => setHprId(e.target.value)}
        />
      </div>
      <Tabs defaultValue="password">
        <TabsList>
          <TabsTrigger value="password">{t("password")}</TabsTrigger>
          <TabsTrigger value="otp">{t("abdm__aadhaar_otp")}</TabsTrigger>
        </TabsList>
        <TabsContent value="password" className="flex flex-col gap-3 pt-2">
          <Input
            type="password"
            value={password}
            autoComplete="current-password"
            placeholder={t("password")}
            onChange={(e) => setPassword(e.target.value)}
          />
          <Button
            className="w-fit"
            disabled={!hprId || !password || passwordLogin.isPending}
            onClick={() =>
              passwordLogin.mutate({ hpr_id: hprId.trim(), password })
            }
          >
            {t("abdm__hpr_sign_in")}
          </Button>
        </TabsContent>
        <TabsContent value="otp" className="flex flex-col gap-3 pt-2">
          {txn ? (
            <>
              <span className="text-sm text-gray-600">
                {t("abdm__otp_sent_to", { mobile: txn.mobile })}
              </span>
              <Input
                inputMode="numeric"
                autoComplete="one-time-code"
                maxLength={8}
                value={otp}
                placeholder={t("otp")}
                onChange={(e) => setOtp(e.target.value.replace(/\D/g, ""))}
              />
              <div className="flex gap-2">
                <Button
                  disabled={otp.length < 4 || verifyOtp.isPending}
                  onClick={() => verifyOtp.mutate({ txn_id: txn.txn_id, otp })}
                >
                  {t("abdm__hpr_sign_in")}
                </Button>
                <Button variant="outline" onClick={() => setTxn(null)}>
                  {t("cancel")}
                </Button>
              </div>
            </>
          ) : (
            <Button
              className="w-fit"
              variant="outline"
              disabled={!hprId || sendOtp.isPending}
              onClick={() => sendOtp.mutate({ hpr_id: hprId.trim() })}
            >
              {t("abdm__send_aadhaar_otp")}
            </Button>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}
