{"content": "import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { ExternalLinkIcon, Loader2Icon } from "lucide-react";
import { useEffect, useState } from "react";
import { useForm } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import * as z from "zod";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";

import { HPR_ME_QUERY_KEY } from "@/components/Abdm/registry/HprSignInForm";
import {
  RegistrySelect,
  useRegistryOptions,
} from "@/components/Abdm/registry/RegistrySelect";
import { getAbhaError, getAbhaPhotoSrc } from "@/components/Abdm/utils";
import { HprAadhaarPerson, HprStatus } from "@/types/abdm/registry";
import registryApi from "@/types/abdm/registryApi";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";

const POLL_INTERVAL_MS = 3000;
// The registry's roles: 0 registers a professional, 2 a facility manager.
const ROLES = ["0", "2"] as const;

type Step = "start" | "waiting" | "mobile" | "mobile_otp" | "details";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

function DetailsForm({
  txnId,
  person,
  onDone,
}: {
  txnId: string;
  person: HprAadhaarPerson;
  onDone: (status: HprStatus) => void;
}) {
  const { t } = useTranslation();
  const schema = z
    .object({
      role: z.enum(ROLES),
      category: z.string().min(1, t("field_required")),
      sub_category: z.string().min(1, t("field_required")),
      state: z.string().min(1, t("field_required")),
      district_code: z.string().min(1, t("field_required")),
      hpr_id: z
        .string()
        .regex(/^[a-z0-9._]{4,}$/i, t("abdm__hpr_id_invalid")),
      email: z.string().email(t("invalid_email")),
      password: z
        .string()
        .regex(
          /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z\d]).{8,}$/,
          t("abdm__hpr_password_rule"),
        ),
      confirm: z.string(),
    })
    .refine((data) => data.password === data.confirm, {
      message: t("password_mismatch"),
      path: ["confirm"],
    });

  const form = useForm<z.infer<typeof schema>>({
    resolver: zodResolver(schema),
    defaultValues: {
      role: "0",
      category: "",
      sub_category: "",
      state: "",
      district_code: "",
      hpr_id: "",
      email: person.email || "",
      password: "",
      confirm: "",
    },
  });
  const role = form.watch("role");
  const category = form.watch("category");
  const stateCode = form.watch("state");

  const { options: categories } = useRegistryOptions("hpr_categories", {
    role,
  });
  const { options: states } = useRegistryOptions("hpr_states");
  const stateId = states.find((s) => s.code === stateCode)?.id;
  const subCategories =
    categories.find((c) => c.code === category)?.sub_categories ?? [];

  const { data: suggestions } = useQuery({
    queryKey: ["abdm_hpr_suggestions", txnId],
    queryFn: query(registryApi.hprCreateSuggestions, {
      body: { txn_id: txnId },
    }),
  });

  const finish = useMutation({
    mutationFn: mutate(registryApi.hprCreateFinish, { silent: true }),
    onSuccess: onDone,
    onError: (error) =>
      toast.error(getAbhaError(error, t("abdm__hpr_create_failed")).msg),
  });

  const onSubmit = (values: z.infer<typeof schema>) =>
    finish.mutate({
      txn_id: txnId,
      hpr_id: values.hpr_id,
      email: values.email,
      password: values.password,
      category: Number(values.category),
      sub_category: Number(values.sub_category),
      state_code: values.state,
      district_code: values.district_code,
      role: Number(values.role),
    });

  return (
    <Form {...form}>
      <form
        onSubmit={form.handleSubmit(onSubmit)}
        className="flex flex-col gap-4"
      >
        <FormField
          control={form.control}
          name="role"
          render={({ field }) => (
            <FormItem>
              <FormLabel>{t("abdm__hpr_role")}</FormLabel>
              <RegistrySelect
                name=""
                options={ROLES.map((code) => ({
                  code,
                  name: t(`abdm__hpr_role__${code}`),
                }))}
                value={field.value}
                onChange={(value) => {
                  field.onChange(value);
                  form.setValue("category", "");
                  form.setValue("sub_category", "");
                }}
              />
              <FormMessage />
            </FormItem>
          )}
        />
        <div className="grid grid-cols-2 gap-4">
          <FormField
            control={form.control}
            name="category"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("abdm__hpr_category")}</FormLabel>
                <RegistrySelect
                  name=""
                  options={categories}
                  value={field.value}
                  onChange={(value) => {
                    field.onChange(value);
                    form.setValue("sub_category", "");
                  }}
                />
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="sub_category"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("abdm__hpr_sub_category")}</FormLabel>
                <RegistrySelect
                  name=""
                  options={subCategories}
                  value={field.value}
                  onChange={field.onChange}
                />
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="state"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("state")}</FormLabel>
                <RegistrySelect
                  name=""
                  options={states}
                  value={field.value}
                  onChange={(value) => {
                    field.onChange(value);
                    form.setValue("district_code", "");
                  }}
                />
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="district_code"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("district")}</FormLabel>
                <RegistrySelect
                  name="hpr_districts"
                  params={{ stateId }}
                  value={field.value}
                  onChange={field.onChange}
                />
                <FormMessage />
              </FormItem>
            )}
          />
        </div>
        <FormField
          control={form.control}
          name="hpr_id"
          render={({ field }) => (
            <FormItem>
              <FormLabel>{t("abdm__hpr_id")}</FormLabel>
              <FormControl>
                <div className="flex items-center gap-2">
                  <Input {...field} />
                  <span className="text-sm text-gray-500">@hpr.abdm</span>
                </div>
              </FormControl>
              {!!suggestions?.results.length && (
                <div className="flex flex-wrap gap-1">
                  {suggestions.results.map((suggestion) => (
                    <Badge
                      key={suggestion}
                      variant="secondary"
                      className="cursor-pointer"
                      onClick={() => form.setValue("hpr_id", suggestion)}
                    >
                      {suggestion}
                    </Badge>
                  ))}
                </div>
              )}
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="email"
          render={({ field }) => (
            <FormItem>
              <FormLabel>{t("email")}</FormLabel>
              <FormControl>
                <Input type="email" {...field} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <div className="grid grid-cols-2 gap-4">
          <FormField
            control={form.control}
            name="password"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("password")}</FormLabel>
                <FormControl>
                  <Input type="password" autoComplete="new-password" {...field} />
                </FormControl>
                <FormDescription>{t("abdm__hpr_password_rule")}</FormDescription>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="confirm"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("confirm_password")}</FormLabel>
                <FormControl>
                  <Input type="password" autoComplete="new-password" {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
        </div>
        <Button type="submit" className="w-fit" disabled={finish.isPending}>
          {t("abdm__hpr_create")}
        </Button>
      </form>
    </Form>
  );
}

export function HprCreateDialog({ open, onOpenChange }: Props) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [step, setStep] = useState<Step>("start");
  const [txnId, setTxnId] = useState("");
  const [url, setUrl] = useState("");
  const [person, setPerson] = useState<HprAadhaarPerson | null>(null);
  const [mobile, setMobile] = useState("");
  const [otp, setOtp] = useState("");

  const reset = () => {
    setStep("start");
    setTxnId("");
    setUrl("");
    setPerson(null);
    setMobile("");
    setOtp("");
  };
  const close = (status?: HprStatus) => {
    if (status) {
      queryClient.setQueryData(HPR_ME_QUERY_KEY, status);
      toast.success(t("abdm__hpr_signed_in"));
    }
    reset();
    onOpenChange(false);
  };
  const onError = (error: Error) =>
    toast.error(getAbhaError(error, t("abdm__hpr_create_failed")).msg);

  const start = useMutation({
    mutationFn: mutate(registryApi.hprCreateStart, { silent: true }),
    onSuccess: (result) => {
      setTxnId(result.txn_id);
      setUrl(result.url);
      setStep("waiting");
      window.open(result.url, "_blank", "noopener,noreferrer");
    },
    onError,
  });

  // The professional authenticates on ABDM's own page; wait until they have.
  const { data: status } = useQuery({
    queryKey: ["abdm_hpr_create_status", txnId],
    queryFn: query(registryApi.hprCreateStatus, { body: { txn_id: txnId } }),
    enabled: step === "waiting" && !!txnId,
    refetchInterval: (state) =>
      state.state.data?.authenticated ? false : POLL_INTERVAL_MS,
  });

  const verify = useMutation({
    mutationFn: mutate(registryApi.hprCreateVerify, { silent: true }),
    onSuccess: (result) => {
      if (result.status === "existing") {
        close(result);
        return;
      }
      setPerson(result);
      setStep("mobile");
    },
    onError,
  });
  const { mutate: verifyTxn } = verify;

  useEffect(() => {
    if (step === "waiting" && status?.authenticated) {
      verifyTxn({ txn_id: txnId });
    }
  }, [step, status?.authenticated, txnId, verifyTxn]);

  const checkMobile = useMutation({
    mutationFn: mutate(registryApi.hprCreateMobile, { silent: true }),
    onSuccess: (result) => setStep(result.verified ? "details" : "mobile_otp"),
    onError,
  });
  const verifyMobileOtp = useMutation({
    mutationFn: mutate(registryApi.hprCreateMobileOtp, { silent: true }),
    onSuccess: () => setStep("details"),
    onError,
  });

  const photo = getAbhaPhotoSrc(person?.photo);

  return (
    <Dialog open={open} onOpenChange={(value) => (value ? null : close())}>
      <DialogContent className="max-w-xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{t("abdm__hpr_create_title")}</DialogTitle>
          <DialogDescription>{t("abdm__hpr_create_desc")}</DialogDescription>
        </DialogHeader>

        {person && (
          <div className="flex items-center gap-3 rounded-md border p-3">
            {photo && (
              <img src={photo} alt="" className="size-12 rounded object-cover" />
            )}
            <div className="flex flex-col text-sm">
              <span className="font-medium">{person.name}</span>
              <span className="text-gray-500">
                {[person.gender, person.birthdate].filter(Boolean).join(" · ")}
              </span>
            </div>
          </div>
        )}

        {step === "start" && (
          <Button
            className="w-fit"
            disabled={start.isPending}
            onClick={() => start.mutate({})}
          >
            <ExternalLinkIcon />
            {t("abdm__hpr_authenticate_aadhaar")}
          </Button>
        )}

        {step === "waiting" && (
          <div className="flex flex-col gap-3 text-sm">
            <div className="flex items-center gap-2">
              <Loader2Icon className="size-4 animate-spin" />
              {t("abdm__hpr_waiting_for_aadhaar")}
            </div>
            <div className="flex gap-2">
              <Button variant="outline" asChild>
                <a href={url} target="_blank" rel="noopener noreferrer">
                  <ExternalLinkIcon />
                  {t("abdm__hpr_open_aadhaar_page")}
                </a>
              </Button>
              <Button variant="ghost" onClick={reset}>
                {t("abdm__start_again")}
              </Button>
            </div>
          </div>
        )}

        {step === "mobile" && (
          <div className="flex flex-col gap-3">
            <span className="text-sm text-gray-600">
              {t("abdm__hpr_mobile_desc")}
            </span>
            <Input
              inputMode="numeric"
              maxLength={10}
              value={mobile}
              placeholder={t("phone_number")}
              onChange={(e) => setMobile(e.target.value.replace(/\D/g, ""))}
            />
            <Button
              className="w-fit"
              disabled={mobile.length !== 10 || checkMobile.isPending}
              onClick={() => checkMobile.mutate({ txn_id: txnId, mobile })}
            >
              {t("continue")}
            </Button>
          </div>
        )}

        {step === "mobile_otp" && (
          <div className="flex flex-col gap-3">
            <span className="text-sm text-gray-600">
              {t("abdm__otp_sent_to", { mobile })}
            </span>
            <Input
              inputMode="numeric"
              autoComplete="one-time-code"
              maxLength={8}
              value={otp}
              placeholder={t("otp")}
              onChange={(e) => setOtp(e.target.value.replace(/\D/g, ""))}
            />
            <Button
              className="w-fit"
              disabled={otp.length < 4 || verifyMobileOtp.isPending}
              onClick={() => verifyMobileOtp.mutate({ txn_id: txnId, otp })}
            >
              {t("verify_otp")}
            </Button>
          </div>
        )}

        {step === "details" && person && (
          <DetailsForm txnId={txnId} person={person} onDone={close} />
        )}
      </DialogContent>
    </Dialog>
  );
}
