import { BadgeCheckIcon, PlusIcon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import { HprCreateDialog } from "@/components/Abdm/registry/HprCreateDialog";
import {
  HPR_ME_QUERY_KEY,
  HprSignInForm,
} from "@/components/Abdm/registry/HprSignInForm";
import { getAbhaError } from "@/components/Abdm/utils";
import { HprStatus } from "@/types/abdm/registry";
import registryApi from "@/types/abdm/registryApi";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { formatDateTime } from "@/Utils/utils";

export function useHprStatus() {
  return useQuery<HprStatus>({
    queryKey: HPR_ME_QUERY_KEY,
    queryFn: query(registryApi.hprMe),
  });
}

function Detail({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex flex-col gap-0.5">
      <span className="text-xs text-gray-500">{label}</span>
      <span className="text-sm font-medium break-all">{value || "-"}</span>
    </div>
  );
}

export function HprSection() {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [creating, setCreating] = useState(false);
  const [signingIn, setSigningIn] = useState(false);
  const { data, isLoading } = useHprStatus();

  const onStatus = (status: HprStatus) =>
    queryClient.setQueryData(HPR_ME_QUERY_KEY, status);
  const onError = (error: Error) =>
    toast.error(getAbhaError(error, t("something_went_wrong")).msg);
  const logout = useMutation({
    mutationFn: mutate(registryApi.hprLogout, { silent: true }),
    onSuccess: onStatus,
    onError,
  });
  const unlink = useMutation({
    mutationFn: mutate(registryApi.hprUnlink, { silent: true }),
    onSuccess: onStatus,
    onError,
  });

  if (isLoading || !data) {
    return <Skeleton className="h-32 w-full" />;
  }
  const profile = data.profile;

  return (
    <div className="flex flex-col gap-4 rounded-lg bg-white px-4 py-5 shadow-sm sm:px-6">
      {profile ? (
        <>
          <div className="flex flex-wrap items-center gap-2">
            <BadgeCheckIcon className="size-5 text-green-600" />
            <span className="font-medium">{profile.name}</span>
            <Badge variant={data.session_active ? "green" : "secondary"}>
              {data.session_active
                ? t("abdm__hpr_session_active")
                : t("abdm__hpr_session_expired")}
            </Badge>
          </div>
          <div className="grid grid-cols-2 gap-4 md:grid-cols-3">
            <Detail label={t("abdm__hpr_id")} value={profile.hpr_id} />
            <Detail
              label={t("abdm__hpr_id_number")}
              value={profile.hpr_id_number}
            />
            <Detail
              label={t("abdm__hpr_category")}
              value={[profile.category, profile.sub_category]
                .filter(Boolean)
                .join(" · ")}
            />
            <Detail
              label={t("abdm__verified_at")}
              value={formatDateTime(profile.verified_at, "DD MMM YYYY, hh:mm A")}
            />
          </div>
          {signingIn && !data.session_active && (
            <HprSignInForm defaultHprId={profile.hpr_id} />
          )}
          <div className="flex flex-wrap gap-2">
            {data.session_active ? (
              <Button
                variant="outline"
                disabled={logout.isPending}
                onClick={() => logout.mutate({})}
              >
                {t("abdm__hpr_sign_out")}
              </Button>
            ) : (
              !signingIn && (
                <Button variant="outline" onClick={() => setSigningIn(true)}>
                  {t("abdm__hpr_sign_in")}
                </Button>
              )
            )}
            <Button
              variant="ghost"
              className="text-red-600"
              disabled={unlink.isPending}
              onClick={() => unlink.mutate({})}
            >
              {t("abdm__hpr_unlink")}
            </Button>
          </div>
        </>
      ) : (
        <>
          <HprSignInForm />
          <div className="flex items-center gap-2 border-t pt-4 text-sm text-gray-600">
            {t("abdm__hpr_no_id")}
            <Button variant="link" onClick={() => setCreating(true)}>
              <PlusIcon />
              {t("abdm__hpr_create")}
            </Button>
          </div>
        </>
      )}
      <HprCreateDialog open={creating} onOpenChange={setCreating} />
    </div>
  );
}
