{"content": "import { useMutation, useQueryClient } from "@tanstack/react-query";
import { SearchIcon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { RegistrySelect } from "@/components/Abdm/registry/RegistrySelect";
import { getAbhaError } from "@/components/Abdm/utils";
import { HealthFacilityLink, HfrFacility } from "@/types/abdm/registry";
import registryApi from "@/types/abdm/registryApi";
import mutate from "@/Utils/request/mutate";

// ABDM shows this name to patients: at most 15 characters, none of %$*#@(~&!).
const HIP_NAME_LIMIT = 15;
const HIP_NAME_FORBIDDEN = /[%$*#@(~&!)]/g;

function suggestHipName(name: string) {
  return name.replace(HIP_NAME_FORBIDDEN, "").trim().slice(0, HIP_NAME_LIMIT);
}

interface Props {
  facilityId: string;
  facilityName: string;
  current: HealthFacilityLink | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function LinkFacilityDialog({
  facilityId,
  facilityName,
  current,
  open,
  onOpenChange,
}: Props) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [search, setSearch] = useState(current?.hfr_id ?? "");
  const [stateCode, setStateCode] = useState("");
  const [selected, setSelected] = useState<HfrFacility | null>(null);
  const [hipName, setHipName] = useState(
    current?.hip_name || suggestHipName(facilityName),
  );
  const [hip, setHip] = useState(current?.is_hip ?? true);
  const [hiu, setHiu] = useState(current?.is_hiu ?? true);

  const searchFacilities = useMutation({
    mutationFn: mutate(registryApi.searchFacilities, { silent: true }),
    onError: (error) =>
      toast.error(getAbhaError(error, t("abdm__hfr_search_failed")).msg),
  });
  const link = useMutation({
    mutationFn: mutate(registryApi.linkFacility, { silent: true }),
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: ["abdm_facility_registry", facilityId],
      });
      toast.success(t("abdm__facility_linked"));
      onOpenChange(false);
    },
    onError: (error) =>
      toast.error(getAbhaError(error, t("abdm__facility_link_failed")).msg),
  });

  const runSearch = () => {
    const value = search.trim();
    const isId = /^IN\d+$/i.test(value);
    setSelected(null);
    searchFacilities.mutate({
      name: isId ? "" : value,
      facility_id: isId ? value.toUpperCase() : "",
      state_code: stateCode,
    });
  };

  const hipNameInvalid =
    !hipName ||
    hipName.length > HIP_NAME_LIMIT ||
    new RegExp(HIP_NAME_FORBIDDEN.source).test(hipName);
  const results = searchFacilities.data?.results ?? [];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{t("abdm__link_facility_title")}</DialogTitle>
          <DialogDescription>{t("abdm__link_facility_desc")}</DialogDescription>
        </DialogHeader>

        <div className="grid grid-cols-1 gap-2 md:grid-cols-[1fr_12rem_auto]">
          <Input
            value={search}
            placeholder={t("abdm__hfr_search_placeholder")}
            onChange={(e) => setSearch(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && runSearch()}
          />
          <RegistrySelect
            name="lgd_states"
            value={stateCode}
            onChange={setStateCode}
            placeholder={t("state")}
          />
          <Button
            variant="outline"
            disabled={(!search.trim() && !stateCode) || searchFacilities.isPending}
            onClick={runSearch}
          >
            <SearchIcon />
            {t("search")}
          </Button>
        </div>

        {searchFacilities.isSuccess && !results.length && (
          <span className="text-sm text-gray-500">
            {t("abdm__hfr_no_results")}
          </span>
        )}
        {!!results.length && (
          <div className="flex max-h-64 flex-col gap-2 overflow-y-auto">
            {results.map((facility) => (
              <button
                type="button"
                key={facility.facility_id}
                onClick={() => setSelected(facility)}
                className={cn(
                  "flex flex-col gap-0.5 rounded-md border p-2 text-left text-sm",
                  selected?.facility_id === facility.facility_id &&
                    "border-primary-500 bg-primary-50",
                )}
              >
                <div className="flex items-center justify-between gap-2">
                  <span className="font-medium">{facility.name}</span>
                  <Badge variant="secondary">{facility.status}</Badge>
                </div>
                <span className="font-mono text-xs">{facility.facility_id}</span>
                <span className="text-xs text-gray-500">
                  {[
                    facility.facility_type,
                    facility.ownership,
                    facility.district,
                    facility.state,
                  ]
                    .filter(Boolean)
                    .join(" · ")}
                </span>
              </button>
            ))}
          </div>
        )}

        <div className="flex flex-col gap-1.5">
          <Label htmlFor="hip-name">{t("abdm__hip_name")}</Label>
          <Input
            id="hip-name"
            value={hipName}
            maxLength={HIP_NAME_LIMIT}
            onChange={(e) => setHipName(e.target.value)}
          />
          <span
            className={cn(
              "text-xs",
              hipNameInvalid ? "text-red-600" : "text-gray-500",
            )}
          >
            {t("abdm__hip_name_rule", { limit: HIP_NAME_LIMIT })}
          </span>
        </div>
        <div className="flex flex-col gap-2">
          <label className="flex items-center gap-2 text-sm">
            <Checkbox checked={hip} onCheckedChange={(v) => setHip(!!v)} />
            {t("abdm__link_as_hip")}
          </label>
          <label className="flex items-center gap-2 text-sm">
            <Checkbox checked={hiu} onCheckedChange={(v) => setHiu(!!v)} />
            {t("abdm__link_as_hiu")}
          </label>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            {t("cancel")}
          </Button>
          <Button
            disabled={
              !(selected || current) || hipNameInvalid || link.isPending
            }
            onClick={() =>
              link.mutate({
                facility: facilityId,
                hfr_id: selected?.facility_id ?? current?.hfr_id ?? "",
                hip_name: hipName.trim(),
                hip,
                hiu,
              })
            }
          >
            {current ? t("abdm__update_link") : t("abdm__link_facility")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
