{"content": "import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import { useTranslation } from "react-i18next";
import * as z from "zod";

import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { MultiSelect } from "@/components/ui/multi-select";

import {
  RegistrySelect,
  useRegistryOptions,
} from "@/components/Abdm/registry/RegistrySelect";
import { FacilityRead } from "@/types/facility/facility";

const schema = z.object({
  facilityName: z.string().min(1),
  stateLGDCode: z.string().min(1),
  districtLGDCode: z.string().min(1),
  subDistrictLGDCode: z.string().min(1),
  facilityRegion: z.string().min(1),
  addressLine1: z.string().min(1),
  addressLine2: z.string(),
  pincode: z.string().regex(/^\d{6}$/),
  latitude: z.string().min(1),
  longitude: z.string().min(1),
  facilityEmailId: z.string().email(),
  facilityContactNumber: z.string().regex(/^\d{10}$/),
  ownershipCode: z.string().min(1),
  ownershipSubTypeCode: z.string().min(1).max(10),
  ownershipSubTypeCode2: z.string(),
  systemOfMedicineCode: z.array(z.string()).min(1),
  typeOfServiceCode: z.array(z.string()).min(1),
  facilityTypeCode: z.string().min(1),
  facilitySubType: z.string(),
  specialityTypeCode: z.string().min(1),
  facilityOperationalStatus: z.string().min(1),
  workingDays: z.array(z.string()).min(1),
  openingHours: z.string().min(1),
});

type Values = z.infer<typeof schema>;

interface SavedBasic {
  facilityName?: string;
  facilityAddressDetails?: Record<string, string>;
  facilityContactInformation?: Record<string, string>;
  timingsOfFacility?: { workingDays: string; openingHours: string }[];
  [key: string]: unknown;
}

function initialValues(facility: FacilityRead, saved?: SavedBasic): Values {
  const address = saved?.facilityAddressDetails ?? {};
  const contact = saved?.facilityContactInformation ?? {};
  const text = (key: string) => (saved?.[key] as string | undefined) ?? "";
  const list = (key: string) => (text(key) ? text(key).split(",") : []);
  return {
    facilityName: saved?.facilityName ?? facility.name,
    stateLGDCode: address.stateLGDCode ?? "",
    districtLGDCode: address.districtLGDCode ?? "",
    subDistrictLGDCode: address.subDistrictLGDCode ?? "",
    facilityRegion: address.facilityRegion ?? "",
    addressLine1: address.addressLine1 ?? facility.address ?? "",
    addressLine2: address.addressLine2 ?? "",
    pincode: address.pincode ?? String(facility.pincode ?? ""),
    latitude: address.latitude ?? String(facility.latitude ?? ""),
    longitude: address.longitude ?? String(facility.longitude ?? ""),
    facilityEmailId: contact.facilityEmailId ?? "",
    facilityContactNumber:
      contact.facilityContactNumber ??
      (facility.phone_number ?? "").replace(/\D/g, "").slice(-10),
    ownershipCode: text("ownershipCode"),
    ownershipSubTypeCode: text("ownershipSubTypeCode"),
    ownershipSubTypeCode2: text("ownershipSubTypeCode2"),
    systemOfMedicineCode: list("systemOfMedicineCode"),
    typeOfServiceCode: list("typeOfServiceCode"),
    facilityTypeCode: text("facilityTypeCode"),
    facilitySubType: text("facilitySubType"),
    specialityTypeCode: text("specialityTypeCode"),
    facilityOperationalStatus: text("facilityOperationalStatus"),
    workingDays: saved?.timingsOfFacility?.map((t) => t.workingDays) ?? [],
    openingHours: saved?.timingsOfFacility?.[0]?.openingHours ?? "",
  };
}

// The HFR's own shape for basic information, built from the form.
function toInformation(values: Values) {
  return {
    facilityName: values.facilityName,
    facilityAddressDetails: {
      country: "India",
      stateLGDCode: values.stateLGDCode,
      districtLGDCode: values.districtLGDCode,
      subDistrictLGDCode: values.subDistrictLGDCode,
      facilityRegion: values.facilityRegion,
      villageCityTownLGDCode: "",
      addressLine1: values.addressLine1,
      addressLine2: values.addressLine2,
      pincode: values.pincode,
      latitude: values.latitude,
      longitude: values.longitude,
    },
    facilityContactInformation: {
      facilityEmailId: values.facilityEmailId,
      facilityContactNumber: values.facilityContactNumber,
      websiteLink: "",
      facilityLandlineNumber: "",
      facilityStdCode: "",
    },
    ownershipCode: values.ownershipCode,
    ownershipSubTypeCode: values.ownershipSubTypeCode.toUpperCase(),
    ownershipSubTypeCode2: values.ownershipSubTypeCode2,
    systemOfMedicineCode: values.systemOfMedicineCode.join(","),
    typeOfServiceCode: values.typeOfServiceCode.join(","),
    facilityTypeCode: values.facilityTypeCode,
    facilitySubType: values.facilitySubType,
    specialityTypeCode: values.specialityTypeCode,
    facilityOperationalStatus: values.facilityOperationalStatus,
    facilityUploads: {
      facilityBoardPhoto: { name: "", value: "" },
      facilityBuildingPhoto: { name: "", value: "" },
    },
    timingsOfFacility: values.workingDays.map((day) => ({
      workingDays: day,
      openingHours: values.openingHours,
    })),
    abdmCompliantSoftware: [{ existingSoftwares: [], anyOther: "CARE" }],
  };
}

interface Props {
  facility: FacilityRead;
  saved?: SavedBasic;
  isPending: boolean;
  onSubmit: (information: Record<string, unknown>) => void;
}

export function HfrBasicForm({ facility, saved, isPending, onSubmit }: Props) {
  const { t } = useTranslation();
  const form = useForm<Values>({
    resolver: zodResolver(schema),
    defaultValues: initialValues(facility, saved),
  });
  const [stateCode, districtCode, ownership, ownershipSubType, medicines] =
    form.watch([
      "stateLGDCode",
      "districtLGDCode",
      "ownershipCode",
      "ownershipSubTypeCode",
      "systemOfMedicineCode",
    ]);
  const facilityType = form.watch("facilityTypeCode");

  const { options: states } = useRegistryOptions("lgd_states");
  const districts = states.find((s) => s.code === stateCode)?.districts ?? [];
  const { options: medicineOptions } = useRegistryOptions("master_data", {
    type: "MEDICINE",
  });
  const { options: serviceOptions } = useRegistryOptions("master_data", {
    type: "TYPE-SERVICE",
  });
  const { options: dayOptions } = useRegistryOptions("master_data", {
    type: "DAYS-OF-OPERATION",
  });
  const { options: ownerSubTypes } = useRegistryOptions("owner_sub_types", {
    ownershipCode: ownership,
    ownerSubtypeCode: ownershipSubType?.toUpperCase(),
  });

  const select = (
    name: keyof Values,
    label: string,
    master: string,
    params?: Record<string, string | undefined>,
  ) => (
    <FormField
      control={form.control}
      name={name}
      render={({ field }) => (
        <FormItem>
          <FormLabel>{label}</FormLabel>
          <RegistrySelect
            name={master}
            params={params}
            value={field.value as string}
            onChange={field.onChange}
          />
          <FormMessage />
        </FormItem>
      )}
    />
  );
  const text = (name: keyof Values, label: string, description?: string) => (
    <FormField
      control={form.control}
      name={name}
      render={({ field }) => (
        <FormItem>
          <FormLabel>{label}</FormLabel>
          <FormControl>
            <Input {...field} value={field.value as string} />
          </FormControl>
          {description && <FormDescription>{description}</FormDescription>}
          <FormMessage />
        </FormItem>
      )}
    />
  );
  const multi = (
    name: "systemOfMedicineCode" | "typeOfServiceCode" | "workingDays",
    label: string,
    options: { code: string; name: string }[],
  ) => (
    <FormField
      control={form.control}
      name={name}
      render={({ field }) => (
        <FormItem>
          <FormLabel>{label}</FormLabel>
          <MultiSelect
            options={options.map((o) => ({ label: o.name, value: o.code }))}
            value={field.value}
            onValueChange={field.onChange}
            placeholder={t("select")}
          />
          <FormMessage />
        </FormItem>
      )}
    />
  );

  return (
    <Form {...form}>
      <form
        onSubmit={form.handleSubmit((values) => onSubmit(toInformation(values)))}
        className="flex flex-col gap-4"
      >
        {text("facilityName", t("abdm__hfr_facility_name"))}
        <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
          <FormField
            control={form.control}
            name="stateLGDCode"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("state")}</FormLabel>
                <RegistrySelect
                  name=""
                  options={states}
                  value={field.value}
                  onChange={(value) => {
                    field.onChange(value);
                    form.setValue("districtLGDCode", "");
                    form.setValue("subDistrictLGDCode", "");
                  }}
                />
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="districtLGDCode"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("district")}</FormLabel>
                <RegistrySelect
                  name=""
                  options={districts}
                  value={field.value}
                  onChange={(value) => {
                    field.onChange(value);
                    form.setValue("subDistrictLGDCode", "");
                  }}
                />
                <FormMessage />
              </FormItem>
            )}
          />
          {select(
            "subDistrictLGDCode",
            t("abdm__sub_district"),
            "lgd_sub_districts",
            { districtCode },
          )}
        </div>
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
          {text("addressLine1", t("abdm__address_line_1"))}
          {text("addressLine2", t("abdm__address_line_2"))}
        </div>
        <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
          {select("facilityRegion", t("abdm__hfr_region"), "master_data", {
            type: "FACILITY-REGION",
          })}
          {text("pincode", t("pincode"))}
          {text("latitude", t("latitude"))}
          {text("longitude", t("longitude"))}
        </div>
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
          {text("facilityEmailId", t("email"))}
          {text("facilityContactNumber", t("phone_number"))}
        </div>
        <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
          {select("ownershipCode", t("abdm__hfr_ownership"), "master_data", {
            type: "OWNER",
          })}
          {text(
            "ownershipSubTypeCode",
            t("abdm__hfr_ownership_sub_type"),
            t("abdm__hfr_ownership_sub_type_desc"),
          )}
          {ownerSubTypes.length > 0 &&
            select(
              "ownershipSubTypeCode2",
              t("abdm__hfr_ownership_sub_type_2"),
              "owner_sub_types",
              {
                ownershipCode: ownership,
                ownerSubtypeCode: ownershipSubType?.toUpperCase(),
              },
            )}
        </div>
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
          {multi(
            "systemOfMedicineCode",
            t("abdm__hfr_system_of_medicine"),
            medicineOptions,
          )}
          {multi(
            "typeOfServiceCode",
            t("abdm__hfr_type_of_service"),
            serviceOptions,
          )}
        </div>
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
          {select("facilityTypeCode", t("abdm__hfr_facility_type"), "facility_types", {
            ownershipCode: ownership,
            systemOfMedicineCode: medicines[0],
          })}
          {select(
            "facilitySubType",
            t("abdm__hfr_facility_sub_type"),
            "facility_sub_types",
            { facilityTypeCode: facilityType },
          )}
          {select(
            "specialityTypeCode",
            t("abdm__hfr_speciality_type"),
            "master_data",
            { type: "SPECIALITY-TYPE" },
          )}
          {select(
            "facilityOperationalStatus",
            t("abdm__hfr_operational_status"),
            "master_data",
            { type: "FAC-STATUS" },
          )}
        </div>
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
          {multi("workingDays", t("abdm__hfr_working_days"), dayOptions)}
          {text(
            "openingHours",
            t("abdm__hfr_opening_hours"),
            t("abdm__hfr_opening_hours_desc"),
          )}
        </div>
        <Button type="submit" className="w-fit" disabled={isPending}>
          {t("abdm__hfr_save_step")}
        </Button>
      </form>
    </Form>
  );
}
