import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";

import { RegistrySelect } from "@/components/Abdm/registry/RegistrySelect";

const SERVICES = [
  "hasDialysisCenter",
  "hasPharmacy",
  "hasBloodBank",
  "hasCathLab",
  "hasDiagnosticLab",
  "hasImagingCenter",
] as const;

interface Props {
  saved?: { generalInformation?: Record<string, string> };
  isPending: boolean;
  onSubmit: (information: Record<string, unknown>) => void;
}

export function HfrAdditionalForm({ saved, isPending, onSubmit }: Props) {
  const { t } = useTranslation();
  const [values, setValues] = useState<Record<string, string>>(
    Object.fromEntries(
      SERVICES.map((key) => [key, saved?.generalInformation?.[key] ?? ""]),
    ),
  );
  const complete = SERVICES.every((key) => values[key]);

  return (
    <div className="flex flex-col gap-4">
      <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
        {SERVICES.map((key) => (
          <div key={key} className="flex flex-col gap-1.5">
            <Label>{t(`abdm__hfr_${key}`)}</Label>
            <RegistrySelect
              name="master_data"
              params={{ type: "GENERAL-INFO-OPTIONS" }}
              value={values[key]}
              onChange={(value) => setValues({ ...values, [key]: value })}
            />
          </div>
        ))}
      </div>
      <Button
        className="w-fit"
        disabled={!complete || isPending}
        onClick={() =>
          onSubmit({
            linkedProgramIds: {},
            generalInformation: { ...values, servicesByImagingCenter: [] },
          })
        }
      >
        {t("abdm__hfr_save_step")}
      </Button>
    </div>
  );
}
