{"content": "import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { MultiSelect } from "@/components/ui/multi-select";

import { useRegistryOptions } from "@/components/Abdm/registry/RegistrySelect";

const INFRASTRUCTURE = [
  "totalNumberOfBeds",
  "countIPDBedsWithoutOxygen",
  "countIPDBedsWithOxygen",
  "countICUBedsWithVentilators",
  "countICUBedsWithoutVentilators",
  "countHDUBedsWithVentilators",
  "countHDUBedsWithoutVentilators",
  "totalNumberOfVentilators",
  "countDayCareBedsWithoutOxygen",
  "countDayCareBedsWithOxygen",
  "countDentalChairs",
] as const;

interface SavedDetailed {
  specialities?: { systemOfMedicineCode: string; specialities: string[] }[];
  medicalInfrastructure?: Record<string, number>;
}

function SpecialitiesSelect({
  systemOfMedicine,
  value,
  onChange,
}: {
  systemOfMedicine: string;
  value: string[];
  onChange: (value: string[]) => void;
}) {
  const { t } = useTranslation();
  const { options } = useRegistryOptions("specialities", {
    systemOfMedicineCode: systemOfMedicine,
  });
  const { options: medicines } = useRegistryOptions("master_data", {
    type: "MEDICINE",
  });
  const name =
    medicines.find((m) => m.code === systemOfMedicine)?.name ?? systemOfMedicine;
  return (
    <div className="flex flex-col gap-1.5">
      <Label>{t("abdm__hfr_specialities_for", { name })}</Label>
      <MultiSelect
        options={options.map((o) => ({ label: o.name, value: o.code }))}
        value={value}
        onValueChange={onChange}
        placeholder={t("select")}
      />
    </div>
  );
}

interface Props {
  systemsOfMedicine: string[];
  saved?: SavedDetailed;
  isPending: boolean;
  onSubmit: (information: Record<string, unknown>) => void;
}

export function HfrDetailedForm({
  systemsOfMedicine,
  saved,
  isPending,
  onSubmit,
}: Props) {
  const { t } = useTranslation();
  const [specialities, setSpecialities] = useState<Record<string, string[]>>(
    Object.fromEntries(
      systemsOfMedicine.map((code) => [
        code,
        saved?.specialities?.find((s) => s.systemOfMedicineCode === code)
          ?.specialities ?? [],
      ]),
    ),
  );
  const [counts, setCounts] = useState<Record<string, string>>(
    Object.fromEntries(
      INFRASTRUCTURE.map((key) => [
        key,
        String(saved?.medicalInfrastructure?.[key] ?? 0),
      ]),
    ),
  );
  const countsValid = INFRASTRUCTURE.every((key) =>
    /^\d+$/.test(counts[key] ?? ""),
  );

  return (
    <div className="flex flex-col gap-4">
      {systemsOfMedicine.map((code) => (
        <SpecialitiesSelect
          key={code}
          systemOfMedicine={code}
          value={specialities[code] ?? []}
          onChange={(value) =>
            setSpecialities({ ...specialities, [code]: value })
          }
        />
      ))}
      <div className="grid grid-cols-2 gap-4 md:grid-cols-3">
        {INFRASTRUCTURE.map((key) => (
          <div key={key} className="flex flex-col gap-1.5">
            <Label htmlFor={`hfr-${key}`}>{t(`abdm__hfr_${key}`)}</Label>
            <Input
              id={`hfr-${key}`}
              inputMode="numeric"
              value={counts[key]}
              onChange={(e) =>
                setCounts({ ...counts, [key]: e.target.value.replace(/\D/g, "") })
              }
            />
          </div>
        ))}
      </div>
      <Button
        className="w-fit"
        disabled={!countsValid || isPending}
        onClick={() =>
          onSubmit({
            specialities: systemsOfMedicine.map((code) => ({
              systemOfMedicineCode: code,
              isSpecializationAvalaible: specialities[code]?.length ? "Y" : "N",
              specialities: specialities[code] ?? [],
            })),
            medicalInfrastructure: Object.fromEntries(
              INFRASTRUCTURE.map((key) => [key, Number(counts[key])]),
            ),
          })
        }
      >
        {t("abdm__hfr_save_step")}
      </Button>
    </div>
  );
}
