{"content": "import { useMutation, useQueryClient } from "@tanstack/react-query";
import { AlertCircleIcon, CheckCircle2Icon, CircleIcon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

import { HfrAdditionalForm } from "@/components/Abdm/registry/HfrAdditionalForm";
import { HfrBasicForm } from "@/components/Abdm/registry/HfrBasicForm";
import { HfrDetailedForm } from "@/components/Abdm/registry/HfrDetailedForm";
import { useHprStatus } from "@/components/Abdm/registry/HprSection";
import { HprSignInForm } from "@/components/Abdm/registry/HprSignInForm";
import { getAbhaError } from "@/components/Abdm/utils";
import {
  HfrRegistration,
  HfrRegistrationStatus,
  HfrRegistrationStep,
} from "@/types/abdm/registry";
import registryApi from "@/types/abdm/registryApi";
import { FacilityRead } from "@/types/facility/facility";
import mutate from "@/Utils/request/mutate";

const STEPS: HfrRegistrationStep[] = ["basic", "additional", "detailed", "submit"];
// The step a registration in each status goes on to.
const NEXT_STEP: Record<HfrRegistrationStatus, HfrRegistrationStep | null> = {
  draft: "basic",
  basic: "additional",
  additional: "detailed",
  detailed: "submit",
  submitted: null,
};

interface Props {
  facility: FacilityRead;
  registration: HfrRegistration | undefined;
}

export function HfrRegistrationCard({ facility, registration }: Props) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const { data: hpr } = useHprStatus();
  const [editing, setEditing] = useState<HfrRegistrationStep | null>(null);
  const queryKey = ["abdm_facility_registry", facility.id];

  const onError = (error: Error) =>
    toast.error(getAbhaError(error, t("abdm__hfr_step_failed")).msg);
  const start = useMutation({
    mutationFn: mutate(registryApi.startRegistration, { silent: true }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
    onError,
  });
  const step = useMutation({
    mutationFn: mutate(registryApi.registrationStep, { silent: true }),
    onSuccess: () => {
      setEditing(null);
      toast.success(t("abdm__hfr_step_saved"));
      queryClient.invalidateQueries({ queryKey });
    },
    onError: (error) => {
      queryClient.invalidateQueries({ queryKey });
      onError(error);
    },
  });

  const signedIn = !!hpr?.session_active;
  const nextStep = registration ? NEXT_STEP[registration.status] : null;
  const current = editing ?? nextStep;
  const done = (s: HfrRegistrationStep) =>
    !!registration?.responses[s] && s !== current;
  const save = (s: HfrRegistrationStep) => (information?: Record<string, unknown>) =>
    registration &&
    step.mutate({ registration: registration.id, step: s, information });
  const systemsOfMedicine = String(
    registration?.data.basic?.systemOfMedicineCode ?? "",
  )
    .split(",")
    .filter(Boolean);

  return (
    <Card>
      <CardHeader className="flex flex-row flex-wrap items-start justify-between gap-2 space-y-0">
        <div className="flex flex-col gap-1.5">
          <CardTitle className="flex items-center gap-2 text-lg">
            {t("abdm__hfr_register_title")}
            {registration && (
              <Badge
                variant={
                  registration.status === "submitted" ? "green" : "secondary"
                }
              >
                {t(`abdm__hfr_status__${registration.status}`)}
              </Badge>
            )}
          </CardTitle>
          <CardDescription>{t("abdm__hfr_register_desc")}</CardDescription>
        </div>
        {!registration && signedIn && (
          <Button
            variant="outline_primary"
            size="sm"
            disabled={start.isPending}
            onClick={() => start.mutate({ facility: facility.id })}
          >
            {t("abdm__hfr_start_registration")}
          </Button>
        )}
      </CardHeader>
      <CardContent className="flex flex-col gap-4">
        {registration?.status !== "submitted" && !signedIn && (
          <div className="flex flex-col gap-3 rounded-md border p-3">
            <span className="text-sm text-gray-700">
              {t("abdm__hfr_needs_hpr")}
            </span>
            <HprSignInForm defaultHprId={hpr?.profile?.hpr_id} />
          </div>
        )}

        {registration?.error && (
          <div className="flex gap-2 rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-900">
            <AlertCircleIcon className="mt-0.5 size-4 shrink-0" />
            <span>
              {registration.error.code ? `${registration.error.code}: ` : ""}
              {registration.error.message}
            </span>
          </div>
        )}

        {registration?.status === "submitted" && (
          <div className="flex flex-col gap-1 text-sm">
            <span>
              {t("abdm__hfr_submitted", {
                id: registration.hfr_id || registration.tracking_id,
              })}
            </span>
            <span className="text-gray-500">{t("abdm__hfr_submitted_desc")}</span>
          </div>
        )}

        {registration && registration.status !== "submitted" && (
          <div className="flex flex-col gap-3">
            {STEPS.map((s) => (
              <div key={s} className="flex flex-col gap-3 rounded-md border p-3">
                <div className="flex items-center justify-between gap-2">
                  <span
                    className={cn(
                      "flex items-center gap-2 text-sm font-medium",
                      s !== current && !done(s) && "text-gray-400",
                    )}
                  >
                    {done(s) ? (
                      <CheckCircle2Icon className="size-4 text-green-600" />
                    ) : (
                      <CircleIcon className="size-4" />
                    )}
                    {t(`abdm__hfr_step__${s}`)}
                  </span>
                  {done(s) && s !== "submit" && signedIn && (
                    <Button variant="link" size="sm" onClick={() => setEditing(s)}>
                      {t("edit")}
                    </Button>
                  )}
                </div>
                {s === current && signedIn && (
                  <>
                    {s === "basic" && (
                      <HfrBasicForm
                        facility={facility}
                        saved={registration.data.basic}
                        isPending={step.isPending}
                        onSubmit={save("basic")}
                      />
                    )}
                    {s === "additional" && (
                      <HfrAdditionalForm
                        saved={registration.data.additional}
                        isPending={step.isPending}
                        onSubmit={save("additional")}
                      />
                    )}
                    {s === "detailed" && (
                      <HfrDetailedForm
                        systemsOfMedicine={systemsOfMedicine}
                        saved={registration.data.detailed}
                        isPending={step.isPending}
                        onSubmit={save("detailed")}
                      />
                    )}
                    {s === "submit" && (
                      <Button
                        className="w-fit"
                        disabled={step.isPending}
                        onClick={() => save("submit")()}
                      >
                        {t("abdm__hfr_submit")}
                      </Button>
                    )}
                  </>
                )}
              </div>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}
