{"content": "import { useQuery } from "@tanstack/react-query";
import { CloudOffIcon, LinkIcon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { EmptyState } from "@/components/ui/empty-state";

import { TableSkeleton } from "@/components/Common/SkeletonLoading";

import { HfrRegistrationCard } from "@/components/Abdm/registry/HfrRegistrationCard";
import { LinkFacilityDialog } from "@/components/Abdm/registry/LinkFacilityDialog";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";
import { FacilityRegistryStatus } from "@/types/abdm/registry";
import registryApi from "@/types/abdm/registryApi";
import query from "@/Utils/request/query";
import { formatDateTime } from "@/Utils/utils";

function Detail({ label, value }: { label: string; value: React.ReactNode }) {
  return (
    <div className="flex flex-col gap-1">
      <span className="text-xs text-gray-500">{label}</span>
      <span className="text-sm font-medium break-all">{value || "-"}</span>
    </div>
  );
}

export function FacilityAbdmSettings({ facilityId }: { facilityId: string }) {
  const { t } = useTranslation();
  const { facility } = useCurrentFacility();
  const [linking, setLinking] = useState(false);

  const { data, isLoading } = useQuery<FacilityRegistryStatus>({
    queryKey: ["abdm_facility_registry", facilityId],
    queryFn: query(registryApi.facilityStatus, {
      queryParams: { facility: facilityId },
    }),
  });

  if (isLoading || !data || !facility) {
    return <TableSkeleton count={3} />;
  }
  const link = data.health_facility;

  return (
    <div className="flex flex-col gap-4">
      <Card>
        <CardHeader className="flex flex-row flex-wrap items-start justify-between gap-2 space-y-0">
          <div className="flex flex-col gap-1.5">
            <CardTitle className="flex items-center gap-2 text-lg">
              {t("abdm__hfr_link_title")}
              {link ? (
                <Badge variant={link.active ? "green" : "secondary"}>
                  {link.active ? t("abdm__linked") : t("abdm__inactive")}
                </Badge>
              ) : (
                <Badge variant="secondary">{t("abdm__not_linked")}</Badge>
              )}
            </CardTitle>
            <CardDescription>
              {t("abdm__hfr_link_desc", { bridge: data.bridge_id })}
            </CardDescription>
          </div>
          <Button
            variant="outline_primary"
            size="sm"
            onClick={() => setLinking(true)}
          >
            <LinkIcon />
            {link ? t("abdm__update_link") : t("abdm__link_facility")}
          </Button>
        </CardHeader>
        <CardContent>
          {link ? (
            <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
              <Detail label={t("abdm__hfr_id")} value={link.hfr_id} />
              <Detail
                label={t("abdm__hfr_name")}
                value={link.hfr.name ?? ""}
              />
              <Detail label={t("abdm__hip_name")} value={link.hip_name} />
              <Detail
                label={t("abdm__linked_at")}
                value={
                  link.linked_at
                    ? formatDateTime(link.linked_at, "DD MMM YYYY, hh:mm A")
                    : ""
                }
              />
              <Detail
                label={t("abdm__roles")}
                value={
                  <span className="flex gap-1">
                    {link.is_hip && <Badge variant="blue">HIP</Badge>}
                    {link.is_hiu && <Badge variant="blue">HIU</Badge>}
                  </span>
                }
              />
              <Detail
                label={t("abdm__hfr_status")}
                value={link.hfr.status ?? ""}
              />
            </div>
          ) : (
            <EmptyState
              icon={<CloudOffIcon />}
              title={t("abdm__facility_not_registered")}
              description={t("abdm__hfr_not_linked_desc")}
            />
          )}
        </CardContent>
      </Card>

      <HfrRegistrationCard
        facility={facility}
        registration={data.registrations[0]}
      />

      {linking && (
        <LinkFacilityDialog
          facilityId={facilityId}
          facilityName={facility.name}
          current={link}
          open={linking}
          onOpenChange={setLinking}
        />
      )}
    </div>
  );
}
