{"filePath": "/Users/rithviknishad/ohc.network/care/care/abdm/service/m4.py", "newString": "def token_claims(token):
    """Read who an HPR token stands for; it came straight from the registry."""
    try:
        payload = token.split(".")[1]
        return json.loads(b64decode(payload + "=" * (-len(payload) % 4), altchars=b"-_"))
    except (IndexError, ValueError, TypeError):
        return {}


def professional_details(hpr_id):
    # The profile-by-token call refuses sandbox tokens; this one answers.
    return call("GET", f"/v1/account/user-details/{hpr_id}").json()


def sign_in(user, body):
    """Keep the HPR token a sign in returned and record who it belongs to."""
    token = body.get("token")
    if not token:
        msg = "The registry did not return a session"
        raise RegistryError(msg)
    claims = token_claims(token)
    hpr_id_number = claims.get("hprIdNumber") or body.get("hprIdNumber")
    hpr_id = claims.get("hprId") or body.get("hprId")
    if not hpr_id_number or not hpr_id:
        msg = "The registry did not say which professional signed in"
        raise RegistryError(msg)
    info = professional_details(hpr_id)
    if info.get("hprIdNumber") and info["hprIdNumber"] != hpr_id_number:
        msg = "The registry returned a different professional"
        raise RegistryError(msg)
    with transaction.atomic():
        if (
            HprProfile.objects.filter(hpr_id_number=hpr_id_number)
            .exclude(user=user)
            .exists()
        ):
            msg = "This HPR id is linked to another Care user"
            raise RegistryError(msg)
        profile, _ = HprProfile.objects.update_or_create(
            user=user,
            defaults={
