{"content": "import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";

import { getAbhaError } from "@/components/Abdm/utils";
import { HealthFacilityLink } from "@/types/abdm/registry";
import registryApi from "@/types/abdm/registryApi";
import mutate from "@/Utils/request/mutate";

interface Props {
  facilityId: string;
  link: HealthFacilityLink;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function UnlinkFacilityDialog({
  facilityId,
  link,
  open,
  onOpenChange,
}: Props) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [deactivateBridge, setDeactivateBridge] = useState(true);

  const unlink = useMutation({
    mutationFn: mutate(registryApi.unlinkFacility, { silent: true }),
    onSuccess: (result: { health_facility: HealthFacilityLink | null }) => {
      queryClient.invalidateQueries({
        queryKey: ["abdm_facility_registry", facilityId],
      });
      toast.success(
        result.health_facility
          ? t("abdm__facility_unlinked_kept")
          : t("abdm__facility_unlinked"),
      );
      onOpenChange(false);
    },
    onError: (error) =>
      toast.error(getAbhaError(error, t("abdm__facility_unlink_failed")).msg),
  });

  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{t("abdm__unlink_facility_title")}</AlertDialogTitle>
          <AlertDialogDescription>
            {t("abdm__unlink_facility_desc", { id: link.hfr_id })}
          </AlertDialogDescription>
        </AlertDialogHeader>
        <label className="flex items-start gap-2 text-sm">
          <Checkbox
            className="mt-0.5"
            checked={deactivateBridge}
            onCheckedChange={(value) => setDeactivateBridge(!!value)}
          />
          <span>{t("abdm__unlink_deactivate_bridge")}</span>
        </label>
        <AlertDialogFooter>
          <AlertDialogCancel>{t("cancel")}</AlertDialogCancel>
          <Button
            variant="destructive"
            disabled={unlink.isPending}
            onClick={() =>
              unlink.mutate({
                facility: facilityId,
                deactivate_bridge: deactivateBridge,
              })
            }
          >
            {t("abdm__unlink")}
          </Button>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}
